export default ":\\n    def test_insert_many_success(self, component_with_collection, mock_collection):\\n        mock_result = Mock()\\n        mock_result.inserted_ids = [\\\"id-1\\\", \\\"id-2\\\", \\\"id-3\\\"]\\n        mock_collection.insert_many.return_value = mock_result\\n\\n        component_with_collection.operation = OP_INSERT_MANY\\n        component_with_collection.documents = [{\\\"a\\\": 1}, {\\\"a\\\": 2}, {\\\"a\\\": 3}]\\n        component_with_collection.ordered = True\\n\\n        result = component_with_collection.run_operation()\\n\\n        mock_collection.insert_many.assert_called_once_with([{\\\"a\\\": 1}, {\\\"a\\\": 2}, {\\\"a\\\": 3}], ordered=True)\\n        assert result[0].data == {\\n            \\\"inserted_ids\\\": [\\\"id-1\\\", \\\"id-2\\\", \\\"id-3\\\"],\\n            \\\"inserted_count\\\": 3,\\n        }\\n\\n    def test_insert_many_empty_rejected(self, component_with_collection):\\n        component_with_collection.operation = OP_INSERT_MANY\\n        component_with_collection.documents = []\\n\\n        with pytest.raises(ValueError, match=\\\"non-empty list\\\"):\\n            component_with_collection.run_operation()\\n\\n\\nclass TestUpdateOperations:\\n    def test_update_one_requires_filter(self, component_with_collection):\\n        component_with_collection.operation = OP_UPDATE_ONE\\n        component_with_collection.filter_query = {}\\n        component_with_collection.update = {\\\"$set\\\": {\\\"status\\\": \\\"x\\\"}}\\n\\n        with pytest.raises(ValueError, match=\\\"filter_query\\\"):\\n            component_with_collection.run_operation()\\n\\n    def test_update_one_requires_update_doc(self, component_with_collection):\\n        component_with_collection.operation = OP_UPDATE_ONE\\n        component_with_collection.filter_query = {\\\"_id\\\": \\\"1\\\"}\\n        component_with_collection.update = {}\\n\\n        with pytest.raises(ValueError, match=\\\"update\\\"):\\n            component_with_collection.run_operation()\\n\\n    def test_update_one_success(self, component_with_collection, mock_collection):\\n        mock_result = Mock()\\n        mock_result.matched_count = 1\\n        mock_result.modified_count = 1\\n        mock_result.upserted_id = None\\n        mock_collection.update_one.return_value = mock_result\\n\\n        component_with_collection.operation = OP_UPDATE_ONE\\n        component_with_collection.filter_query = {\\\"_id\\\": \\\"1\\\"}\\n        component_with_collection.update = {\\\"$set\\\": {\\\"status\\\": \\\"active\\\"}}\\n        component_with_collection.upsert = True\\n\\n        result = component_with_collection.run_operation()\\n\\n        mock_collection.update_one.assert_called_once_with({\\\"_id\\\": \\\"1\\\"}, {\\\"$set\\\": {\\\"status\\\": \\\"active\\\"}}, upsert=True)\\n        assert result[0].data[\\\"matched_count\\\"] == 1\\n        assert result[0].data[\\\"modified_count\\\"] == 1\\n        assert result[0].data[\\\"upserted_id\\\"] is None\\n\\n    def test_update_many_success(self, component_with_collection, mock_collection):\\n        mock_result = Mock()\\n        mock_result.matched_count = 5\\n        mock_result.modified_count = 5\\n        mock_result.upserted_id = None\\n        mock_collection.update_many.return_value = mock_result\\n\\n        component_with_collection.operation = OP_UPDATE_MANY\\n        component_with_collection.filter_query = {\\\"active\\\": True}\\n        component_with_collection.update = {\\\"$inc\\\": {\\\"version\\\": 1}}\\n\\n        result = component_with_collection.run_operation()\\n\\n        mock_collection.update_many.assert_called_once_with({\\\"active\\\": True}, {\\\"$inc\\\": {\\\"version\\\": 1}}, upsert=False)\\n        assert result[0].data[\\\"modified_count\\\"] == 5\\n\\n\\nclass TestDeleteOperations:\\n    def test_delete_one(self, component_with_collection, mock_collection):\\n        mock_result = Mock()\\n        mock_result.deleted_count = 1\\n        mock_collection.delete_one.return_value = mock_result\\n\\n        component_with_collection.operation = OP_DELETE_ONE\\n        component_with_collection.filter_query = {\\\"_id\\\": \\\"1\\\"}\\n\\n        result = component_with_collection.run_operation()\\n\\n        mock_collection.delete_one.assert_called_once_with({\\\"_id\\\": \\\"1\\\"})\\n        assert result[0].data == {\\\"deleted_count\\\": 1}\\n\\n    def test_delete_many(self, component_with_collection, mock_collection):\\n        mock_result = Mock()\\n        mock_result.deleted_count = 42\\n        mock_collection.delete_many.return_value = mock_result\\n\\n        component_with_collection.operation = OP_DELETE_MANY\\n        component_with_collection.filter_query = {\\\"archived\\\": True}\\n\\n        result = component_with_collection.run_operation()\\n\\n        mock_collection.delete_many.assert_called_once_with({\\\"archived\\\": True})\\n        assert result[0].data == {\\\"deleted_count\\\": 42}\\n\\n    def test_delete_requires_filter(self, component_with_collection):\\n        component_with_collection.operation = OP_DELETE_ONE\\n        component_with_collection.filter_query = {}\\n\\n        with pytest.raises(ValueError, match=\\\"filter_query\\\"):\\n            component_with_collection.run_operation()\\n\\n\\nclass TestCountOperations:\\n    def test_count_documents(self, component_with_collection, mock_collection):\\n        mock_collection.count_documents.return_value = 17\\n\\n        component_with_collection.operation = OP_COUNT\\n        component_with_collection.filter_query = {\\\"active\\\": True}\\n        component_with_collection.upper_bound = 500\\n\\n        result = component_with_collection.run_operation()\\n\\n        mock_collection.count_documents.assert_called_once_with({\\\"active\\\": True}, upper_bound=500)\\n        assert result[0].data == {\\\"count\\\": 17, \\\"upper_bound\\\": 500}\\n\\n    def test_estimated_count(self, component_with_collection, mock_collection):\\n        mock_collection.estimated_document_count.return_value = 1_000_000\\n\\n        component_with_collection.operation = OP_ESTIMATED_COUNT\\n\\n        result = component_with_collection.run_operation()\\n\\n        mock_collection.estimated_document_count.assert_called_once_with()\\n        assert result[0].data == {\\\"estimated_count\\\": 1_000_000}\\n\\n\\n# ----------------------------------------------------------------------\\n# DataFrame output\\n# ----------------------------------------------------------------------\\n\\n\\nclass TestDataFrameOutput:\\n    def test_as_dataframe_from_find(self, component_with_collection, mock_collection):\\n        mock_collection.find.return_value = iter(\\n            [\\n                {\\\"name\\\": \\\"Ada\\\", \\\"age\\\": 36},\\n                {\\\"name\\\": \\\"Grace\\\", \\\"age\\\": 85},\\n            ]\\n        )\\n        component_with_collection.operation = OP_FIND\\n\\n        df = component_with_collection.as_dataframe()\\n\\n        assert len(df) == 2\\n        assert set(df.columns) >= {\\\"name\\\", \\\"age\\\"}\\n\\n    def test_as_dataframe_empty(self, component_with_collection, mock_collection):\\n        mock_collection.find.return_value = iter([])\\n        component_with_collection.operation = OP_FIND\\n\\n        df = component_with_collection.as_dataframe()\\n\\n        assert len(df) == 0\\n\\n\\n# ----------------------------------------------------------------------\\n# Error propagation\\n# ----------------------------------------------------------------------\\n\\n\\nclass TestErrorPropagation:\\n    def test_unknown_operation_raises(self, component_with_collection):\\n        component_with_collection.operation = \\\"Destroy The Universe\\\"\\n\\n        with pytest.raises(ValueError, match=\\\"Unsupported operation\\\"):\\n            component_with_collection.run_operation()\\n\\n    def test_astrapy_errors_wrapped(self, component_with_collection, mock_collection):\\n        mock_collection.find.side_effect = RuntimeError(\\\"boom\\\")\\n        component_with_collection.operation = OP_FIND\\n\\n        with pytest.raises(ValueError, match=\\\"Astra DB Data API 'Find' failed: boom\\\"):\\n            component_with_collection.run_operation()\\n\\n    def test_missing_collection_name_raises(self, component):\\n        component.collection_name = \\\"\\\"\\n        # Bypass the patched _get_collection to exercise the real path.\\n        with pytest.raises(ValueError, match=\\\"No collection selected\\\"):\\n            component._get_collection()\\n\\n\\n# ----------------------------------------------------------------------\\n# update_build_config\\n# ----------------------------------------------------------------------\\n\\n\\nclass TestUpdateBuildConfig:\\n    @pytest.mark.asyncio\\n    async def test_operation_change_toggles_fields(self, component):\\n        # Simulate the base behavior: reset_build_config if no token, so provide one.\\n        build_config = {\\n            \\\"token\\\": {\\\"value\\\": \\\"tok\\\"},\\n            \\\"environment\\\": {\\\"value\\\": \\\"prod\\\"},\\n            \\\"database_name\\\": {\\n                \\\"value\\\": \\\"\\\",\\n                \\\"options\\\": [],\\n                \\\"options_metadata\\\": [],\\n                \\\"show\\\": False,\\n            },\\n            \\\"api_endpoint\\\": {\\\"value\\\": \\\"\\\", \\\"options\\\": []},\\n            \\\"keyspace\\\": {\\\"value\\\": \\\"\\\", \\\"options\\\": []},\\n            \\\"collection_name\\\": {\\n                \\\"value\\\": \\\"\\\",\\n                \\\"options\\\": [],\\n                \\\"options_metadata\\\": [],\\n                \\\"show\\\": False,\\n            },\\n            \\\"autodetect_collection\\\": {\\\"value\\\": True},\\n            \\\"operation\\\": {\\\"value\\\": OP_FIND},\\n            # Fields managed by _apply_operation_visibility\\n            \\\"filter_query\\\": {\\\"show\\\": True},\\n            \\\"projection\\\": {\\\"show\\\": True},\\n            \\\"sort\\\": {\\\"show\\\": True},\\n            \\\"limit\\\": {\\\"show\\\": True},\\n            \\\"skip\\\": {\\\"show\\\": True},\\n            \\\"include_similarity\\\": {\\\"show\\\": True},\\n            \\\"document\\\": {\\\"show\\\": True},\\n            \\\"documents\\\": {\\\"show\\\": True},\\n            \\\"ordered\\\": {\\\"show\\\": True},\\n            \\\"update\\\": {\\\"show\\\": True},\\n            \\\"upsert\\\": {\\\"show\\\": True},\\n            \\\"upper_bound\\\": {\\\"show\\\": True},\\n        }\\n\\n        # Switching to Insert One should hide find-style fields.\\n        with (\\n            patch.object(\\n                AstraDBDataAPIComponent,\\n                \\\"get_database_list_static\\\",\\n                return_value={},\\n            ),\\n            patch.object(\\n                AstraDBDataAPIComponent,\\n                \\\"map_cloud_providers\\\",\\n                return_value={},\\n            ),\\n        ):\\n            # Swap to a non-managed field so we don't trigger the full base reset,\\n            # then directly invoke the visibility helper via the operation branch.\\n            result = await component.update_build_config(build_config, OP_INSERT_ONE, \\\"operation\\\")\\n\\n        assert result[\\\"document\\\"][\\\"show\\\"] is True\\n        assert result[\\\"filter_query\\\"][\\\"show\\\"] is False\\n        assert result[\\\"documents\\\"][\\\"show\\\"] is False\\n\\n\\n# ----------------------------------------------------------------------\\n# astrapy-backed collection creation\\n# ----------------------------------------------------------------------\\n\\n\\n@pytest.mark.usefixtures(\\\"allow_placeholder_endpoints\\\")\\nclass TestCreateCollectionAstrapyOnly:\\n    \\\"\\\"\\\"The override must not touch ``langchain-astradb``.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"lfx_datastax.components.datastax.astradb_data_api.DataAPIClient\\\")\\n    async def test_bring_your_own_dimension(self, mock_client_cls):\\n        mock_db = Mock()\\n        mock_client_cls.return_value.get_database.return_value = mock_db\\n\\n        await AstraDBDataAPIComponent.create_collection_api(\\n            new_collection_name=\\\"c1\\\",\\n            token=\\\"t\\\",  # noqa: S106\\n            api_endpoint=\\\"https://x.apps.astra.datastax.com\\\",\\n            keyspace=\\\"ks\\\",\\n            dimension=1536,\\n        )\\n\\n        mock_db.create_collection.assert_called_once()\\n        args, kwargs = mock_db.create_collection.call_args\\n        assert args[0] == \\\"c1\\\"\\n        assert kwargs[\\\"keyspace\\\"] == \\\"ks\\\"\\n        definition = kwargs[\\\"definition\\\"]\\n        assert definition is not None\\n        assert definition.vector is not None\\n        assert definition.vector.dimension == 1536\\n        # Vectorize service must NOT be set when dimension-only.\\n        assert definition.vector.service is None\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"lfx_datastax.components.datastax.astradb_data_api.DataAPIClient\\\")\\n    @patch.object(AstraDBDataAPIComponent, \\\"get_vectorize_providers\\\")\\n    async def test_vectorize_provider(self, mock_providers, mock_client_cls):\\n        mock_db = Mock()\\n        mock_client_cls.return_value.get_database.return_value = mock_db\\n        mock_providers.return_value = defaultdict(\\n            list,\\n            {\\\"NVIDIA\\\": [\\\"nvidia\\\", [\\\"nv-embed-qa\\\"]]},\\n        )\\n\\n        await AstraDBDataAPIComponent.create_collection_api(\\n            new_collection_name=\\\"c2\\\",\\n            token=\\\"t\\\",  # noqa: S106\\n            api_endpoint=\\\"https://x.apps.astra.datastax.com\\\",\\n            keyspace=\\\"ks\\\",\\n            embedding_generation_provider=\\\"NVIDIA\\\",\\n            embedding_generation_model=\\\"nv-embed-qa\\\",\\n        )\\n\\n        kwargs = mock_db.create_collection.call_args.kwargs\\n        definition = kwargs[\\\"definition\\\"]\\n        assert definition.vector.service is not None\\n        assert definition.vector.service.provider == \\\"nvidia\\\"\\n        assert definition.vector.service.model_name == \\\"nv-embed-qa\\\"\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"lfx_datastax.components.datastax.astradb_data_api.DataAPIClient\\\")\\n    async def test_plain_collection_no_vector(self, mock_client_cls):\\n        \\\"\\\"\\\"No dimension and no vectorize provider --> plain collection, no definition.\\\"\\\"\\\"\\n        mock_db = Mock()\\n        mock_client_cls.return_value.get_database.return_value = mock_db\\n\\n        await AstraDBDataAPIComponent.create_collection_api(\\n            new_collection_name=\\\"plain\\\",\\n            token=\\\"t\\\",  # noqa: S106\\n            api_endpoint=\\\"https://x.apps.astra.datastax.com\\\",\\n            keyspace=\\\"ks\\\",\\n            embedding_generation_provider=\\\"Bring your own\\\",\\n        )\\n\\n        kwargs = mock_db.create_collection.call_args.kwargs\\n        assert kwargs[\\\"definition\\\"] is None\\n\\n    @pytest.mark.asyncio\\n    async def test_missing_name_rejected(self):\\n        with pytest.raises(ValueError, match=\\\"Collection name is required\\\"):\\n            await AstraDBDataAPIComponent.create_collection_api(\\n                new_collection_name=\\\"\\\",\\n                token=\\\"t\\\",  # noqa: S106\\n                api_endpoint=\\\"https://x.apps.astra.datastax.com\\\",\\n            )\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"lfx_datastax.components.datastax.astradb_data_api.DataAPIClient\\\")\\n    @patch.object(AstraDBDataAPIComponent, \\\"get_vectorize_providers\\\")\\n    async def test_unknown_provider_rejected(self, mock_providers, mock_client_cls):\\n        mock_client_cls.return_value.get_database.return_value = Mock()\\n        mock_providers.return_value = defaultdict(list)\\n\\n        with pytest.raises(ValueError, match=\\\"Unknown embedding provider\\\"):\\n            await AstraDBDataAPIComponent.create_collection_api(\\n                new_collection_name=\\\"c3\\\",\\n                token=\\\"t\\\",  # noqa: S106\\n                api_endpoint=\\\"https://x.apps.astra.datastax.com\\\",\\n                embedding_generation_provider=\\\"NotAProvider\\\",\\n                embedding_generation_model=\\\"m\\\",\\n            )\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"lfx_datastax.components.datastax.astradb_data_api.DataAPIClient\\\")\\n    async def test_no_langchain_astradb_import(self, mock_client_cls, monkeypatch):\\n        \\\"\\\"\\\"The override must not import ``langchain_astradb``.\\n\\n        We simulate that module being unavailable; the call must still succeed.\\n        \\\"\\\"\\\"\\n        import sys\\n\\n        monkeypatch.setitem(sys.modules, \\\"langchain_astradb\\\", None)\\n\\n        mock_db = Mock()\\n        mock_client_cls.return_value.get_database.return_value = mock_db\\n\\n        await AstraDBDataAPIComponent.create_collection_api(\\n            new_collection_name=\\\"no-lc\\\",\\n            token=\\\"t\\\",  # noqa: S106\\n            api_endpoint=\\\"https://x.apps.astra.datastax.com\\\",\\n            dimension=512,\\n        )\\n\\n        mock_db.create_collection.assert_called_once()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/tests/test_cassandra_batch_size.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4ec6f98e9b08403fc1b1246ecad00fe1b8718ecf70bdd72f6c566027f4741944\",\"content\":\"\\\"\\\"\\\"LE-2352 / #6255: ingesting into the Cassandra vector store must not crash.\\n\\n``build_vector_store`` called ``Cassandra.from_documents(..., batch_size=...)``.\\n``from_documents`` does not declare ``batch_size``, so it landed in ``**kwargs``\\nand was splatted into ``cls(...)`` -- i.e. ``Cassandra.__init__``, which accepts\\nonly ``embedding, session, keyspace, table_name, ttl_seconds, body_index_options,\\nsetup_mode, metadata_indexing``. Every run with anything wired to Ingest Data\\ndied with::\\n\\n    Cassandra.__init__() got an unexpected keyword argument 'batch_size'\\n\\n``batch_size`` is a real parameter of ``Cassandra.add_texts`` (default 16), which\\n``add_documents`` forwards to, so the exposed component field has a correct home\\nand must keep working rather than being dropped.\\n\\nNothing above the storage layer is stubbed: ``cassio.init`` opens a real cluster\\nsession and the cassio table writes rows, so those two are patched and everything\\nelse -- the component, ``Cassandra.__init__``, ``add_documents`` -> ``add_texts`` --\\nruns as shipped. The bug cannot hide behind those patches either, since the\\nTypeError comes from binding arguments to ``__init__`` before its body runs.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom langchain_community.vectorstores import Cassandra\\nfrom langchain_core.embeddings import Embeddings, FakeEmbeddings\\nfrom lfx.schema.data import Data\\nfrom lfx_datastax.components.cassandra.cassandra import (\\n    DEFAULT_BATCH_SIZE,\\n    CassandraVectorStoreComponent,\\n)\\n\\nMODULE = \\\"lfx_datastax.components.cassandra.cassandra\\\"\\nCASSIO_TABLE = \\\"cassio.table.MetadataVectorCassandraTable\\\"\\nBATCH_SIZE = 16\\n\\n\\ndef _component(*, with_documents: bool, setup_mode: str = \\\"Sync\\\") -> CassandraVectorStoreComponent:\\n    component = CassandraVectorStoreComponent()\\n    component.database_ref = \\\"127.0.0.1\\\"\\n    component.username = \\\"user\\\"\\n    component.token = \\\"token\\\"  # noqa: S105\\n    component.keyspace = \\\"test_keyspace\\\"\\n    component.table_name = \\\"test_table\\\"\\n    component.ttl_seconds = 0\\n    component.batch_size = BATCH_SIZE\\n    component.cluster_kwargs = {}\\n    component.setup_mode = setup_mode\\n    component.enable_body_search = False\\n    component.embedding = MagicMock(spec=Embeddings)\\n    component.ingest_data = [Data(text=\\\"hello world\\\")] if with_documents else []\\n    return component\\n\\n\\n@pytest.mark.parametrize((\\\"document_count\\\", \\\"batch_size\\\"), [(1, 16), (5, 2), (40, 16), (5, 0)])\\ndef test_should_ingest_against_the_real_cassandra_implementation(document_count: int, batch_size: int):\\n    \\\"\\\"\\\"The reported failure, checked end to end rather than against a stubbed class.\\n\\n    Only the cassio storage table is patched -- the layer that genuinely needs a\\n    cluster. ``Cassandra.__init__``, ``add_documents`` and ``add_texts`` all run for\\n    real, so a mismatch anywhere in that chain still fails here, not just at the\\n    constructor where the reported TypeError happened to land.\\n    \\\"\\\"\\\"\\n    component = _component(with_documents=False)\\n    component.batch_size = batch_size\\n    component.embedding = FakeEmbeddings(size=8)\\n    component.ingest_data = [Data(text=f\\\"doc {i}\\\") for i in range(document_count)]\\n\\n    table = MagicMock()\\n    table.session = MagicMock()\\n\\n    with patch(\\\"cassio.init\\\"), patch(CASSIO_TABLE, MagicMock(return_value=table)):\\n        store = component.build_vector_store()\\n\\n    assert isinstance(store, Cassandra)\\n    assert table.put_async.call_count == document_count, \\\"not every document reached the store\\\"\\n\\n\\ndef test_should_pass_batch_size_to_add_documents():\\n    \\\"\\\"\\\"The exposed field must keep its meaning, not be silently dropped.\\\"\\\"\\\"\\n    component = _component(with_documents=True)\\n    table = MagicMock()\\n\\n    with patch(\\\"cassio.init\\\"), patch(f\\\"{MODULE}.Cassandra\\\", MagicMock(return_value=table)):\\n        result = component.build_vector_store()\\n\\n    table.add_documents.assert_called_once()\\n    assert table.add_documents.call_args.kwargs[\\\"batch_size\\\"] == BATCH_SIZE\\n    assert result is table\\n\\n\\ndef test_should_ingest_every_document():\\n    component = _component(with_documents=True)\\n    table = MagicMock()\\n\\n    with patch(\\\"cassio.init\\\"), patch(f\\\"{MODULE}.Cassandra\\\", MagicMock(return_value=table)):\\n        component.build_vector_store()\\n\\n    documents = table.add_documents.call_args.kwargs[\\\"documents\\\"]\\n    assert len(documents) == 1\\n    assert documents[0].page_content == \\\"hello world\\\"\\n\\n\\ndef test_should_not_add_documents_when_ingest_data_is_empty():\\n    \\\"\\\"\\\"The search-only path was never broken and must stay untouched.\\\"\\\"\\\"\\n    component = _component(with_documents=False)\\n    table = MagicMock()\\n\\n    with patch(\\\"cassio.init\\\"), patch(f\\\"{MODULE}.Cassandra\\\", MagicMock(return_value=table)) as cls:\\n        result = component.build_vector_store()\\n\\n    table.add_documents.assert_not_called()\\n    assert \\\"batch_size\\\" not in cls.call_args.kwargs\\n    assert result is table\\n\\n\\n@pytest.mark.parametrize((\\\"setup_mode\\\", \\\"expected\\\"), [(\\\"Sync\\\", \\\"SYNC\\\"), (\\\"Async\\\", \\\"SYNC\\\"), (\\\"Off\\\", \\\"OFF\\\")])\\ndef test_should_resolve_setup_mode_for_a_synchronous_ingest(setup_mode: str, expected: str):\\n    \\\"\\\"\\\"ASYNC is unsafe on this path; OFF is not, and it is the one that matters.\\n\\n    ``SetupMode.ASYNC`` makes ``__init__`` hand cassio ``async_setup=True`` plus an\\n    un-awaited coroutine as the vector dimension, while ``add_documents``/``add_texts``\\n    are synchronous -- so it degrades to SYNC. ``SetupMode.OFF`` is honoured because it\\n    is what sets ``skip_provisioning``: forcing SYNC would re-run the table DDL on every\\n    ingest for a pre-provisioned table or a role without CREATE.\\n    \\\"\\\"\\\"\\n    from langchain_community.utilities.cassandra import SetupMode\\n\\n    component = _component(with_documents=True, setup_mode=setup_mode)\\n\\n    with patch(\\\"cassio.init\\\"), patch(f\\\"{MODULE}.Cassandra\\\", MagicMock(return_value=MagicMock())) as cls:\\n        component.build_vector_store()\\n\\n    assert cls.call_args.kwargs[\\\"setup_mode\\\"] is getattr(SetupMode, expected)\\n\\n\\n@pytest.mark.parametrize(\\\"raw_batch_size\\\", [0, None, \\\"\\\"])\\ndef test_should_fall_back_to_the_default_batch_size_when_the_field_is_cleared(raw_batch_size):\\n    \\\"\\\"\\\"``IntInput`` coerces a cleared advanced field to 0, and add_texts slices with\\n    ``range(0, len(texts), batch_size)`` -- which raises ``range() arg 3 must not be\\n    zero`` only AFTER the table DDL and the embedding-dimension probe have run.\\n    \\\"\\\"\\\"\\n    component = _component(with_documents=True)\\n    component.batch_size = raw_batch_size\\n    table = MagicMock()\\n\\n    with patch(\\\"cassio.init\\\"), patch(f\\\"{MODULE}.Cassandra\\\", MagicMock(return_value=table)):\\n        component.build_vector_store()\\n\\n    assert table.add_documents.call_args.kwargs[\\\"batch_size\\\"] == DEFAULT_BATCH_SIZE\\n\\n\\ndef test_should_clamp_a_negative_batch_size():\\n    \\\"\\\"\\\"A negative batch size makes add_texts iterate an empty range: it reports success\\n    and writes NOTHING, which is worse than the crash a zero produces.\\n    \\\"\\\"\\\"\\n    component = _component(with_documents=True)\\n    component.batch_size = -1\\n    component.embedding = FakeEmbeddings(size=8)\\n    table = MagicMock()\\n    table.session = MagicMock()\\n\\n    with patch(\\\"cassio.init\\\"), patch(CASSIO_TABLE, MagicMock(return_value=table)):\\n        component.build_vector_store()\\n\\n    assert table.put_async.call_count == 1, \\\"a negative batch size silently dropped the documents\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/tests/test_cassandra_compatibility.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6ea734f86796eeb33e14cb992d0bda8fb97c3f1127f2161356af6414e6dc732f\",\"content\":\"import json\\nfrom importlib.metadata import version\\nfrom pathlib import Path\\n\\nfrom lfx.components.cassandra import (\\n    CassandraChatMemory as CompatibilityCassandraChatMemory,\\n)\\nfrom lfx.components.cassandra import (\\n    CassandraGraphVectorStoreComponent as CompatibilityCassandraGraphVectorStoreComponent,\\n)\\nfrom lfx.components.cassandra import (\\n    CassandraVectorStoreComponent as CompatibilityCassandraVectorStoreComponent,\\n)\\nfrom lfx.components.cassandra.cassandra import CassandraVectorStoreComponent as CompatibilityModuleCassandraVectorStore\\nfrom lfx.components.cassandra.cassandra_chat import CassandraChatMemory as CompatibilityModuleCassandraChatMemory\\nfrom lfx.components.cassandra.cassandra_graph import (\\n    CassandraGraphVectorStoreComponent as CompatibilityModuleCassandraGraphVectorStore,\\n)\\nfrom lfx_datastax.components.cassandra import (\\n    CassandraChatMemory,\\n    CassandraGraphVectorStoreComponent,\\n    CassandraVectorStoreComponent,\\n)\\n\\n\\ndef test_legacy_cassandra_imports_preserve_class_identity() -> None:\\n    assert CompatibilityCassandraVectorStoreComponent is CassandraVectorStoreComponent\\n    assert CompatibilityCassandraChatMemory is CassandraChatMemory\\n    assert CompatibilityCassandraGraphVectorStoreComponent is CassandraGraphVectorStoreComponent\\n    assert CompatibilityModuleCassandraVectorStore is CassandraVectorStoreComponent\\n    assert CompatibilityModuleCassandraChatMemory is CassandraChatMemory\\n    assert CompatibilityModuleCassandraGraphVectorStore is CassandraGraphVectorStoreComponent\\n    assert CassandraVectorStoreComponent.__name__ == \\\"CassandraVectorStoreComponent\\\"\\n    assert CassandraChatMemory.__name__ == \\\"CassandraChatMemory\\\"\\n    assert CassandraGraphVectorStoreComponent.__name__ == \\\"CassandraGraphVectorStoreComponent\\\"\\n\\n\\ndef test_manifest_exposes_cassandra_as_a_separate_bundle() -> None:\\n    manifest_path = Path(__file__).parents[1] / \\\"src\\\" / \\\"lfx_datastax\\\" / \\\"extension.json\\\"\\n    manifest = json.loads(manifest_path.read_text(encoding=\\\"utf-8\\\"))\\n\\n    # Assert the manifest tracks the distribution rather than a literal: the release-plan guard\\n    # bumps pyproject whenever releasable bundle source changes, and a hardcoded version here\\n    # turns every one of those bumps into a spurious failure while checking nothing real. The\\n    # invariant worth pinning is that extension.json and the package stay in lockstep -- bumping\\n    # one without the other is the actual bug.\\n    assert manifest[\\\"version\\\"] == version(\\\"lfx-datastax\\\")\\n    assert manifest[\\\"bundles\\\"] == [\\n        {\\\"name\\\": \\\"datastax\\\", \\\"path\\\": \\\"components/datastax\\\"},\\n        {\\\"name\\\": \\\"cassandra\\\", \\\"path\\\": \\\"components/cassandra\\\"},\\n    ]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/tests/test_removed_components.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1fadd1586bcafbfa0561bf4e7b363fda4b7b64b6f7f838fcbbdeb360f00c5468\",\"content\":\"import importlib\\n\\nimport pytest\\n\\n\\ndef test_deprecated_astra_assistants_removed():\\n    \\\"\\\"\\\"Deprecated Astra Assistants components should not be exported by the Datastax bundle.\\\"\\\"\\\"\\n    import lfx.components.datastax as datastax\\n\\n    removed_components = [\\n        \\\"AssistantsCreateAssistant\\\",\\n        \\\"AssistantsCreateThread\\\",\\n        \\\"AssistantsGetAssistantName\\\",\\n        \\\"AssistantsListAssistants\\\",\\n        \\\"AssistantsRun\\\",\\n        \\\"AstraAssistantManager\\\",\\n    ]\\n\\n    for name in removed_components:\\n        assert not hasattr(datastax, name), f\\\"Deprecated component {name} should have been removed\\\"\\n\\n\\ndef test_datastax_remaining_components_accessible():\\n    \\\"\\\"\\\"Non-deprecated Datastax components should remain exported by the Datastax bundle.\\\"\\\"\\\"\\n    import lfx.components.datastax as datastax\\n\\n    expected_components = [\\n        \\\"AstraDBVectorStoreComponent\\\",\\n        \\\"AstraDBChatMemory\\\",\\n        \\\"AstraDBToolComponent\\\",\\n        \\\"AstraDBCQLToolComponent\\\",\\n        \\\"AstraDBGraphVectorStoreComponent\\\",\\n        \\\"AstraVectorizeComponent\\\",\\n        \\\"GraphRAGComponent\\\",\\n        \\\"Dotenv\\\",\\n    ]\\n\\n    for name in expected_components:\\n        assert hasattr(datastax, name), f\\\"Component {name} should still be accessible\\\"\\n        component = getattr(datastax, name)\\n        assert component is not None, f\\\"Component {name} should not be None\\\"\\n\\n\\ndef test_getenvvar_component_removed():\\n    \\\"\\\"\\\"The removed GetEnvVar component should not be importable from the Datastax bundle.\\\"\\\"\\\"\\n    import lfx.components.datastax as datastax\\n\\n    with pytest.raises(AttributeError):\\n        _ = datastax.GetEnvVar\\n\\n    assert not hasattr(datastax, \\\"GetEnvVar\\\"), \\\"GetEnvVar should have been removed from lfx.components.datastax\\\"\\n\\n    with pytest.raises((ImportError, ModuleNotFoundError)):\\n        importlib.import_module(\\\"lfx_datastax.components.datastax.getenvvar\\\")\\n\\n\\ndef test_datastax_dir_excludes_deprecated():\\n    \\\"\\\"\\\"dir(datastax) should not list deprecated components.\\\"\\\"\\\"\\n    import lfx.components.datastax as datastax\\n\\n    exported = dir(datastax)\\n    deprecated = {\\n        \\\"AssistantsCreateAssistant\\\",\\n        \\\"AssistantsCreateThread\\\",\\n        \\\"AssistantsGetAssistantName\\\",\\n        \\\"AssistantsListAssistants\\\",\\n        \\\"AssistantsRun\\\",\\n        \\\"AstraAssistantManager\\\",\\n    }\\n\\n    assert not deprecated.intersection(exported), (\\n        f\\\"Deprecated components still appear in dir(): {deprecated.intersection(exported)}\\\"\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/tests/test_vector_store_decorator.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e10b4cb8e5bdc3f7a74771f3a91797b1f3558830d60c4fbbbf3913cf5343c3ab\",\"content\":\"from lfx_datastax import AstraDBVectorStoreComponent\\n\\n\\nclass TestVectorStoreDecorator:\\n    \\\"\\\"\\\"Unit tests for the AstraDBVectorStoreComponent decorator.\\n\\n    This test class inherits from ComponentTestBaseWithoutClient and includes\\n    the following tests and fixtures:\\n\\n    Fixtures:\\n        - component_class: Returns the AstraDBVectorStoreComponent class to be tested.\\n        - file_names_mapping: Returns an empty list representing the file names mapping for different versions.\\n    Tests:\\n        - test_decorator_applied: Verifies that the AstraDBVectorStoreComponent has the 'decorated' attribute and that\\n        it is set to True.\\n    \\\"\\\"\\\"\\n\\n    def test_decorator_applied(self):\\n        component = AstraDBVectorStoreComponent()\\n        assert hasattr(component, \\\"decorated\\\")\\n        assert component.decorated\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/docling/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"665c7249829afdb44e18cde7fc5db9720aa586a0ddd1cb66e209bc89d34c1079\",\"content\":\"# Docling Bundle\\n\\nDocling components for Langflow packaged as a standalone Extension Bundle.\\n\\n## Components\\n\\n- Docling\\n- Docling Serve\\n- Export DoclingDocument\\n- Chunk DoclingDocument\\n\\n## Install\\n\\nThe bundle is installed with Langflow in the 1.10 workspace. The base package includes `docling-core` for the `DoclingDocument` schema. For standalone local conversion:\\n\\n```bash\\nuv pip install \\\"lfx-docling[local]\\\"\\n```\\n\\nChunking and picture-description support use separate optional extras. Chunking\\ndoes not install the full local converter/OCR stack:\\n\\n```bash\\nuv pip install \\\"lfx-docling[chunking]\\\"\\nuv pip install \\\"lfx-docling[image-description]\\\"\\n```\\n\\n## Develop\\n\\n```bash\\nuv run lfx extension validate src/bundles/docling/src/lfx_docling\\nuv run pytest src/bundles/docling/tests\\n```\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/docling/pyproject.toml\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"91073dcc16223f8309fc483be1384f586d58310e4da8cd55bae5381cfa97f9bb\",\"content\":\"[project]\\nname = \\\"lfx-docling\\\"\\nversion = \\\"0.1.7\\\"\\ndescription = \\\"Docling document processing components as a standalone Langflow Extension Bundle.\\\"\\nreadme = \\\"README.md\\\"\\nrequires-python = \\\">=3.10,<3.15\\\"\\nlicense = { text = \\\"MIT\\\" }\\nauthors = [\\n    { name = \\\"Langflow\\\", email = \\\"contact@langflow.org\\\" },\\n]\\nkeywords = [\\\"langflow\\\", \\\"lfx\\\", \\\"extension\\\", \\\"bundle\\\", \\\"docling\\\", \\\"documents\\\"]\\n\\n# Keep the full local converter and OCR stack optional. docling-core remains a\\n# base dependency because the bundle exchanges DoclingDocument objects even when\\n# conversion happens remotely.\\ndependencies = [\\n    \\\"lfx>=1.12.0.dev0,<2.0.0\\\",\\n    \\\"httpx>=0.28.1,<1.0.0\\\",\\n    \\\"docling-core>=2.36.1,<3.0.0\\\",\\n]\\n\\n[project.optional-dependencies]\\nlocal = [\\n    # Older Docling releases cap Transformers below the CVE-2026-9856 fix on macOS.\\n    \\\"docling>=2.125.0,<3.0.0; sys_platform != 'darwin' or platform_machine != 'x86_64'\\\",\\n    \\\"tesserocr>=2.8.0\\\",\\n    \\\"rapidocr-onnxruntime>=1.4.4\\\",\\n    \\\"ocrmac>=1.0.0; sys_platform == 'darwin'\\\",\\n    \\\"torch>=2.14.0\\\", # CVE-2025-3000: includes the bare-container annotation fix\\n    \\\"torchvision>=0.21.0\\\",\\n    \\\"transformers>=5.10.1,<6.0.0\\\", # CVE-2026-9856\\n]\\nchunking = [\\n    \\\"docling-core[chunking]>=2.36.1,<3.0.0\\\",\\n    \\\"tiktoken>=0.7.0\\\",\\n    \\\"transformers>=5.10.1,<6.0.0\\\", # CVE-2026-9856\\n]\\nimage-description = [\\n    \\\"lfx-docling[local]\\\",\\n    \\\"langchain-docling>=1.1.0\\\",\\n]\\nall = [\\n    \\\"lfx-docling[local,chunking,image-description]\\\",\\n]\\n\\n[project.urls]\\nHomepage = \\\"https://github.com/langflow-ai/langflow\\\"\\nDocumentation = \\\"https://docs.langflow.org/bundles-docling\\\"\\nRepository = \\\"https://github.com/langflow-ai/langflow\\\"\\n\\n[project.entry-points.\\\"langflow.extensions\\\"]\\nlfx-docling = \\\"lfx_docling\\\"\\n\\n[build-system]\\nrequires = [\\\"hatchling==1.31.0\\\"]\\nbuild-backend = \\\"hatchling.build\\\"\\n\\n[tool.hatch.build.targets.wheel]\\npackages = [\\\"src/lfx_docling\\\"]\\ninclude = [\\\"src/lfx_docling/extension.json\\\", \\\"src/lfx_docling/components/**/*.py\\\"]\\n\\n[tool.hatch.build.targets.sdist]\\ninclude = [\\n    \\\"src/lfx_docling\\\",\\n    \\\"extension.json\\\",\\n    \\\"README.md\\\",\\n    \\\"pyproject.toml\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/docling/src/lfx_docling/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7024705b58cb657f41279a15f535d861c611ba19550cf543ab23e364195a0719\",\"content\":\"\\\"\\\"\\\"lfx-docling: Docling document processing components.\\\"\\\"\\\"\\n\\nfrom lfx_docling.components.docling.chunk_docling_document import ChunkDoclingDocumentComponent\\nfrom lfx_docling.components.docling.docling_inline import DoclingInlineComponent\\nfrom lfx_docling.components.docling.docling_remote import DoclingRemoteComponent\\nfrom lfx_docling.components.docling.export_docling_document import ExportDoclingDocumentComponent\\n\\n__all__ = [\\n    \\\"ChunkDoclingDocumentComponent\\\",\\n    \\\"DoclingInlineComponent\\\",\\n    \\\"DoclingRemoteComponent\\\",\\n    \\\"ExportDoclingDocumentComponent\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/docling/src/lfx_docling/components/docling/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"eb1c5578ad43bad0ca4bbbdd8ae17d5c519b779c89f4cfdea767bf618a9adf62\",\"content\":\"from .chunk_docling_document import ChunkDoclingDocumentComponent\\nfrom .docling_inline import DoclingInlineComponent\\nfrom .docling_remote import DoclingRemoteComponent\\nfrom .export_docling_document import ExportDoclingDocumentComponent\\n\\n__all__ = [\\n    \\\"ChunkDoclingDocumentComponent\\\",\\n    \\\"DoclingInlineComponent\\\",\\n    \\\"DoclingRemoteComponent\\\",\\n    \\\"ExportDoclingDocumentComponent\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/docling/src/lfx_docling/components/docling/chunk_docling_document.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f5ef3251f5cee181f18e005f6f4566edc4365d2156e0a3e48227eb2eee3cf537\",\"content\":\"import json\\nfrom typing import Any\\n\\nfrom lfx.base.data.docling_utils import extract_docling_documents\\nfrom lfx.custom import Component\\nfrom lfx.io import BoolInput, DropdownInput, HandleInput, IntInput, MessageTextInput, Output, StrInput\\nfrom lfx.schema import Data, DataFrame\\n\\n_CHUNKING_INSTALL_HINT = (\\n    \\\"Install them with `uv pip install 'lfx-docling[chunking]'`, \\\"\\n    \\\"`uv pip install 'langflow[docling-chunking]'`, or \\\"\\n    \\\"`uv pip install 'docling-core[chunking]' tiktoken`.\\\"\\n)\\n\\n\\ndef _load_docling_chunker_dependencies() -> tuple[type[Any], type[Any]]:\\n    try:\\n        from docling_core.transforms.chunker.doc_chunk import DocMeta as DocMetaCls\\n        from docling_core.transforms.chunker.hierarchical_chunker import HierarchicalChunker as HierarchicalChunkerCls\\n    except (ImportError, RuntimeError) as e:\\n        msg = f\\\"Docling chunking dependencies are not installed. {_CHUNKING_INSTALL_HINT}\\\"\\n        raise ImportError(msg) from e\\n    return DocMetaCls, HierarchicalChunkerCls\\n\\n\\nclass ChunkDoclingDocumentComponent(Component):\\n    display_name: str = \\\"Chunk DoclingDocument\\\"\\n    description: str = \\\"Use DoclingDocument chunkers to split the document into chunks.\\\"\\n    documentation = \\\"https://docling-project.github.io/docling/concepts/chunking/\\\"\\n    icon = \\\"Docling\\\"\\n    name = \\\"ChunkDoclingDocument\\\"\\n\\n    inputs = [\\n        HandleInput(\\n            name=\\\"data_inputs\\\",\\n            display_name=\\\"JSON or Table\\\",\\n            info=\\\"The data with documents to split in chunks.\\\",\\n            input_types=[\\\"Data\\\", \\\"JSON\\\", \\\"DataFrame\\\", \\\"Table\\\"],\\n            required=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"chunker\\\",\\n            display_name=\\\"Chunker\\\",\\n            options=[\\\"HybridChunker\\\", \\\"HierarchicalChunker\\\"],\\n            info=(\\\"Which chunker to use.\\\"),\\n            value=\\\"HybridChunker\\\",\\n            real_time_refresh=True,\\n            input_types=[\\\"Message\\\"],\\n        ),\\n        DropdownInput(\\n            name=\\\"provider\\\",\\n            display_name=\\\"Provider\\\",\\n            options=[\\\"Hugging Face\\\", \\\"OpenAI\\\"],\\n            info=(\\\"Which tokenizer provider.\\\"),\\n            value=\\\"Hugging Face\\\",\\n            show=True,\\n            real_time_refresh=True,\\n            advanced=True,\\n            dynamic=True,\\n        ),\\n        StrInput(\\n            name=\\\"hf_model_name\\\",\\n            display_name=\\\"HF model name\\\",\\n            info=(\\n                \\\"Model name of the tokenizer to use with the HybridChunker when Hugging Face is chosen as a tokenizer.\\\"\\n            ),\\n            value=\\\"sentence-transformers/all-MiniLM-L6-v2\\\",\\n            show=True,\\n            advanced=True,\\n            dynamic=True,\\n        ),\\n        StrInput(\\n            name=\\\"openai_model_name\\\",\\n            display_name=\\\"OpenAI model name\\\",\\n            info=(\\\"Model name of the tokenizer to use with the HybridChunker when OpenAI is chosen as a tokenizer.\\\"),\\n            value=\\\"gpt-4o\\\",\\n            show=False,\\n            advanced=True,\\n            dynamic=True,\\n        ),\\n        IntInput(\\n            name=\\\"max_tokens\\\",\\n            display_name=\\\"Maximum tokens\\\",\\n            info=(\\\"Maximum number of tokens for the HybridChunker.\\\"),\\n            show=True,\\n            required=False,\\n            advanced=True,\\n            dynamic=True,\\n            input_types=[\\\"Message\\\"],\\n        ),\\n        BoolInput(\\n            name=\\\"merge_peers\\\",\\n            display_name=\\\"Merge peers\\\",\\n            info=\\\"Merge undersized chunks sharing the same relevant metadata.\\\",\\n            value=True,\\n            show=True,\\n            advanced=True,\\n            dynamic=True,\\n        ),\\n        BoolInput(\\n            name=\\\"always_emit_headings\\\",\\n            display_name=\\\"Always emit headings\\\",\\n            info=\\\"Emit headings even for empty sections.\\\",\\n            value=False,\\n            show=True,\\n            advanced=True,\\n            dynamic=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"doc_key\\\",\\n            display_name=\\\"Doc Key\\\",\\n            info=\\\"The key to use for the DoclingDocument column.\\\",\\n            value=\\\"doc\\\",\\n            advanced=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Table\\\", name=\\\"dataframe\\\", method=\\\"chunk_documents\\\"),\\n    ]\\n\\n    def update_build_config(self, build_config: dict, field_value: str, field_name: str | None = None) -> dict:\\n        \\\"\\\"\\\"Update build_config to show/hide fields based on chunker and provider selection.\\\"\\\"\\\"\\n        if field_name == \\\"chunker\\\":\\n            provider_type = build_config[\\\"provider\\\"][\\\"value\\\"]\\n            is_hf = provider_type == \\\"Hugging Face\\\"\\n            is_openai = provider_type == \\\"OpenAI\\\"\\n            if field_value == \\\"HybridChunker\\\":\\n                build_config[\\\"provider\\\"][\\\"show\\\"] = True\\n                build_config[\\\"hf_model_name\\\"][\\\"show\\\"] = is_hf\\n                build_config[\\\"openai_model_name\\\"][\\\"show\\\"] = is_openai\\n                build_config[\\\"max_tokens\\\"][\\\"show\\\"] = True\\n                build_config[\\\"merge_peers\\\"][\\\"show\\\"] = True\\n                build_config[\\\"always_emit_headings\\\"][\\\"show\\\"] = True\\n            else:\\n                build_config[\\\"provider\\\"][\\\"show\\\"] = False\\n                build_config[\\\"hf_model_name\\\"][\\\"show\\\"] = False\\n                build_config[\\\"openai_model_name\\\"][\\\"show\\\"] = False\\n                build_config[\\\"max_tokens\\\"][\\\"show\\\"] = False\\n                build_config[\\\"merge_peers\\\"][\\\"show\\\"] = False\\n                build_config[\\\"always_emit_headings\\\"][\\\"show\\\"] = False\\n        elif field_name == \\\"provider\\\" and build_config[\\\"chunker\\\"][\\\"value\\\"] == \\\"HybridChunker\\\":\\n            if field_value == \\\"Hugging Face\\\":\\n                build_config[\\\"hf_model_name\\\"][\\\"show\\\"] = True\\n                build_config[\\\"openai_model_name\\\"][\\\"show\\\"] = False\\n            elif field_value == \\\"OpenAI\\\":\\n                build_config[\\\"hf_model_name\\\"][\\\"show\\\"] = False\\n                build_config[\\\"openai_model_name\\\"][\\\"show\\\"] = True\\n\\n        return build_config\\n\\n    def _docs_to_data(self, docs) -> list[Data]:\\n        return [Data(text=doc.page_content, data=doc.metadata) for doc in docs]\\n\\n    def chunk_documents(self) -> DataFrame:\\n        documents, warning = extract_docling_documents(self.data_inputs, self.doc_key)\\n        if warning:\\n            self.status = warning\\n\\n        doc_meta_cls, hierarchical_chunker_cls = _load_docling_chunker_dependencies()\\n        chunker: Any\\n        if self.chunker == \\\"HybridChunker\\\":\\n            try:\\n                from docling_core.transforms.chunker.hybrid_chunker import HybridChunker\\n            except (ImportError, RuntimeError) as e:\\n                msg = f\\\"HybridChunker is not installed. {_CHUNKING_INSTALL_HINT}\\\"\\n                raise ImportError(msg) from e\\n            max_tokens: int | None = self.max_tokens if self.max_tokens else None\\n            if self.provider == \\\"Hugging Face\\\":\\n                try:\\n                    from docling_core.transforms.chunker.tokenizer.huggingface import HuggingFaceTokenizer\\n                except (ImportError, RuntimeError) as e:\\n                    msg = f\\\"HuggingFaceTokenizer is not installed. {_CHUNKING_INSTALL_HINT}\\\"\\n                    raise ImportError(msg) from e\\n                tokenizer = HuggingFaceTokenizer.from_pretrained(\\n                    model_name=self.hf_model_name,\\n                    max_tokens=max_tokens,\\n                )\\n            elif self.provider == \\\"OpenAI\\\":\\n                try:\\n                    import tiktoken\\n                    from docling_core.transforms.chunker.tokenizer.openai import OpenAITokenizer\\n                except (ImportError, RuntimeError) as e:\\n                    msg = f\\\"OpenAITokenizer is not installed. {_CHUNKING_INSTALL_HINT}\\\"\\n                    raise ImportError(msg) from e\\n                if max_tokens is None:\\n                    max_tokens = 128 * 1024  # context window length required for OpenAI tokenizers\\n                tokenizer = OpenAITokenizer(\\n                    tokenizer=tiktoken.encoding_for_model(self.openai_model_name), max_tokens=max_tokens\\n                )\\n            chunker = HybridChunker(\\n                tokenizer=tokenizer,\\n                merge_peers=bool(self.merge_peers),\\n                always_emit_headings=bool(self.always_emit_headings),\\n            )\\n\\n        elif self.chunker == \\\"HierarchicalChunker\\\":\\n            chunker = hierarchical_chunker_cls()\\n        else:\\n            msg = f\\\"Unknown chunker: {self.chunker}\\\"\\n            raise ValueError(msg)\\n\\n        results: list[Data] = []\\n        try:\\n            for doc in documents:\\n                for chunk in chunker.chunk(dl_doc=doc):\\n                    enriched_text = chunker.contextualize(chunk=chunk)\\n                    meta = doc_meta_cls.model_validate(chunk.meta)\\n\\n                    results.append(\\n                        Data(\\n                            data={\\n                                \\\"text\\\": enriched_text,\\n                                \\\"document_id\\\": f\\\"{doc.origin.binary_hash}\\\",\\n                                \\\"doc_items\\\": json.dumps([item.self_ref for item in meta.doc_items]),\\n                            }\\n                        )\\n                    )\\n\\n        except Exception as e:\\n            msg = f\\\"Error splitting text: {e}\\\"\\n            raise TypeError(msg) from e\\n\\n        return DataFrame(results)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/docling/src/lfx_docling/components/docling/docling_inline.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"65d38b7e5500126fdb6ea9ee700f3a8cbcc3722d84c429af1fd7fdacaee8810c\",\"content\":\"import json\\nimport subprocess\\nimport sys\\nimport textwrap\\nimport time\\n\\nfrom lfx.base.data import BaseFileComponent\\nfrom lfx.base.data.docling_utils import _serialize_pydantic_model\\nfrom lfx.inputs import BoolInput, DropdownInput, HandleInput, StrInput\\nfrom lfx.schema import Data, DataFrame\\n\\n\\nclass DoclingInlineComponent(BaseFileComponent):\\n    display_name = \\\"Docling\\\"\\n    description = \\\"Uses Docling to process input documents running the Docling models locally.\\\"\\n    documentation = \\\"https://docling-project.github.io/docling/\\\"\\n    trace_type = \\\"tool\\\"\\n    icon = \\\"Docling\\\"\\n    name = \\\"DoclingInline\\\"\\n\\n    # https://docling-project.github.io/docling/usage/supported_formats/\\n    VALID_EXTENSIONS = [\\n        \\\"adoc\\\",\\n        \\\"asciidoc\\\",\\n        \\\"asc\\\",\\n        \\\"bmp\\\",\\n        \\\"csv\\\",\\n        \\\"dotx\\\",\\n        \\\"dotm\\\",\\n        \\\"docm\\\",\\n        \\\"docx\\\",\\n        \\\"htm\\\",\\n        \\\"html\\\",\\n        \\\"jpeg\\\",\\n        \\\"json\\\",\\n        \\\"md\\\",\\n        \\\"pdf\\\",\\n        \\\"png\\\",\\n        \\\"potx\\\",\\n        \\\"ppsx\\\",\\n        \\\"pptm\\\",\\n        \\\"potm\\\",\\n        \\\"ppsm\\\",\\n        \\\"pptx\\\",\\n        \\\"tiff\\\",\\n        \\\"txt\\\",\\n        \\\"xls\\\",\\n        \\\"xlsx\\\",\\n        \\\"xhtml\\\",\\n        \\\"xml\\\",\\n        \\\"webp\\\",\\n    ]\\n\\n    inputs = [\\n        *BaseFileComponent.get_base_inputs(),\\n        DropdownInput(\\n            name=\\\"pipeline\\\",\\n            display_name=\\\"Pipeline\\\",\\n            info=\\\"Docling pipeline to use\\\",\\n            options=[\\\"standard\\\", \\\"vlm\\\"],\\n            value=\\\"standard\\\",\\n        ),\\n        DropdownInput(\\n            name=\\\"ocr_engine\\\",\\n            display_name=\\\"OCR Engine\\\",\\n            info=\\\"OCR engine to use. None will disable OCR.\\\",\\n            options=[\\\"None\\\", \\\"easyocr\\\", \\\"tesserocr\\\", \\\"rapidocr\\\", \\\"ocrmac\\\"],\\n            value=\\\"None\\\",\\n        ),\\n        BoolInput(\\n            name=\\\"do_picture_classification\\\",\\n            display_name=\\\"Picture classification\\\",\\n            info=\\\"If enabled, the Docling pipeline will classify the pictures type.\\\",\\n            value=False,\\n        ),\\n        HandleInput(\\n            name=\\\"pic_desc_llm\\\",\\n            display_name=\\\"Picture description LLM\\\",\\n            info=\\\"If connected, the model to use for running the picture description task.\\\",\\n            input_types=[\\\"LanguageModel\\\"],\\n            required=False,\\n        ),\\n        StrInput(\\n            name=\\\"pic_desc_prompt\\\",\\n            display_name=\\\"Picture description prompt\\\",\\n            value=\\\"Describe the image in three sentences. Be concise and accurate.\\\",\\n            info=\\\"The user prompt to use when invoking the model.\\\",\\n            advanced=True,\\n        ),\\n        # TODO: expose more Docling options\\n    ]\\n\\n    outputs = [\\n        *BaseFileComponent.get_base_outputs(),\\n    ]\\n\\n    def build(self) -> DataFrame:\\n        # Static bundle validation cannot see BaseFileComponent's inherited output method.\\n        return self.load_files()\\n\\n    # ------------------------------------------------------------------ #\\n    # Child script that runs Docling in a separate OS process.            #\\n    # Uses subprocess.Popen (same pattern as Read File advanced mode)     #\\n    # instead of multiprocessing/threading so that:                       #\\n    #   1. It works reliably under Gunicorn's fork-based workers          #\\n    #   2. The parent's event loop stays free for SSE heartbeats          #\\n    #   3. No pickling / signal-handler conflicts                         #\\n    # ------------------------------------------------------------------ #\\n    _CHILD_SCRIPT: str = textwrap.dedent(r\\\"\\\"\\\"\\n        import json, sys\\n\\n        def main():\\n            cfg = json.loads(sys.stdin.read())\\n            file_paths      = cfg[\\\"file_paths\\\"]\\n            pipeline        = cfg[\\\"pipeline\\\"]\\n            ocr_engine      = cfg[\\\"ocr_engine\\\"]\\n            do_picture_cls  = cfg[\\\"do_picture_classification\\\"]\\n            pic_desc_config = cfg.get(\\\"pic_desc_config\\\")\\n            pic_desc_prompt = cfg.get(\\\"pic_desc_prompt\\\", \\\"\\\")\\n\\n            try:\\n                from docling.datamodel.base_models import ConversionStatus, InputFormat\\n                from docling.datamodel.pipeline_options import PdfPipelineOptions\\n                from docling.document_converter import DocumentConverter, FormatOption, PdfFormatOption\\n            except ImportError as e:\\n                print(json.dumps({\\\"ok\\\": False, \\\"error\\\": f\\\"Docling is not installed: {e}\\\"}))\\n                return\\n\\n            # --- build converter ------------------------------------------------\\n            try:\\n                pipe = PdfPipelineOptions()\\n                pipe.do_ocr = ocr_engine not in (\\\"\\\", \\\"None\\\")\\n                if pipe.do_ocr:\\n                    try:\\n                        from docling.models.factories import get_ocr_factory\\n                        fac = get_ocr_factory(allow_external_plugins=False)\\n                        pipe.ocr_options = fac.create_options(kind=ocr_engine)\\n                    except Exception:\\n                        pipe.do_ocr = False\\n\\n                pipe.do_picture_classification = do_picture_cls\\n\\n                if pic_desc_config:\\n                    try:\\n                        import importlib\\n                        from pydantic import TypeAdapter\\n                        try:\\n                            from langchain_docling.picture_description import PictureDescriptionLangChainOptions\\n                        except ImportError:\\n                            print(json.dumps({\\n                                \\\"ok\\\": False,\\n                                \\\"error\\\": (\\n                                    \\\"langchain-docling is not installed. Install it with \\\"\\n                                    \\\"`uv pip install 'langflow[docling-image-description]'` or \\\"\\n                                    \\\"`uv pip install 'lfx-docling[image-description]'`.\\\"\\n                                )\\n                            }))\\n                            return\\n                        mod_name, cls_name = pic_desc_config[\\\"__class_path__\\\"].rsplit(\\\".\\\", 1)\\n                        mod = importlib.import_module(mod_name)\\n                        cls = getattr(mod, cls_name)\\n                        adapter = TypeAdapter(cls)\\n                        llm = adapter.validate_python(pic_desc_config[\\\"config\\\"])\\n                        pipe.do_picture_description = True\\n                        pipe.allow_external_plugins = True\\n                        pipe.picture_description_options = PictureDescriptionLangChainOptions(\\n                            llm=llm, prompt=pic_desc_prompt,\\n                        )\\n                    except Exception as e:\\n                        print(json.dumps({\\\"ok\\\": False, \\\"error\\\": f\\\"Picture description setup failed: {e}\\\"}))\\n                        return\\n\\n                if pipeline == \\\"vlm\\\":\\n                    try:\\n                        from docling.datamodel.pipeline_options import VlmPipelineOptions\\n                        from docling.pipeline.vlm_pipeline import VlmPipeline\\n                        vlm_opts = VlmPipelineOptions()\\n                        if sys.platform == \\\"darwin\\\":\\n                            try:\\n                                from docling.datamodel.vlm_model_specs import GRANITEDOCLING_MLX\\n                                vlm_opts.vlm_options = GRANITEDOCLING_MLX\\n                            except ImportError:\\n                                from docling.datamodel.vlm_model_specs import GRANITEDOCLING_TRANSFORMERS\\n                                vlm_opts.vlm_options = GRANITEDOCLING_TRANSFORMERS\\n                        fmt = {}\\n                        if hasattr(InputFormat, \\\"PDF\\\"):\\n                            fmt[InputFormat.PDF] = PdfFormatOption(\\n                                pipeline_cls=VlmPipeline, pipeline_options=vlm_opts,\\n                            )\\n                        if hasattr(InputFormat, \\\"IMAGE\\\"):\\n                            fmt[InputFormat.IMAGE] = PdfFormatOption(\\n                                pipeline_cls=VlmPipeline, pipeline_options=vlm_opts,\\n                            )\\n                        converter = DocumentConverter(format_options=fmt)\\n                    except Exception as e:\\n                        print(json.dumps({\\\"ok\\\": False, \\\"error\\\": f\\\"VLM pipeline setup failed: {e}\\\"}))\\n                        return\\n                else:\\n                    pdf_opt = PdfFormatOption(pipeline_options=pipe)\\n                    fmt = {}\\n                    if hasattr(InputFormat, \\\"PDF\\\"):\\n                        fmt[InputFormat.PDF] = pdf_opt\\n                    if hasattr(InputFormat, \\\"IMAGE\\\"):\\n                        fmt[InputFormat.IMAGE] = pdf_opt\\n                    converter = DocumentConverter(format_options=fmt)\\n            except Exception as e:\\n                print(json.dumps({\\\"ok\\\": False, \\\"error\\\": f\\\"Converter creation failed: {e}\\\"}))\\n                return\\n\\n            # --- process files --------------------------------------------------\\n            results = []\\n            for fp in file_paths:\\n                try:\\n                    res = converter.convert(fp)\\n                    ok = False\\n                    if hasattr(res, \\\"status\\\"):\\n                        try:\\n                            ok = res.status == ConversionStatus.SUCCESS\\n                        except Exception:\\n                            ok = str(res.status).lower() == \\\"success\\\"\\n                    if not ok and getattr(res, \\\"document\\\", None) is not None:\\n                        ok = True\\n                    if ok and res.document is not None:\\n                        doc_json = res.document.export_to_dict()\\n                        results.append({\\n                            \\\"document\\\": doc_json,\\n                            \\\"file_path\\\": str(fp),\\n                            \\\"status\\\": \\\"SUCCESS\\\",\\n                        })\\n                    else:\\n                        results.append(None)\\n                except Exception as e:\\n                    sys.stderr.write(f\\\"Error processing {fp}: {e}\\\\n\\\")\\n                    results.append(None)\\n\\n            print(json.dumps({\\\"ok\\\": True, \\\"results\\\": results}))\\n\\n        if __name__ == \\\"__main__\\\":\\n            main()\\n    \\\"\\\"\\\")\\n\\n    def process_files(self, file_list: list[BaseFileComponent.BaseFile]) -> list[BaseFileComponent.BaseFile]:\\n        # Check that docling is installed without actually importing it.\\n        # The real import (PyTorch, transformers, etc.) happens in the child\\n        # subprocess.  Importing it here would spike memory and get the\\n        # Gunicorn worker SIGKILL'd by the OOM killer.\\n        import importlib.util\\n\\n        if importlib.util.find_spec(\\\"docling\\\") is None:\\n            msg = (\\n                \\\"Docling is an optional dependency. Install with `uv pip install 'langflow[docling]'` or \\\"\\n                \\\"`uv pip install 'lfx-docling[local]'`.\\\"\\n            )\\n            raise ImportError(msg)\\n\\n        file_paths = [str(file.path) for file in file_list if file.path]\\n\\n        if not file_paths:\\n            self.log(\\\"No files to process.\\\")\\n            return file_list\\n\\n        pic_desc_config: dict | None = None\\n        if self.pic_desc_llm is not None:\\n            pic_desc_config = _serialize_pydantic_model(self.pic_desc_llm)\\n\\n        args = {\\n            \\\"file_paths\\\": file_paths,\\n            \\\"pipeline\\\": self.pipeline,\\n            \\\"ocr_engine\\\": self.ocr_engine,\\n            \\\"do_picture_classification\\\": self.do_picture_classification,\\n            \\\"pic_desc_config\\\": pic_desc_config,\\n            \\\"pic_desc_prompt\\\": self.pic_desc_prompt,\\n        }\\n\\n        # Use Popen with a polling loop (same pattern as Read File advanced mode).\\n        # This avoids multiprocessing/threading issues under Gunicorn and keeps the\\n        # SSE event stream alive via periodic heartbeat logs.\\n        docling_timeout = 600  # 10 minutes\\n        poll_interval = 5\\n\\n        # Use a temporary file for stdout to avoid pipe buffer deadlocks.\\n        # Docling (and its transitive imports: PyTorch, transformers, etc.) can\\n        # write large amounts of output.  With subprocess.PIPE the OS pipe\\n        # buffer (~16 KB on macOS) fills up, the child blocks on write, and the\\n        # parent - which only reads *after* the child exits - waits forever.\\n        import tempfile\\n\\n        with tempfile.TemporaryFile() as stdout_file, tempfile.TemporaryFile() as stderr_file:\\n            proc = subprocess.Popen(  # noqa: S603\\n                [sys.executable, \\\"-u\\\", \\\"-c\\\", self._CHILD_SCRIPT],\\n                stdin=subprocess.PIPE,\\n                stdout=stdout_file,\\n                stderr=stderr_file,\\n            )\\n            proc.stdin.write(json.dumps(args).encode(\\\"utf-8\\\"))\\n            proc.stdin.close()\\n\\n            start = time.monotonic()\\n            while proc.poll() is None:\\n                elapsed = time.monotonic() - start\\n                if elapsed >= docling_timeout:\\n                    proc.kill()\\n                    proc.wait()\\n                    msg = (\\n                        f\\\"Docling processing timed out after {docling_timeout}s. Try processing fewer or smaller files.\\\"\\n                    )\\n                    raise TimeoutError(msg)\\n                self.log(f\\\"Docling processing in progress ({int(elapsed)}s elapsed)...\\\")\\n                time.sleep(poll_interval)\\n\\n            stdout_file.seek(0)\\n            stderr_file.seek(0)\\n            stdout_bytes = stdout_file.read()\\n            stderr_bytes = stderr_file.read()\\n\\n        if not stdout_bytes:\\n            err_msg = stderr_bytes.decode(\\\"utf-8\\\", errors=\\\"replace\\\") if stderr_bytes else \\\"no output\\\"\\n            msg = f\\\"Docling subprocess error: {err_msg}\\\"\\n            raise RuntimeError(msg)\\n\\n        try:\\n            payload = json.loads(stdout_bytes.decode(\\\"utf-8\\\"))\\n        except Exception as e:\\n            err_msg = stderr_bytes.decode(\\\"utf-8\\\", errors=\\\"replace\\\")\\n            msg = f\\\"Invalid JSON from Docling subprocess: {e}. stderr={err_msg}\\\"\\n            raise RuntimeError(msg) from e\\n\\n        if not payload.get(\\\"ok\\\"):\\n            error_msg = payload.get(\\\"error\\\", \\\"Unknown Docling error\\\")\\n            if \\\"not installed\\\" in error_msg.lower():\\n                raise ImportError(error_msg)\\n            raise RuntimeError(error_msg)\\n\\n        # Reconstruct DoclingDocument objects from JSON dicts returned by the child\\n        from docling_core.types.doc import DoclingDocument\\n\\n        raw_results = payload.get(\\\"results\\\", [])\\n        processed_data: list[Data | None] = []\\n        for r in raw_results:\\n            if r is None:\\n                processed_data.append(None)\\n                continue\\n            try:\\n                doc = DoclingDocument.model_validate(r[\\\"document\\\"])\\n            except Exception:  # noqa: BLE001\\n                # Fall back to keeping the raw dict if validation fails\\n                doc = r[\\\"document\\\"]\\n            processed_data.append(Data(data={\\\"doc\\\": doc, \\\"file_path\\\": r[\\\"file_path\\\"]}))\\n\\n        return self.rollup_data(file_list, processed_data)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/docling/src/lfx_docling/components/docling/docling_remote.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"08849b9fcc0fdf203ca18c3cf98b4996512c74e02e60eb4383585f25b67bb6d6\",\"content\":\"from __future__ import annotations\\n\\nimport base64\\nimport json\\nimport time\\nfrom concurrent.futures import Future, ThreadPoolExecutor\\nfrom pathlib import Path  # noqa: TC003\\nfrom typing import Any\\n\\nimport httpx\\nfrom lfx.base.data import BaseFileComponent\\nfrom lfx.base.data.docling_utils import coerce_docling_document\\nfrom lfx.inputs import IntInput, NestedDictInput, StrInput, TableInput\\nfrom lfx.inputs.inputs import FloatInput\\nfrom lfx.schema import Data, DataFrame, dotdict\\nfrom lfx.utils.ssrf_httpx import ssrf_protected_httpx_client_kwargs_for_url\\nfrom lfx.utils.util import transform_localhost_url\\n\\n\\nclass DoclingRemoteComponent(BaseFileComponent):\\n    display_name = \\\"Docling Serve\\\"\\n    description = \\\"Uses Docling to process input documents connecting to your instance of Docling Serve.\\\"\\n    documentation = \\\"https://docling-project.github.io/docling/\\\"\\n    trace_type = \\\"tool\\\"\\n    icon = \\\"Docling\\\"\\n    name = \\\"DoclingRemote\\\"\\n\\n    MAX_500_RETRIES = 5\\n\\n    # https://docling-project.github.io/docling/usage/supported_formats/\\n    VALID_EXTENSIONS = [\\n        \\\"adoc\\\",\\n        \\\"asciidoc\\\",\\n        \\\"asc\\\",\\n        \\\"bmp\\\",\\n        \\\"csv\\\",\\n        \\\"dotx\\\",\\n        \\\"dotm\\\",\\n        \\\"docm\\\",\\n        \\\"docx\\\",\\n        \\\"htm\\\",\\n        \\\"html\\\",\\n        \\\"jpeg\\\",\\n        \\\"jpg\\\",\\n        \\\"json\\\",\\n        \\\"md\\\",\\n        \\\"pdf\\\",\\n        \\\"png\\\",\\n        \\\"potx\\\",\\n        \\\"ppsx\\\",\\n        \\\"pptm\\\",\\n        \\\"potm\\\",\\n        \\\"ppsm\\\",\\n        \\\"pptx\\\",\\n        \\\"tiff\\\",\\n        \\\"txt\\\",\\n        \\\"xls\\\",\\n        \\\"xlsx\\\",\\n        \\\"xhtml\\\",\\n        \\\"xml\\\",\\n        \\\"webp\\\",\\n    ]\\n\\n    inputs = [\\n        *BaseFileComponent.get_base_inputs(),\\n        StrInput(\\n            name=\\\"api_url\\\",\\n            display_name=\\\"Server address\\\",\\n            info=\\\"URL of the Docling Serve instance.\\\",\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"task_id\\\",\\n            display_name=\\\"Task ID\\\",\\n            info=(\\n                \\\"Optional task ID from a previous Docling Serve upload. \\\"\\n                \\\"If provided, file input is ignored and the component polls for this task's results.\\\"\\n            ),\\n            required=False,\\n        ),\\n        IntInput(\\n            name=\\\"max_concurrency\\\",\\n            display_name=\\\"Concurrency\\\",\\n            info=\\\"Maximum number of concurrent requests for the server.\\\",\\n            advanced=True,\\n            value=2,\\n            input_types=[\\\"Message\\\"],\\n        ),\\n        FloatInput(\\n            name=\\\"max_poll_timeout\\\",\\n            display_name=\\\"Maximum poll time\\\",\\n            info=\\\"Maximum waiting time for the document conversion to complete.\\\",\\n            advanced=True,\\n            value=3600,\\n            input_types=[\\\"Message\\\"],\\n        ),\\n        TableInput(\\n            name=\\\"api_headers\\\",\\n            display_name=\\\"HTTP headers\\\",\\n            advanced=True,\\n            required=False,\\n            info=(\\\"Optional headers required for connecting to Docling Serve.\\\"),\\n            table_schema=[\\n                {\\n                    \\\"name\\\": \\\"key\\\",\\n                    \\\"display_name\\\": \\\"Key\\\",\\n                    \\\"type\\\": \\\"string\\\",\\n                    \\\"description\\\": \\\"Key name\\\",\\n                },\\n                {\\n                    \\\"name\\\": \\\"value\\\",\\n                    \\\"display_name\\\": \\\"Value\\\",\\n                    \\\"load_from_db\\\": True,\\n                    \\\"type\\\": \\\"string\\\",\\n                    \\\"description\\\": \\\"Value of the header\\\",\\n                },\\n            ],\\n            value=[],\\n            real_time_refresh=True,\\n            input_types=[\\\"Data\\\", \\\"JSON\\\"],\\n        ),\\n        NestedDictInput(\\n            name=\\\"docling_serve_opts\\\",\\n            display_name=\\\"Docling options\\\",\\n            advanced=True,\\n            required=False,\\n            info=(\\n                \\\"Optional dictionary of additional options. \\\"\\n                \\\"See https://github.com/docling-project/docling-serve/blob/main/docs/usage.md for more information.\\\"\\n            ),\\n            input_types=[\\\"Message\\\"],\\n        ),\\n    ]\\n\\n    outputs = [\\n        *BaseFileComponent.get_base_outputs(),\\n    ]\\n\\n    def build(self) -> DataFrame:\\n        # Static bundle validation cannot see BaseFileComponent's inherited output method.\\n        return self.load_files()\\n\\n    @staticmethod\\n    def _add_header(headers: dict[str, str], key: Any, value: Any) -> None:\\n        key_str = str(key).strip()\\n        if not key_str or key_str == \\\"None\\\":\\n            return\\n        headers[key_str] = str(value)\\n\\n    def _process_headers_input(self, headers_input: Any, component_headers_dict: dict[str, str]) -> None:\\n        if not headers_input:\\n            return\\n\\n        items = headers_input if isinstance(headers_input, list) else [headers_input]\\n\\n        for item in items:\\n            if not item:\\n                continue\\n\\n            # Case 1: Data object\\n            if hasattr(item, \\\"data\\\") and isinstance(item.data, dict):\\n                data = item.data\\n                if \\\"key\\\" in data and \\\"value\\\" in data:\\n                    self._add_header(component_headers_dict, data[\\\"key\\\"], data[\\\"value\\\"])\\n                else:\\n                    # Fallback: merge all keys from Data object\\n                    for k, v in data.items():\\n                        if k not in (\\\"text_key\\\", \\\"default_value\\\"):\\n                            self._add_header(component_headers_dict, k, v)\\n\\n            # Case 2: Dictionary (Table row)\\n            elif isinstance(item, dict):\\n                if \\\"key\\\" in item and \\\"value\\\" in item:\\n                    self._add_header(component_headers_dict, item[\\\"key\\\"], item[\\\"value\\\"])\\n                else:\\n                    # Fallback: merge all keys\\n                    for k, v in item.items():\\n                        self._add_header(component_headers_dict, k, v)\\n\\n            # Case 3: Message object\\n            elif hasattr(item, \\\"text\\\") and isinstance(item.text, str):\\n                try:\\n                    parsed = json.loads(item.text)\\n                    if isinstance(parsed, dict):\\n                        for k, v in parsed.items():\\n                            self._add_header(component_headers_dict, k, v)\\n                except json.JSONDecodeError:\\n                    pass\\n\\n    def _process_headers(self) -> dict[str, str]:\\n        \\\"\\\"\\\"Process the headers input into a valid dictionary.\\\"\\\"\\\"\\n        component_headers_dict: dict[str, str] = {}\\n        self._process_headers_input(self.api_headers, component_headers_dict)\\n        return component_headers_dict\\n\\n    def update_build_config(self, build_config: dotdict, field_value: Any, field_name: str | None = None) -> dotdict:\\n        if field_name == \\\"api_headers\\\":\\n            if isinstance(field_value, dict):\\n                build_config[\\\"api_headers\\\"][\\\"value\\\"] = [{\\\"key\\\": k, \\\"value\\\": v} for k, v in field_value.items()]\\n                return build_config\\n            if field_value is None:\\n                build_config[\\\"api_headers\\\"][\\\"value\\\"] = []\\n                return build_config\\n\\n        # Default behavior\\n        return super().update_build_config(build_config, field_value, field_name)\\n\\n    def _poll_and_fetch_result(\\n        self, client: httpx.Client, base_url: str, task_id: str, file_path: str | None = None\\n    ) -> Data | None:\\n        \\\"\\\"\\\"Poll for task completion and fetch the result.\\n\\n        Args:\\n            client: The HTTP client to use for requests.\\n            base_url: The base URL of the Docling Serve API.\\n            task_id: The task ID to poll for.\\n            file_path: Optional file path to include in the result data.\\n\\n        Returns:\\n            Data object with the DoclingDocument, or None if processing failed.\\n        \\\"\\\"\\\"\\n        http_failures = 0\\n        retry_status_start = 500\\n        retry_status_end = 600\\n        start_wait_time = time.monotonic()\\n\\n        task_status = None\\n        while task_status not in (\\\"success\\\", \\\"failure\\\"):\\n            processing_time = time.monotonic() - start_wait_time\\n            if processing_time >= self.max_poll_timeout:\\n                msg = (\\n                    f\\\"Processing time {processing_time=} exceeds the maximum poll timeout {self.max_poll_timeout=}.\\\"\\n                    \\\"Please increase the max_poll_timeout parameter or review why the processing \\\"\\n                    \\\"takes long on the server.\\\"\\n                )\\n                self.log(msg)\\n                raise RuntimeError(msg)\\n\\n            response = client.get(f\\\"{base_url}/status/poll/{task_id}\\\")\\n\\n            if retry_status_start <= response.status_code < retry_status_end:\\n                http_failures += 1\\n                if http_failures > self.MAX_500_RETRIES:\\n                    self.log(f\\\"The status requests got a http response {response.status_code} too many times.\\\")\\n                    return None\\n                time.sleep(2)\\n                continue\\n\\n            response.raise_for_status()\\n            task = response.json()\\n            task_status = task[\\\"task_status\\\"]\\n            if task_status not in (\\\"success\\\", \\\"failure\\\"):\\n                time.sleep(2)\\n\\n        result_resp = client.get(f\\\"{base_url}/result/{task_id}\\\")\\n        result_resp.raise_for_status()\\n        result = result_resp.json()\\n\\n        if result.get(\\\"status\\\") == \\\"failure\\\" or result.get(\\\"errors\\\"):\\n            errors = result.get(\\\"errors\\\", [])\\n            err_msg_list = []\\n            for err in errors:\\n                if isinstance(err, dict) and \\\"error_message\\\" in err:\\n                    err_msg_list.append(err[\\\"error_message\\\"])\\n                elif isinstance(err, str):\\n                    err_msg_list.append(err)\\n\\n            err_details = \\\"; \\\".join(err_msg_list) if err_msg_list else \\\"Unknown Docling processing error\\\"\\n\\n            msg = f\\\"Docling processing failed: {err_details}\\\"\\n            raise ValueError(msg)\\n\\n        if \\\"json_content\\\" not in result[\\\"document\\\"] or result[\\\"document\\\"][\\\"json_content\\\"] is None:\\n            self.log(\\\"No JSON DoclingDocument found in the result.\\\")\\n            return None\\n\\n        try:\\n            doc = coerce_docling_document(result[\\\"document\\\"][\\\"json_content\\\"])\\n            data_dict: dict[str, Any] = {\\\"doc\\\": doc}\\n            if file_path:\\n                data_dict[\\\"file_path\\\"] = file_path\\n            return Data(data=data_dict)\\n        except Exception as e:  # noqa: BLE001\\n            self.log(f\\\"Error validating the document. {e}\\\")\\n            return None\\n\\n    def _process_task_id(self) -> list[Data]:\\n        \\\"\\\"\\\"Process an existing task by polling for status and retrieving results.\\n\\n        Returns:\\n            List containing the result Data object, or empty list if processing failed.\\n        \\\"\\\"\\\"\\n        transformed_url = transform_localhost_url(self.api_url)\\n        base_url = f\\\"{transformed_url}/v1\\\"\\n\\n        with self._create_http_client(base_url) as client:\\n            result = self._poll_and_fetch_result(client, base_url, self.task_id)\\n            return [result] if result else []\\n\\n    def _create_http_client(self, base_url: str) -> httpx.Client:\\n        client_kwargs, _ = ssrf_protected_httpx_client_kwargs_for_url(base_url)\\n        return httpx.Client(headers=self._process_headers(), **client_kwargs)\\n\\n    def load_files_base(self) -> list[Data]:\\n        \\\"\\\"\\\"Load and process files, or poll an existing task if task_id is provided.\\n\\n        Returns:\\n            list[Data]: Parsed data from the processed files or task.\\n        \\\"\\\"\\\"\\n        if self.task_id:\\n            return self._process_task_id()\\n        return super().load_files_base()\\n\\n    def process_files(self, file_list: list[BaseFileComponent.BaseFile]) -> list[BaseFileComponent.BaseFile]:\\n        transformed_url = transform_localhost_url(self.api_url)\\n        base_url = f\\\"{transformed_url}/v1\\\"\\n\\n        def _convert_document(client: httpx.Client, file_path: Path, options: dict[str, Any]) -> Data | None:\\n            encoded_doc = base64.b64encode(file_path.read_bytes()).decode()\\n            payload = {\\n                \\\"options\\\": options,\\n                \\\"sources\\\": [{\\\"kind\\\": \\\"file\\\", \\\"base64_string\\\": encoded_doc, \\\"filename\\\": file_path.name}],\\n            }\\n\\n            response = client.post(f\\\"{base_url}/convert/source/async\\\", json=payload)\\n            response.raise_for_status()\\n            task = response.json()\\n\\n            return self._poll_and_fetch_result(client, base_url, task[\\\"task_id\\\"], str(file_path))\\n\\n        docling_options = {\\n            \\\"to_formats\\\": [\\\"json\\\"],\\n            \\\"image_export_mode\\\": \\\"placeholder\\\",\\n            **(self.docling_serve_opts or {}),\\n        }\\n\\n        processed_data: list[Data | None] = []\\n        with (\\n            self._create_http_client(base_url) as client,\\n            ThreadPoolExecutor(max_workers=self.max_concurrency) as executor,\\n        ):\\n            futures: list[tuple[int, Future]] = []\\n            for i, file in enumerate(file_list):\\n                if file.path is None:\\n                    processed_data.append(None)\\n                    continue\\n\\n                futures.append((i, executor.submit(_convert_document, client, file.path, docling_options)))\\n\\n            for _index, future in futures:\\n                try:\\n                    result_data = future.result()\\n                    processed_data.append(result_data)\\n                except (httpx.HTTPStatusError, httpx.RequestError, KeyError, ValueError) as exc:\\n                    self.log(f\\\"Docling remote processing failed: {exc}\\\")\\n                    raise\\n\\n        return self.rollup_data(file_list, processed_data)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/docling/src/lfx_docling/components/docling/export_docling_document.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f601ac44a05030d450c7c712916ca1052950942eef1edff3d38b7b7db5922283\",\"content\":\"from typing import Any\\n\\nfrom lfx.base.data.docling_utils import coerce_docling_document, extract_docling_documents, get_docling_image_ref_mode\\nfrom lfx.custom import Component\\nfrom lfx.io import DropdownInput, HandleInput, MessageTextInput, Output, StrInput\\nfrom lfx.schema import Data, DataFrame\\n\\n\\nclass ExportDoclingDocumentComponent(Component):\\n    display_name: str = \\\"Export DoclingDocument\\\"\\n    description: str = \\\"Export DoclingDocument to markdown, html or other formats.\\\"\\n    documentation = \\\"https://docling-project.github.io/docling/\\\"\\n    icon = \\\"Docling\\\"\\n    name = \\\"ExportDoclingDocument\\\"\\n\\n    inputs = [\\n        HandleInput(\\n            name=\\\"data_inputs\\\",\\n            display_name=\\\"JSON or Table\\\",\\n            info=\\\"The data with documents to export.\\\",\\n            input_types=[\\\"Data\\\", \\\"JSON\\\", \\\"DataFrame\\\", \\\"Table\\\"],\\n            required=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"export_format\\\",\\n            display_name=\\\"Export format\\\",\\n            options=[\\\"Markdown\\\", \\\"HTML\\\", \\\"Plaintext\\\", \\\"DocTags\\\"],\\n            info=\\\"Select the export format to convert the input.\\\",\\n            value=\\\"Markdown\\\",\\n            real_time_refresh=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"image_mode\\\",\\n            display_name=\\\"Image export mode\\\",\\n            options=[\\\"placeholder\\\", \\\"embedded\\\"],\\n            info=(\\n                \\\"Specify how images are exported in the output. Placeholder will replace the images with a string, \\\"\\n                \\\"whereas Embedded will include them as base64 encoded images.\\\"\\n            ),\\n            value=\\\"placeholder\\\",\\n        ),\\n        StrInput(\\n            name=\\\"md_image_placeholder\\\",\\n            display_name=\\\"Image placeholder\\\",\\n            info=\\\"Specify the image placeholder for markdown exports.\\\",\\n            value=\\\"<!-- image -->\\\",\\n            advanced=True,\\n        ),\\n        StrInput(\\n            name=\\\"md_page_break_placeholder\\\",\\n            display_name=\\\"Page break placeholder\\\",\\n            info=\\\"Add this placeholder between pages in the markdown output.\\\",\\n            value=\\\"\\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"doc_key\\\",\\n            display_name=\\\"Doc Key\\\",\\n            info=\\\"The key to use for the DoclingDocument column.\\\",\\n            value=\\\"doc\\\",\\n            advanced=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Exported data\\\", name=\\\"data\\\", method=\\\"export_document\\\"),\\n        Output(display_name=\\\"Table\\\", name=\\\"dataframe\\\", method=\\\"as_dataframe\\\"),\\n    ]\\n\\n    def update_build_config(self, build_config: dict, field_value: Any, field_name: str | None = None) -> dict:\\n        if field_name == \\\"export_format\\\" and field_value == \\\"Markdown\\\":\\n            build_config[\\\"md_image_placeholder\\\"][\\\"show\\\"] = True\\n            build_config[\\\"md_page_break_placeholder\\\"][\\\"show\\\"] = True\\n            build_config[\\\"image_mode\\\"][\\\"show\\\"] = True\\n        elif field_name == \\\"export_format\\\" and field_value == \\\"HTML\\\":\\n            build_config[\\\"md_image_placeholder\\\"][\\\"show\\\"] = False\\n            build_config[\\\"md_page_break_placeholder\\\"][\\\"show\\\"] = False\\n            build_config[\\\"image_mode\\\"][\\\"show\\\"] = True\\n        elif field_name == \\\"export_format\\\" and field_value in {\\\"Plaintext\\\", \\\"DocTags\\\"}:\\n            build_config[\\\"md_image_placeholder\\\"][\\\"show\\\"] = False\\n            build_config[\\\"md_page_break_placeholder\\\"][\\\"show\\\"] = False\\n            build_config[\\\"image_mode\\\"][\\\"show\\\"] = False\\n\\n        return build_config\\n\\n    def _get_image_mode(self) -> Any:\\n        return get_docling_image_ref_mode(self.image_mode)\\n\\n    @staticmethod\\n    def _coerce_exportable_document(doc: Any) -> Any:\\n        return coerce_docling_document(doc)\\n\\n    def export_document(self) -> list[Data]:\\n        documents, warning = extract_docling_documents(self.data_inputs, self.doc_key)\\n        if warning:\\n            self.status = warning\\n\\n        results: list[Data] = []\\n        try:\\n            image_mode = self._get_image_mode()\\n            for raw_doc in documents:\\n                doc = self._coerce_exportable_document(raw_doc)\\n                content = \\\"\\\"\\n                if self.export_format == \\\"Markdown\\\":\\n                    content = doc.export_to_markdown(\\n                        image_mode=image_mode,\\n                        image_placeholder=self.md_image_placeholder,\\n                        page_break_placeholder=self.md_page_break_placeholder,\\n                    )\\n                elif self.export_format == \\\"HTML\\\":\\n                    content = doc.export_to_html(image_mode=image_mode)\\n                elif self.export_format == \\\"Plaintext\\\":\\n                    content = doc.export_to_text()\\n                elif self.export_format == \\\"DocTags\\\":\\n                    content = doc.export_to_doctags()\\n\\n                # Preserve metadata from the DoclingDocument\\n                metadata: dict = {\\\"export_format\\\": self.export_format}\\n                if hasattr(doc, \\\"name\\\") and doc.name:\\n                    metadata[\\\"name\\\"] = doc.name\\n                if hasattr(doc, \\\"origin\\\") and doc.origin is not None:\\n                    if hasattr(doc.origin, \\\"filename\\\") and doc.origin.filename:\\n                        metadata[\\\"filename\\\"] = doc.origin.filename\\n                    if hasattr(doc.origin, \\\"binary_hash\\\") and doc.origin.binary_hash:\\n                        metadata[\\\"document_id\\\"] = str(doc.origin.binary_hash)\\n                    if hasattr(doc.origin, \\\"mimetype\\\") and doc.origin.mimetype:\\n                        metadata[\\\"mimetype\\\"] = doc.origin.mimetype\\n\\n                results.append(Data(text=content, data={\\\"text\\\": content, **metadata}))\\n        except Exception as e:\\n            msg = f\\\"Error exporting document: {e}\\\"\\n            raise TypeError(msg) from e\\n\\n        return results\\n\\n    def as_dataframe(self) -> DataFrame:\\n        return DataFrame(self.export_document())\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/docling/src/lfx_docling/extension.json\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5feff893d4de0ff1c3ab1efb943d8405caf13b6e6491856e6c4d0bb907f92bc9\",\"content\":\"{\\n  \\\"$schema\\\": \\\"https://schemas.langflow.org/extension/v1.json\\\",\\n  \\\"id\\\": \\\"lfx-docling\\\",\\n  \\\"version\\\": \\\"0.1.7\\\",\\n  \\\"name\\\": \\\"Docling\\\",\\n  \\\"description\\\": \\\"Docling document processing components as a standalone Langflow Extension Bundle.\\\",\\n  \\\"lfx\\\": {\\n    \\\"compat\\\": [\\\"1\\\"]\\n  },\\n  \\\"bundles\\\": [\\n    {\\n      \\\"name\\\": \\\"docling\\\",\\n      \\\"path\\\": \\\"components/docling\\\"\\n    }\\n  ]\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/docling/tests/test_chunk_docling_document_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"68a64da2bf5697047c32536db496ff96ac81821e64a5dc08ff5d1fdc33a7ab0b\",\"content\":\"\\\"\\\"\\\"Tests for ChunkDoclingDocumentComponent HybridChunker parameters.\\\"\\\"\\\"\\n\\nimport builtins\\nimport sys\\nimport types\\n\\nimport pytest\\nfrom lfx_docling.components.docling.chunk_docling_document import (\\n    ChunkDoclingDocumentComponent,\\n    _load_docling_chunker_dependencies,\\n)\\n\\n\\ndef _base_build_config():\\n    return {\\n        \\\"chunker\\\": {\\\"value\\\": \\\"HybridChunker\\\"},\\n        \\\"provider\\\": {\\\"value\\\": \\\"Hugging Face\\\", \\\"show\\\": True},\\n        \\\"hf_model_name\\\": {\\\"show\\\": True},\\n        \\\"openai_model_name\\\": {\\\"show\\\": False},\\n        \\\"max_tokens\\\": {\\\"show\\\": True},\\n        \\\"merge_peers\\\": {\\\"show\\\": False},\\n        \\\"always_emit_headings\\\": {\\\"show\\\": False},\\n    }\\n\\n\\nclass TestChunkDoclingDocumentComponentBuildConfig:\\n    def test_update_build_config_hybrid_shows_chunker_fields(self):\\n        component = ChunkDoclingDocumentComponent()\\n        build_config = _base_build_config()\\n\\n        result = component.update_build_config(build_config, field_value=\\\"HybridChunker\\\", field_name=\\\"chunker\\\")\\n\\n        assert result[\\\"provider\\\"][\\\"show\\\"] is True\\n        assert result[\\\"hf_model_name\\\"][\\\"show\\\"] is True\\n        assert result[\\\"openai_model_name\\\"][\\\"show\\\"] is False\\n        assert result[\\\"max_tokens\\\"][\\\"show\\\"] is True\\n        assert result[\\\"merge_peers\\\"][\\\"show\\\"] is True\\n        assert result[\\\"always_emit_headings\\\"][\\\"show\\\"] is True\\n\\n    def test_update_build_config_hierarchical_hides_hybrid_fields(self):\\n        component = ChunkDoclingDocumentComponent()\\n        build_config = _base_build_config()\\n\\n        result = component.update_build_config(build_config, field_value=\\\"HierarchicalChunker\\\", field_name=\\\"chunker\\\")\\n\\n        assert result[\\\"provider\\\"][\\\"show\\\"] is False\\n        assert result[\\\"hf_model_name\\\"][\\\"show\\\"] is False\\n        assert result[\\\"openai_model_name\\\"][\\\"show\\\"] is False\\n        assert result[\\\"max_tokens\\\"][\\\"show\\\"] is False\\n        assert result[\\\"merge_peers\\\"][\\\"show\\\"] is False\\n        assert result[\\\"always_emit_headings\\\"][\\\"show\\\"] is False\\n\\n    def test_update_build_config_provider_toggle(self):\\n        component = ChunkDoclingDocumentComponent()\\n        build_config = _base_build_config()\\n\\n        result = component.update_build_config(build_config, field_value=\\\"OpenAI\\\", field_name=\\\"provider\\\")\\n\\n        assert result[\\\"hf_model_name\\\"][\\\"show\\\"] is False\\n        assert result[\\\"openai_model_name\\\"][\\\"show\\\"] is True\\n\\n\\nclass TestChunkDoclingDocumentComponentHybridChunker:\\n    def _run_chunk_documents_with_mocks(\\n        self, monkeypatch, *, chunker_name, merge_peers_input, always_emit_headings_input\\n    ):\\n        captured = {}\\n\\n        class DummyHybridChunker:\\n            def __init__(self, tokenizer, *, merge_peers=False, always_emit_headings=False):\\n                captured[\\\"tokenizer\\\"] = tokenizer\\n                captured[\\\"merge_peers\\\"] = merge_peers\\n                captured[\\\"always_emit_headings\\\"] = always_emit_headings\\n\\n            def chunk(self, _dl_doc=None, **_kwargs):\\n                return []\\n\\n            def contextualize(self, _chunk=None, **_kwargs):\\n                return \\\"\\\"\\n\\n        class DummyHierarchicalChunker:\\n            def __init__(self):\\n                captured[\\\"hierarchical_called\\\"] = True\\n\\n            def chunk(self, **_kwargs):\\n                return []\\n\\n            def contextualize(self, **_kwargs):\\n                return \\\"\\\"\\n\\n        class DummyDocMeta:\\n            @classmethod\\n            def model_validate(cls, meta):\\n                return meta\\n\\n        class DummyTokenizer:\\n            @classmethod\\n            def from_pretrained(cls, model_name, max_tokens=None):\\n                captured[\\\"model_name\\\"] = model_name\\n                captured[\\\"max_tokens\\\"] = max_tokens\\n                return \\\"tokenizer\\\"\\n\\n        hybrid_chunker_module = types.ModuleType(\\\"docling_core.transforms.chunker.hybrid_chunker\\\")\\n        hybrid_chunker_module.HybridChunker = DummyHybridChunker\\n        monkeypatch.setitem(sys.modules, \\\"docling_core.transforms.chunker.hybrid_chunker\\\", hybrid_chunker_module)\\n\\n        tokenizer_module = types.ModuleType(\\\"docling_core.transforms.chunker.tokenizer\\\")\\n        huggingface_tokenizer_module = types.ModuleType(\\\"docling_core.transforms.chunker.tokenizer.huggingface\\\")\\n        huggingface_tokenizer_module.HuggingFaceTokenizer = DummyTokenizer\\n        tokenizer_module.huggingface = huggingface_tokenizer_module\\n        monkeypatch.setitem(sys.modules, \\\"docling_core.transforms.chunker.tokenizer\\\", tokenizer_module)\\n        monkeypatch.setitem(\\n            sys.modules,\\n            \\\"docling_core.transforms.chunker.tokenizer.huggingface\\\",\\n            huggingface_tokenizer_module,\\n        )\\n        monkeypatch.setattr(\\n            \\\"lfx_docling.components.docling.chunk_docling_document._load_docling_chunker_dependencies\\\",\\n            lambda: (DummyDocMeta, DummyHierarchicalChunker),\\n        )\\n        monkeypatch.setattr(\\n            \\\"lfx_docling.components.docling.chunk_docling_document.extract_docling_documents\\\",\\n            lambda *_args, **_kwargs: ([], None),\\n        )\\n\\n        component = ChunkDoclingDocumentComponent()\\n        component._attributes = {\\n            \\\"data_inputs\\\": None,\\n            \\\"chunker\\\": chunker_name,\\n            \\\"provider\\\": \\\"Hugging Face\\\",\\n            \\\"hf_model_name\\\": \\\"sentence-transformers/all-MiniLM-L6-v2\\\",\\n            \\\"max_tokens\\\": 256,\\n            \\\"merge_peers\\\": merge_peers_input,\\n            \\\"always_emit_headings\\\": always_emit_headings_input,\\n            \\\"doc_key\\\": \\\"doc\\\",\\n        }\\n        component.chunk_documents()\\n        return captured\\n\\n    @pytest.mark.parametrize(\\n        (\\\"merge_peers_input\\\", \\\"expected_merge_peers\\\"),\\n        [\\n            (True, True),\\n            (False, False),\\n            (1, True),\\n            (0, False),\\n            (None, False),\\n        ],\\n    )\\n    def test_hybrid_chunker_receives_merge_peers(self, monkeypatch, merge_peers_input, expected_merge_peers):\\n        captured = self._run_chunk_documents_with_mocks(\\n            monkeypatch,\\n            chunker_name=\\\"HybridChunker\\\",\\n            merge_peers_input=merge_peers_input,\\n            always_emit_headings_input=False,\\n        )\\n        assert captured[\\\"model_name\\\"] == \\\"sentence-transformers/all-MiniLM-L6-v2\\\"\\n        assert captured[\\\"max_tokens\\\"] == 256\\n        assert captured[\\\"merge_peers\\\"] is expected_merge_peers\\n\\n    @pytest.mark.parametrize(\\n        (\\\"always_emit_headings_input\\\", \\\"expected_always_emit_headings\\\"),\\n        [\\n            (True, True),\\n            (False, False),\\n            (1, True),\\n            (0, False),\\n            (None, False),\\n        ],\\n    )\\n    def test_hybrid_chunker_receives_always_emit_headings(\\n        self, monkeypatch, always_emit_headings_input, expected_always_emit_headings\\n    ):\\n        captured = self._run_chunk_documents_with_mocks(\\n            monkeypatch,\\n            chunker_name=\\\"HybridChunker\\\",\\n            merge_peers_input=True,\\n            always_emit_headings_input=always_emit_headings_input,\\n        )\\n        assert captured[\\\"always_emit_headings\\\"] is expected_always_emit_headings\\n\\n    def test_hierarchical_chunker_instantiates_without_hybrid_kwargs(self, monkeypatch):\\n        captured = self._run_chunk_documents_with_mocks(\\n            monkeypatch,\\n            chunker_name=\\\"HierarchicalChunker\\\",\\n            merge_peers_input=True,\\n            always_emit_headings_input=True,\\n        )\\n        assert captured[\\\"hierarchical_called\\\"] is True\\n\\n    def test_missing_chunking_extra_has_actionable_error(self, monkeypatch):\\n        original_import = builtins.__import__\\n\\n        def fake_import(name, globals_=None, locals_=None, fromlist=(), level=0):\\n            if name in {\\n                \\\"docling_core.transforms.chunker.doc_chunk\\\",\\n                \\\"docling_core.transforms.chunker.hierarchical_chunker\\\",\\n            }:\\n                msg = \\\"Module requires 'chunking' extra\\\"\\n                raise RuntimeError(msg)\\n            return original_import(name, globals_, locals_, fromlist, level)\\n\\n        monkeypatch.setattr(builtins, \\\"__import__\\\", fake_import)\\n\\n        with pytest.raises(ImportError, match=r\\\"docling-chunking\\\"):\\n            _load_docling_chunker_dependencies()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/docling/tests/test_docling_remote.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"290e6a498f876323d9067bd05ffbebc7f46b8a84b89e0bbeadb956503ba36457\",\"content\":\"\\\"\\\"\\\"Tests for DoclingRemoteComponent compatibility and polling behavior.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nimport httpx\\nimport pytest\\n\\nif TYPE_CHECKING:\\n    from typing_extensions import Self\\n\\npytest.importorskip(\\\"docling_core\\\")\\n\\n# NOTE: Import the bundle component module before lfx.inputs/lfx.schema. Importing\\n# lfx.inputs/lfx.schema first leaves lfx.custom partially initialized and triggers a\\n# circular import when the component (a Component subclass) is imported afterwards.\\n# isort: off\\nfrom lfx_docling.components.docling import docling_remote\\nfrom lfx_docling.components.docling.docling_remote import DoclingRemoteComponent\\n\\nfrom lfx.inputs import TableInput\\nfrom lfx.schema import Data\\nfrom lfx.utils.ssrf_transport import SSRFProtectedSyncTransport\\n\\n# isort: on\\n\\n\\nclass _Message:\\n    def __init__(self, text: str) -> None:\\n        self.text = text\\n\\n\\n_UNSET = object()\\n\\n\\nclass _Response:\\n    def __init__(self, status_code: int, payload: Any = _UNSET) -> None:\\n        self.status_code = status_code\\n        self.payload = payload\\n        self.json_called = False\\n        self.request = httpx.Request(\\\"GET\\\", \\\"http://docling.test/v1/status/poll/task-1\\\")\\n        self.response = httpx.Response(status_code, request=self.request)\\n\\n    def raise_for_status(self) -> None:\\n        if self.status_code >= 400:\\n            msg = f\\\"HTTP error {self.status_code}\\\"\\n            raise httpx.HTTPStatusError(msg, request=self.request, response=self.response)\\n\\n    def json(self) -> Any:\\n        self.json_called = True\\n        if self.payload is _UNSET:\\n            msg = \\\"json() should not be called for this response\\\"\\n            raise AssertionError(msg)\\n        return self.payload\\n\\n\\nclass _Client:\\n    def __init__(self, responses: list[_Response]) -> None:\\n        self.responses = responses\\n        self.urls: list[str] = []\\n\\n    def get(self, url: str) -> _Response:\\n        self.urls.append(url)\\n        return self.responses.pop(0)\\n\\n\\nclass _ContextClient:\\n    def __enter__(self) -> Self:\\n        return self\\n\\n    def __exit__(self, *_args: object) -> None:\\n        return None\\n\\n\\ndef _input(name: str):\\n    return next(input_ for input_ in DoclingRemoteComponent.inputs if input_.name == name)\\n\\n\\ndef test_api_headers_uses_table_input_contract() -> None:\\n    api_headers = _input(\\\"api_headers\\\")\\n\\n    assert isinstance(api_headers, TableInput)\\n    assert api_headers.input_types == [\\\"Data\\\", \\\"JSON\\\"]\\n    columns = {column[\\\"name\\\"]: column for column in api_headers.table_schema}\\n    assert columns[\\\"key\\\"].get(\\\"load_from_db\\\") is not True\\n    assert columns[\\\"value\\\"].get(\\\"load_from_db\\\") is True\\n\\n\\ndef test_process_headers_skips_blank_and_none_keys_across_input_shapes() -> None:\\n    component = DoclingRemoteComponent()\\n    component._attributes.update(\\n        {\\n            \\\"api_headers\\\": [\\n                Data(data={\\\"key\\\": \\\" X-Data \\\", \\\"value\\\": \\\"data\\\"}),\\n                Data(data={\\\"key\\\": \\\" \\\", \\\"value\\\": \\\"skip\\\"}),\\n                Data(data={\\\"X-Data-Fallback\\\": \\\"fallback\\\", \\\"\\\": \\\"skip\\\", None: \\\"skip\\\"}),\\n                {\\\"key\\\": \\\"X-Table\\\", \\\"value\\\": 123},\\n                {\\\"key\\\": None, \\\"value\\\": \\\"skip\\\"},\\n                {\\\"X-Merged\\\": \\\"merged\\\", \\\"  \\\": \\\"skip\\\", \\\"None\\\": \\\"skip\\\"},\\n                _Message('{\\\" X-Message \\\": \\\"message\\\", \\\"\\\": \\\"skip\\\", \\\"None\\\": \\\"skip\\\"}'),\\n            ],\\n        }\\n    )\\n\\n    assert component._process_headers() == {\\n        \\\"X-Data\\\": \\\"data\\\",\\n        \\\"X-Data-Fallback\\\": \\\"fallback\\\",\\n        \\\"X-Table\\\": \\\"123\\\",\\n        \\\"X-Merged\\\": \\\"merged\\\",\\n        \\\"X-Message\\\": \\\"message\\\",\\n    }\\n\\n\\ndef test_update_build_config_migrates_dict_values_to_api_headers_table_rows() -> None:\\n    component = DoclingRemoteComponent()\\n    headers = {\\\"Authorization\\\": \\\"Bearer token\\\"}\\n    build_config = {\\n        \\\"api_headers\\\": {\\\"value\\\": []},\\n    }\\n\\n    updated = component.update_build_config(build_config, headers, \\\"api_headers\\\")\\n\\n    assert updated[\\\"api_headers\\\"][\\\"value\\\"] == [{\\\"key\\\": \\\"Authorization\\\", \\\"value\\\": \\\"Bearer token\\\"}]\\n\\n\\ndef test_poll_retries_initial_5xx_before_returning_none(monkeypatch: pytest.MonkeyPatch) -> None:\\n    monkeypatch.setattr(docling_remote.time, \\\"sleep\\\", lambda _seconds: None)\\n    component = DoclingRemoteComponent()\\n    component._attributes[\\\"max_poll_timeout\\\"] = 60\\n    responses = [_Response(500) for _ in range(component.MAX_500_RETRIES + 1)]\\n    client = _Client(responses)\\n\\n    result = component._poll_and_fetch_result(client, \\\"http://docling.test/v1\\\", \\\"task-1\\\")\\n\\n    assert result is None\\n    assert len(client.urls) == component.MAX_500_RETRIES + 1\\n\\n\\ndef test_poll_raises_later_4xx_before_json_parse(monkeypatch: pytest.MonkeyPatch) -> None:\\n    monkeypatch.setattr(docling_remote.time, \\\"sleep\\\", lambda _seconds: None)\\n    component = DoclingRemoteComponent()\\n    component._attributes[\\\"max_poll_timeout\\\"] = 60\\n    pending_response = _Response(200, {\\\"task_status\\\": \\\"pending\\\"})\\n    not_found_response = _Response(404)\\n    client = _Client([pending_response, not_found_response])\\n\\n    with pytest.raises(httpx.HTTPStatusError):\\n        component._poll_and_fetch_result(client, \\\"http://docling.test/v1\\\", \\\"task-1\\\")\\n\\n    assert pending_response.json_called is True\\n    assert not_found_response.json_called is False\\n\\n\\n@pytest.mark.parametrize(\\\"request_path\\\", [\\\"task\\\", \\\"files\\\"])\\ndef test_remote_request_paths_block_metadata_url_before_creating_client(\\n    monkeypatch: pytest.MonkeyPatch, request_path: str\\n) -> None:\\n    monkeypatch.setenv(\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\", \\\"true\\\")\\n    monkeypatch.delenv(\\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\", raising=False)\\n\\n    component = DoclingRemoteComponent()\\n    component._attributes.update(\\n        {\\n            \\\"api_url\\\": \\\"http://169.254.169.254/latest/meta-data\\\",\\n            \\\"api_headers\\\": [],\\n            \\\"docling_serve_opts\\\": {},\\n            \\\"max_concurrency\\\": 1,\\n            \\\"max_poll_timeout\\\": 60,\\n            \\\"task_id\\\": \\\"task-1\\\",\\n        }\\n    )\\n\\n    def fail_if_client_is_created(**_kwargs: Any) -> None:\\n        msg = \\\"HTTP client must not be created for a blocked URL\\\"\\n        raise AssertionError(msg)\\n\\n    monkeypatch.setattr(docling_remote.httpx, \\\"Client\\\", fail_if_client_is_created)\\n\\n    def invoke_request() -> None:\\n        if request_path == \\\"task\\\":\\n            component._process_task_id()\\n        else:\\n            component.process_files([])\\n\\n    with pytest.raises(ValueError, match=r\\\"SSRF Protection: .*blocked IP address\\\"):\\n        invoke_request()\\n\\n\\ndef test_process_task_id_pins_public_docling_host_and_preserves_headers(monkeypatch: pytest.MonkeyPatch) -> None:\\n    monkeypatch.setenv(\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\", \\\"true\\\")\\n    monkeypatch.delenv(\\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\", raising=False)\\n    monkeypatch.setattr(\\\"lfx.utils.ssrf_protection.resolve_hostname\\\", lambda _hostname: [\\\"93.184.216.34\\\"])\\n\\n    component = DoclingRemoteComponent()\\n    component._attributes.update(\\n        {\\n            \\\"api_url\\\": \\\"https://docling.example\\\",\\n            \\\"api_headers\\\": [{\\\"key\\\": \\\"Authorization\\\", \\\"value\\\": \\\"Bearer token\\\"}],\\n            \\\"max_poll_timeout\\\": 60,\\n            \\\"task_id\\\": \\\"task-1\\\",\\n        }\\n    )\\n    client_kwargs: dict[str, Any] = {}\\n\\n    def capture_client(**kwargs: Any) -> _ContextClient:\\n        client_kwargs.update(kwargs)\\n        return _ContextClient()\\n\\n    expected = Data(data={\\\"status\\\": \\\"success\\\"})\\n    monkeypatch.setattr(docling_remote.httpx, \\\"Client\\\", capture_client)\\n    monkeypatch.setattr(component, \\\"_poll_and_fetch_result\\\", lambda *_args, **_kwargs: expected)\\n\\n    result = component._process_task_id()\\n\\n    assert result[0] is expected\\n    assert client_kwargs[\\\"headers\\\"] == {\\\"Authorization\\\": \\\"Bearer token\\\"}\\n    assert client_kwargs[\\\"follow_redirects\\\"] is False\\n    assert isinstance(client_kwargs[\\\"transport\\\"], SSRFProtectedSyncTransport)\\n    assert client_kwargs[\\\"transport\\\"].pinned_ips == {\\\"docling.example\\\": [\\\"93.184.216.34\\\"]}\\n\\n\\ndef test_process_task_id_allows_explicitly_allowlisted_internal_docling(monkeypatch: pytest.MonkeyPatch) -> None:\\n    monkeypatch.setenv(\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\", \\\"true\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\", \\\"10.0.0.7\\\")\\n\\n    component = DoclingRemoteComponent()\\n    component._attributes.update(\\n        {\\n            \\\"api_url\\\": \\\"http://10.0.0.7:5001\\\",\\n            \\\"api_headers\\\": [],\\n            \\\"max_poll_timeout\\\": 60,\\n            \\\"task_id\\\": \\\"task-1\\\",\\n        }\\n    )\\n    client_kwargs: dict[str, Any] = {}\\n\\n    def capture_client(**kwargs: Any) -> _ContextClient:\\n        client_kwargs.update(kwargs)\\n        return _ContextClient()\\n\\n    expected = Data(data={\\\"status\\\": \\\"success\\\"})\\n    monkeypatch.setattr(docling_remote.httpx, \\\"Client\\\", capture_client)\\n    monkeypatch.setattr(component, \\\"_poll_and_fetch_result\\\", lambda *_args, **_kwargs: expected)\\n\\n    result = component._process_task_id()\\n\\n    assert result[0] is expected\\n    assert client_kwargs == {\\\"headers\\\": {}, \\\"follow_redirects\\\": False}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/docling/tests/test_export_docling_document_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"42b579ab95f7c30c5b8e3dd8f1a5749edf463e0ad74c17e077884ac1bea1040d\",\"content\":\"\\\"\\\"\\\"Tests for ExportDoclingDocumentComponent metadata preservation.\\\"\\\"\\\"\\n\\nfrom lfx_docling.components.docling.export_docling_document import ExportDoclingDocumentComponent\\n\\n\\nclass _FakeOrigin:\\n    \\\"\\\"\\\"Minimal stand-in for DoclingDocument.origin.\\\"\\\"\\\"\\n\\n    def __init__(self, *, filename=None, binary_hash=None, mimetype=None):\\n        self.filename = filename\\n        self.binary_hash = binary_hash\\n        self.mimetype = mimetype\\n\\n\\nclass _FakeDoclingDocument:\\n    \\\"\\\"\\\"Minimal stand-in for DoclingDocument with configurable metadata.\\\"\\\"\\\"\\n\\n    def __init__(self, *, name=None, origin=None, markdown_text=\\\"# Hello\\\"):\\n        self.name = name\\n        self.origin = origin\\n        self._markdown_text = markdown_text\\n\\n    def export_to_markdown(self, **_kwargs):\\n        return self._markdown_text\\n\\n    def export_to_text(self, **_kwargs):\\n        return self._markdown_text\\n\\n    def export_to_html(self, **_kwargs):\\n        return f\\\"<p>{self._markdown_text}</p>\\\"\\n\\n    def export_to_doctags(self, **_kwargs):\\n        return f\\\"<doc>{self._markdown_text}</doc>\\\"\\n\\n\\nclass TestExportDoclingDocumentMetadata:\\n    \\\"\\\"\\\"Verify that export_document preserves DoclingDocument metadata.\\\"\\\"\\\"\\n\\n    def _run_export(self, monkeypatch, fake_doc, export_format=\\\"Markdown\\\"):\\n        \\\"\\\"\\\"Helper: run export_document with a mocked extract_docling_documents.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\n            \\\"lfx_docling.components.docling.export_docling_document.extract_docling_documents\\\",\\n            lambda *_args, **_kwargs: ([fake_doc], None),\\n        )\\n\\n        component = ExportDoclingDocumentComponent()\\n        component._attributes = {\\n            \\\"data_inputs\\\": None,\\n            \\\"export_format\\\": export_format,\\n            \\\"image_mode\\\": \\\"placeholder\\\",\\n            \\\"md_image_placeholder\\\": \\\"<!-- image -->\\\",\\n            \\\"md_page_break_placeholder\\\": \\\"\\\",\\n            \\\"doc_key\\\": \\\"doc\\\",\\n        }\\n        return component.export_document()\\n\\n    def test_metadata_preserved_with_full_origin(self, monkeypatch):\\n        fake_doc = _FakeDoclingDocument(\\n            name=\\\"report.pdf\\\",\\n            origin=_FakeOrigin(\\n                filename=\\\"report.pdf\\\",\\n                binary_hash=\\\"abc123hash\\\",\\n                mimetype=\\\"application/pdf\\\",\\n            ),\\n            markdown_text=\\\"# Report\\\",\\n        )\\n\\n        results = self._run_export(monkeypatch, fake_doc)\\n\\n        assert len(results) == 1\\n        data = results[0]\\n        assert data.get_text() == \\\"# Report\\\"\\n        assert data.data[\\\"export_format\\\"] == \\\"Markdown\\\"\\n        assert data.data[\\\"name\\\"] == \\\"report.pdf\\\"\\n        assert data.data[\\\"filename\\\"] == \\\"report.pdf\\\"\\n        assert data.data[\\\"document_id\\\"] == \\\"abc123hash\\\"\\n        assert data.data[\\\"mimetype\\\"] == \\\"application/pdf\\\"\\n\\n    def test_metadata_preserved_without_origin(self, monkeypatch):\\n        \\\"\\\"\\\"When origin is None, metadata should still include export_format and name.\\\"\\\"\\\"\\n        fake_doc = _FakeDoclingDocument(name=\\\"notes.md\\\", origin=None, markdown_text=\\\"hello\\\")\\n\\n        results = self._run_export(monkeypatch, fake_doc)\\n\\n        assert len(results) == 1\\n        data = results[0]\\n        assert data.data[\\\"export_format\\\"] == \\\"Markdown\\\"\\n        assert data.data[\\\"name\\\"] == \\\"notes.md\\\"\\n        assert \\\"filename\\\" not in data.data\\n        assert \\\"document_id\\\" not in data.data\\n\\n    def test_metadata_preserved_with_partial_origin(self, monkeypatch):\\n        \\\"\\\"\\\"When origin has only some fields, only those should appear.\\\"\\\"\\\"\\n        fake_doc = _FakeDoclingDocument(\\n            name=\\\"scan.png\\\",\\n            origin=_FakeOrigin(filename=\\\"scan.png\\\", binary_hash=None, mimetype=None),\\n            markdown_text=\\\"image text\\\",\\n        )\\n\\n        results = self._run_export(monkeypatch, fake_doc)\\n\\n        assert len(results) == 1\\n        data = results[0]\\n        assert data.data[\\\"filename\\\"] == \\\"scan.png\\\"\\n        assert \\\"document_id\\\" not in data.data\\n        assert \\\"mimetype\\\" not in data.data\\n\\n    def test_metadata_preserved_for_plaintext_export(self, monkeypatch):\\n        fake_doc = _FakeDoclingDocument(\\n            name=\\\"doc.pdf\\\",\\n            origin=_FakeOrigin(filename=\\\"doc.pdf\\\", binary_hash=\\\"xyz\\\", mimetype=\\\"application/pdf\\\"),\\n            markdown_text=\\\"plain content\\\",\\n        )\\n\\n        results = self._run_export(monkeypatch, fake_doc, export_format=\\\"Plaintext\\\")\\n\\n        assert len(results) == 1\\n        data = results[0]\\n        assert data.data[\\\"export_format\\\"] == \\\"Plaintext\\\"\\n        assert data.data[\\\"document_id\\\"] == \\\"xyz\\\"\\n\\n    def test_no_metadata_when_doc_has_no_name_or_origin(self, monkeypatch):\\n        \\\"\\\"\\\"Minimal doc with no name or origin should still export with export_format.\\\"\\\"\\\"\\n        fake_doc = _FakeDoclingDocument(name=None, origin=None, markdown_text=\\\"bare\\\")\\n\\n        results = self._run_export(monkeypatch, fake_doc)\\n\\n        assert len(results) == 1\\n        data = results[0]\\n        assert data.data[\\\"export_format\\\"] == \\\"Markdown\\\"\\n        assert \\\"name\\\" not in data.data\\n        assert \\\"filename\\\" not in data.data\\n        assert \\\"document_id\\\" not in data.data\\n        assert \\\"mimetype\\\" not in data.data\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/duckduckgo/M1_DOGFOOD_CHECKLIST.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"eeec7eb02ea94a1878c9e0cc6286721a10068cb12d5ceb52d3c2bf47819066e7\",\"content\":\"# M1 dogfood checklist \u2014 `lfx-duckduckgo` pilot bundle\\n\\n> **Status:** :hourglass: **OPEN** \u2014 the runtime half of the DuckDuckGo\\n> pilot has not been signed off. A non-Extension-team engineer must\\n> complete the steps below and paste the filled-in checklist into the\\n> PR before merge. Until that happens, the M1 proof-of-delivery gate is\\n> incomplete even if every automated check is green.\\n\\nPer the Bundle Separation Developer Guide, the M1 proof-of-delivery\\ngate has two halves:\\n\\n1. **Deserialize + build pipeline (automated)** \u2014 lives in\\n   [`src/lfx/tests/integration/extension/test_pilot_duckduckgo_upgrade.py`](../../lfx/tests/integration/extension/test_pilot_duckduckgo_upgrade.py)\\n   and covers:\\n   - Every legacy reference form (bare class name, full import path,\\n     package-level import path, pre-Phase-A slot ID) rewrites to\\n     `ext:duckduckgo:DuckDuckGoSearchComponent@official`.\\n   - The `lfx-duckduckgo` distribution is importable and ships its\\n     manifest where `importlib.metadata.files()` can discover it.\\n   - The loader resolves the migration target to a\\n     `DuckDuckGoSearchComponent` class built from the same source file as\\n     the bundle export \u2014 with the canonical `input_value` input and\\n     `dataframe` output preserved so existing flows' wiring stays valid.\\n   - **The loaded class's build pipeline runs end-to-end against a\\n     stubbed network wrapper** to the canonical output schema:\\n     `content` / `snippet` columns are present, `max_results` slicing\\n     and `max_snippet_length` truncation behave correctly, and the\\n     wrapper is called with the canonical `\\\"<query> (site:*)\\\"` template.\\n\\n2. **Real cross-version swap (manual)** \u2014 the pre-merge dogfood gate.\\n   This file is the checklist for that half.\\n\\nThe remaining question for the dogfood is therefore narrow: with the\\nload-and-run pipeline now locked in by automated tests against a stub,\\nthe human gate only needs to answer \\\"do real DuckDuckGo search results\\nlook materially the same between the pre- and post-migration releases?\\\"\\nA unit-style integration test cannot answer that because it would have\\nto span a Python environment swap and touch the live DuckDuckGo\\nbackend.  A real dogfood run by an engineer who is *not* on the\\nExtension team is what actually closes the DuckDuckGo pilot.\\n\\nThe checklist below is intentionally a template \u2014 fill it in, do not edit it\\nin advance. A pre-checked checklist is not evidence.\\n\\n---\\n\\n## Dogfood run\\n\\n| Field | Value |\\n| --- | --- |\\n| Run by | _engineer name + handle_ |\\n| Date | _YYYY-MM-DD_ |\\n| Pre-migration Langflow version | `1.9.x` (last release before the pilot landed) |\\n| Post-migration Langflow version | this branch / `1.10.x` |\\n| Result | _pass / fail_ |\\n| Notes | _free text_ |\\n\\n### Steps\\n\\n1. **Pre-migration save.**\\n   - [ ] `pip install langflow==<pre-migration version>` in a clean venv\\n   - [ ] `langflow run` and open the UI\\n   - [ ] Drag a **DuckDuckGo Search** component onto the canvas, set\\n         `query` to a string that produces deterministic-enough output\\n         (e.g. `\\\"site:wikipedia.org claude shannon\\\"`)\\n   - [ ] Wire it into a minimal flow that prints the result list\\n   - [ ] **Save the flow** \u2014 record the resulting JSON to disk\\n         (download from the UI or read out of the SQLite store)\\n\\n2. **Pre-migration run.**\\n   - [ ] Run the flow once and **record the output** (titles + URLs) to\\n         a file alongside the saved flow JSON\\n\\n3. **Upgrade.**\\n   - [ ] In a separate clean venv: `pip install langflow==<this branch>`\\n         (which transitively pulls in `lfx-duckduckgo`)\\n   - [ ] Confirm `lfx extension list --format=json` shows\\n         `lfx-duckduckgo` at slot `@official`\\n\\n4. **Post-migration load.**\\n   - [ ] `langflow run`, open the saved flow JSON from step 1\\n   - [ ] Confirm the canvas renders the DuckDuckGo node intact\\n         (no red placeholder; no \\\"component not found\\\" toast)\\n   - [ ] Inspect the loaded node's `data.type` field \u2014 it should be\\n         `ext:duckduckgo:DuckDuckGoSearchComponent@official`\\n         (rewritten by the migration table on load)\\n\\n5. **Post-migration run.**\\n   - [ ] Execute the flow with the same `query` value from step 1\\n   - [ ] Compare the output to the recording from step 2\\n   - [ ] **Pass criterion:** the result set is materially equivalent.\\n         DuckDuckGo's ranking can drift between calls, so an exact\\n         byte-for-byte match is not the bar; \\\"the top results overlap\\n         and the schema is identical\\\" is enough.  The point of this\\n         check is \\\"the component still works against a real network\\\",\\n         not \\\"search results are deterministic.\\\"\\n\\n6. **Sign-off.**\\n   - [ ] Cross-link the completed checklist in the PR description\\n         under \\\"M1 dogfood evidence\\\"\\n\\n---\\n\\n## What \\\"fail\\\" looks like\\n\\nAny of:\\n\\n- The pre-migration flow JSON does not load (red placeholder, \\\"component\\n  not found\\\", typed `component-not-found-with-hint` toast).\\n- The migration table rewrites the node to a non-canonical or wrong\\n  target.\\n- Post-migration execution raises an exception that did not exist\\n  pre-migration.\\n- The result schema differs (different fields, different shape) \u2014 note\\n  that this is different from \\\"different ranking\\\", which is fine.\\n\\nIf any of these fail, **do not merge**.  File a follow-up that captures\\nthe failure mode in\\n[`test_pilot_duckduckgo_upgrade.py`](../../lfx/tests/integration/extension/test_pilot_duckduckgo_upgrade.py)\\nso the regression is locked in.\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/duckduckgo/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"59430c26fdab37e9e4ae7e0b080f70b3e56d1b6e262c341175fa47c631ec4129\",\"content\":\"# lfx-duckduckgo\\n\\nDuckDuckGo Search component as a standalone Langflow Extension Bundle.\\n\\nThis is the first provider extracted from `lfx.components.<provider>`\\ninto a separate distribution.  The bundle ships a single component,\\n`DuckDuckGoSearchComponent`, which performs DuckDuckGo web searches\\nvia `langchain-community`.\\n\\n## Install\\n\\n```bash\\npip install lfx-duckduckgo\\n```\\n\\nThe bundle is registered automatically via the `langflow.extensions`\\nentry-point.  After install, restart your Langflow server; the\\n`DuckDuckGoSearchComponent` will appear in the palette under the\\n`duckduckgo` bundle group.\\n\\n## Develop\\n\\n```bash\\ncd src/bundles/duckduckgo\\npip install -e .\\nlfx extension validate .\\n```\\n\\n## Manifest\\n\\nThe extension manifest is shipped at\\n`src/lfx_duckduckgo/extension.json` and points at the bundle at\\n`components/duckduckgo`.  Components register under the canonical\\nnamespaced ID `ext:duckduckgo:DuckDuckGoSearchComponent@official`.\\n\\n## Migration\\n\\nSaved flows referencing the legacy class name `DuckDuckGoSearchComponent`\\nor the old import path\\n`lfx.components.duckduckgo.duck_duck_go_search_run.DuckDuckGoSearchComponent`\\nare rewritten to the new namespaced ID by the migration table in\\n`src/lfx/src/lfx/extension/migration/migration_table.json`.\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/duckduckgo/pyproject.toml\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"eceb64f1092390cf68c206e84456ef94b640841573a02df64f4ab630b565e1d3\",\"content\":\"[project]\\nname = \\\"lfx-duckduckgo\\\"\\nversion = \\\"0.1.5\\\"\\ndescription = \\\"DuckDuckGo Search component as a standalone Langflow Extension Bundle.\\\"\\nreadme = \\\"README.md\\\"\\nrequires-python = \\\">=3.10,<3.15\\\"\\nlicense = { text = \\\"MIT\\\" }\\nauthors = [\\n    { name = \\\"Langflow\\\", email = \\\"contact@langflow.org\\\" },\\n]\\nkeywords = [\\\"langflow\\\", \\\"lfx\\\", \\\"extension\\\", \\\"bundle\\\", \\\"duckduckgo\\\", \\\"search\\\"]\\n\\n# Runtime deps: lfx (the BUNDLE_API surface) and the langchain-community\\n# binding that wraps the duckduckgo-search Python client.  lfx is floored at\\n# the current major.minor line (>=1.10.0) and capped below the next lfx major\\n# (<2.0.0) so the bundle resolves a compatible lfx; fine-grained BUNDLE_API\\n# compatibility is enforced separately via extension.json's\\n# \\\"lfx\\\": {\\\"compat\\\": [...]} contract.  langchain-community uses the same\\n# range the lfx tree does to keep co-installation lockstep.\\ndependencies = [\\n    \\\"lfx>=1.12.0.dev0,<2.0.0\\\",\\n    \\\"langchain-community>=0.4.1,<1.0.0\\\",\\n    \\\"ddgs>=9.0.0\\\",\\n]\\n\\n[project.urls]\\nHomepage = \\\"https://github.com/langflow-ai/langflow\\\"\\nDocumentation = \\\"https://docs.langflow.org/extensions\\\"\\nRepository = \\\"https://github.com/langflow-ai/langflow\\\"\\n\\n# Manifest-shipping distributions are discovered via the\\n# ``langflow.extensions`` entry-point.  The value is the dotted path\\n# to the package containing ``extension.json`` -- the loader walks\\n# ``importlib.metadata.files()`` from there to find the manifest, and\\n# falls back to this entry-point for editable installs whose dist.files\\n# only surfaces dist-info entries.\\n[project.entry-points.\\\"langflow.extensions\\\"]\\nlfx-duckduckgo = \\\"lfx_duckduckgo\\\"\\n\\n[build-system]\\nrequires = [\\\"hatchling==1.31.0\\\"]\\nbuild-backend = \\\"hatchling.build\\\"\\n\\n[tool.hatch.build.targets.wheel]\\n# extension.json + components live inside the lfx_duckduckgo package so\\n# ``importlib.metadata.files(dist)`` finds them and the loader resolves\\n# bundles[].path relative to the manifest's directory.\\npackages = [\\\"src/lfx_duckduckgo\\\"]\\ninclude = [\\\"src/lfx_duckduckgo/extension.json\\\", \\\"src/lfx_duckduckgo/components/**/*.py\\\"]\\n\\n[tool.hatch.build.targets.sdist]\\ninclude = [\\n    \\\"src/lfx_duckduckgo\\\",\\n    \\\"extension.json\\\",\\n    \\\"README.md\\\",\\n    \\\"pyproject.toml\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/duckduckgo/src/lfx_duckduckgo/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1b6a971fd48b0270148aa9ca60485f9529aef9d07c5d3eb468460bc8e3e41e98\",\"content\":\"\\\"\\\"\\\"lfx-duckduckgo: DuckDuckGo Search bundle.\\n\\nThis package is the distribution unit ``lfx-duckduckgo``.  At runtime\\nLangflow's loader discovers ``extension.json`` shipped alongside this\\n``__init__.py`` and registers ``DuckDuckGoSearchComponent`` under the\\nnamespaced ID ``ext:duckduckgo:DuckDuckGoSearchComponent@official``.\\n\\nThe first provider extracted from ``lfx.components.<provider>`` into\\na standalone Bundle.\\n\\\"\\\"\\\"\\n\\nfrom lfx_duckduckgo.components.duckduckgo.duck_duck_go_search_run import (\\n    DuckDuckGoSearchComponent,\\n)\\n\\n__all__ = [\\\"DuckDuckGoSearchComponent\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/duckduckgo/src/lfx_duckduckgo/components/duckduckgo/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"638cda38b54e2ac0ffab017b2912de935a5c68a2876ba94650739bb904d1f626\",\"content\":\"from .duck_duck_go_search_run import DuckDuckGoSearchComponent\\n\\n__all__ = [\\\"DuckDuckGoSearchComponent\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/duckduckgo/src/lfx_duckduckgo/components/duckduckgo/duck_duck_go_search_run.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"eccbd392095dbec8fad6ac022e8bad9594b315557b4f1afa36486e55e776a966\",\"content\":\"from langchain_community.tools import DuckDuckGoSearchRun\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.inputs.inputs import IntInput, MessageTextInput\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dataframe import DataFrame\\nfrom lfx.template.field.base import Output\\n\\n\\nclass DuckDuckGoSearchComponent(Component):\\n    \\\"\\\"\\\"Component for performing web searches using DuckDuckGo.\\\"\\\"\\\"\\n\\n    display_name = \\\"DuckDuckGo Search\\\"\\n    description = \\\"Search the web using DuckDuckGo with customizable result limits\\\"\\n    documentation = \\\"https://python.langchain.com/docs/integrations/tools/ddg\\\"\\n    icon = \\\"DuckDuckGo\\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\\"input_value\\\",\\n            display_name=\\\"Search Query\\\",\\n            required=True,\\n            info=\\\"The search query to execute with DuckDuckGo\\\",\\n            tool_mode=True,\\n        ),\\n        IntInput(\\n            name=\\\"max_results\\\",\\n            display_name=\\\"Max Results\\\",\\n            value=5,\\n            required=False,\\n            advanced=True,\\n            info=\\\"Maximum number of search results to return\\\",\\n        ),\\n        IntInput(\\n            name=\\\"max_snippet_length\\\",\\n            display_name=\\\"Max Snippet Length\\\",\\n            value=100,\\n            required=False,\\n            advanced=True,\\n            info=\\\"Maximum length of each result snippet\\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Table\\\", name=\\\"dataframe\\\", method=\\\"fetch_content_dataframe\\\"),\\n    ]\\n\\n    def _build_wrapper(self) -> DuckDuckGoSearchRun:\\n        \\\"\\\"\\\"Build the DuckDuckGo search wrapper.\\\"\\\"\\\"\\n        return DuckDuckGoSearchRun()\\n\\n    def run_model(self) -> DataFrame:\\n        return self.fetch_content_dataframe()\\n\\n    def fetch_content(self) -> list[Data]:\\n        \\\"\\\"\\\"Execute the search and return results as Data objects.\\\"\\\"\\\"\\n        try:\\n            wrapper = self._build_wrapper()\\n\\n            full_results = wrapper.run(f\\\"{self.input_value} (site:*)\\\")\\n\\n            result_list = full_results.split(\\\"\\\\n\\\")[: self.max_results]\\n\\n            data_results = []\\n            for result in result_list:\\n                if result.strip():\\n                    snippet = result[: self.max_snippet_length]\\n                    data_results.append(\\n                        Data(\\n                            text=snippet,\\n                            data={\\n                                \\\"content\\\": result,\\n                                \\\"snippet\\\": snippet,\\n                            },\\n                        )\\n                    )\\n        except (ValueError, AttributeError) as e:\\n            error_data = [Data(text=str(e), data={\\\"error\\\": str(e)})]\\n            self.status = error_data\\n            return error_data\\n        else:\\n            self.status = data_results\\n            return data_results\\n\\n    def fetch_content_dataframe(self) -> DataFrame:\\n        \\\"\\\"\\\"Convert the search results to a DataFrame.\\n\\n        Returns:\\n            DataFrame: A DataFrame containing the search results.\\n        \\\"\\\"\\\"\\n        data = self.fetch_content()\\n        return DataFrame(data)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/duckduckgo/src/lfx_duckduckgo/extension.json\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bc274166d9487f2f1ab4592155df9fabc0974cedc5b474c3e1de0ded89b85033\",\"content\":\"{\\n  \\\"$schema\\\": \\\"https://schemas.langflow.org/extension/v1.json\\\",\\n  \\\"id\\\": \\\"lfx-duckduckgo\\\",\\n  \\\"version\\\": \\\"0.1.5\\\",\\n  \\\"name\\\": \\\"DuckDuckGo Search\\\",\\n  \\\"description\\\": \\\"DuckDuckGo Search component as a standalone Langflow Extension Bundle.\\\",\\n  \\\"lfx\\\": {\\n    \\\"compat\\\": [\\\"1\\\"]\\n  },\\n  \\\"bundles\\\": [\\n    {\\n      \\\"name\\\": \\\"duckduckgo\\\",\\n      \\\"path\\\": \\\"components/duckduckgo\\\"\\n    }\\n  ]\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/empiriolabs/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c9ee4c4d3fcc071db57a923c924c081c1ae82b305cece766a143d3f421ec5aa7\",\"content\":\"# lfx-empiriolabs\\n\\nEmpirioLabs as a standalone Langflow Extension Bundle.\\n\\nShips two components for [EmpirioLabs](https://empiriolabs.ai):\\n\\n- **EmpirioLabs** \u2014 generates text using EmpirioLabs language models. EmpirioLabs\\n  exposes an OpenAI-compatible API (`https://api.empiriolabs.ai/v1`), so the\\n  component reuses `langchain_openai.ChatOpenAI` and can output either a\\n  **Model Response** (`Message`) or a **Language Model** (`LanguageModel`) for\\n  downstream components such as Agents.\\n- **EmpirioLabs Image Generation** \u2014 generates an image from a text prompt via\\n  the EmpirioLabs OpenAI-compatible Images endpoint\\n  (`POST /v1/images/generations`).\\n\\nBoth components fetch the live model list from the EmpirioLabs `/v1/models`\\nendpoint over `requests`, falling back to a bundled model list. This mirrors the\\nexisting OpenAI-compatible provider bundles (`novita`, `cometapi`).\\n\\n## Install\\n\\n```bash\\npip install lfx-empiriolabs\\n```\\n\\nThe bundle is registered automatically via the `langflow.extensions`\\nentry-point. After install, restart your Langflow server; the components will\\nappear in the palette under the `EmpirioLabs` group.\\n\\nYou will need an EmpirioLabs API key (<https://empiriolabs.ai>) to run the\\ncomponents. By default the components read it from the `EMPIRIOLABS_API_KEY`\\nenvironment variable.\\n\\n## Develop\\n\\n```bash\\ncd src/bundles/empiriolabs\\npip install -e .\\nlfx extension validate src/lfx_empiriolabs\\n```\\n\\n## Migration\\n\\nSaved flows referencing the legacy class names or the old import paths under\\n`lfx.components.empiriolabs.*` are rewritten to the new namespaced IDs\\n`ext:empiriolabs:EmpirioLabsModelComponent@official` and\\n`ext:empiriolabs:EmpirioLabsImageGenerationComponent@official` by the migration\\ntable in `src/lfx/src/lfx/extension/migration/migration_table.json`.\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/empiriolabs/pyproject.toml\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0c24b49104c995fe028a2478ec5d113d98238ac7a7d6608113efeae7d5a63232\",\"content\":\"[project]\\nname = \\\"lfx-empiriolabs\\\"\\nversion = \\\"0.1.3\\\"\\ndescription = \\\"EmpirioLabs components (OpenAI-compatible chat models and image generation) as a standalone Langflow Extension Bundle.\\\"\\nreadme = \\\"README.md\\\"\\nrequires-python = \\\">=3.10,<3.15\\\"\\nlicense = { text = \\\"MIT\\\" }\\nauthors = [\\n    { name = \\\"Langflow\\\", email = \\\"contact@langflow.org\\\" },\\n]\\nkeywords = [\\\"langflow\\\", \\\"lfx\\\", \\\"extension\\\", \\\"bundle\\\", \\\"empiriolabs\\\", \\\"openai\\\", \\\"llm\\\"]\\n\\n# Runtime deps: lfx (the BUNDLE_API surface) plus the third-party imports the\\n# bundle's components rely on. EmpirioLabs exposes an OpenAI-compatible API, so\\n# the chat-model component reuses ``langchain_openai.ChatOpenAI``; both\\n# components fetch the live model list (and the image component POSTs the\\n# generation request) over the EmpirioLabs HTTP API via ``requests``. This\\n# mirrors the existing OpenAI-compatible provider bundles (novita, cometapi),\\n# which declare the same two runtime deps.\\n# lfx is floored at the current major.minor line and capped below the next lfx\\n# major; the floor is read from src/lfx/pyproject.toml at port time and\\n# re-synced on ``make patch`` via scripts/ci/sync_bundle_lfx_pin.py.\\n# Fine-grained BUNDLE_API compatibility is enforced via extension.json's\\n# lfx.compat list against BUNDLE_API_VERSION.\\ndependencies = [\\n    \\\"lfx>=1.12.0.dev0,<2.0.0\\\",\\n    \\\"langchain-openai>=1.1.6\\\",\\n    \\\"requests>=2.32.0\\\",\\n]\\n\\n[project.urls]\\nHomepage = \\\"https://github.com/langflow-ai/langflow\\\"\\nDocumentation = \\\"https://docs.langflow.org/extensions\\\"\\nRepository = \\\"https://github.com/langflow-ai/langflow\\\"\\n\\n# Manifest-shipping distributions are discovered via the\\n# ``langflow.extensions`` entry-point.  Editable installs whose\\n# ``dist.files`` only surfaces dist-info entries fall back to this\\n# entry-point to find the manifest.\\n[project.entry-points.\\\"langflow.extensions\\\"]\\nlfx-empiriolabs = \\\"lfx_empiriolabs\\\"\\n\\n[build-system]\\nrequires = [\\\"hatchling==1.31.0\\\"]\\nbuild-backend = \\\"hatchling.build\\\"\\n\\n[tool.hatch.build.targets.wheel]\\n# extension.json + components live inside the lfx_empiriolabs package so\\n# ``importlib.metadata.files(dist)`` finds them and the loader resolves\\n# bundles[].path relative to the manifest's directory.\\npackages = [\\\"src/lfx_empiriolabs\\\"]\\ninclude = [\\\"src/lfx_empiriolabs/extension.json\\\", \\\"src/lfx_empiriolabs/components/**/*.py\\\"]\\n\\n[tool.hatch.build.targets.sdist]\\ninclude = [\\n    \\\"src/lfx_empiriolabs\\\",\\n    \\\"extension.json\\\",\\n    \\\"README.md\\\",\\n    \\\"pyproject.toml\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/empiriolabs/src/lfx_empiriolabs/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8e1bf75ceab8713fa72ef0746a8fe77ddd7c45f88df056378480da2b617a6a5d\",\"content\":\"\\\"\\\"\\\"lfx-empiriolabs: EmpirioLabs bundle.\\n\\nDistribution unit ``lfx-empiriolabs``.  At runtime Langflow's loader discovers\\n``extension.json`` shipped alongside this ``__init__.py`` and registers the\\nbundle's components under the namespaced IDs\\n``ext:empiriolabs:EmpirioLabsModelComponent@official`` and\\n``ext:empiriolabs:EmpirioLabsImageGenerationComponent@official``.\\n\\\"\\\"\\\"\\n\\nfrom lfx_empiriolabs.components.empiriolabs.empiriolabs import EmpirioLabsModelComponent\\nfrom lfx_empiriolabs.components.empiriolabs.empiriolabs_image_generation import EmpirioLabsImageGenerationComponent\\n\\n__all__ = [\\\"EmpirioLabsImageGenerationComponent\\\", \\\"EmpirioLabsModelComponent\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/empiriolabs/src/lfx_empiriolabs/components/empiriolabs/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b8a2fe99d587db2081db70b4352d92a5adfae397a777c5f27fff55248dd045cb\",\"content\":\"\\\"\\\"\\\"Component re-exports for the ``empiriolabs`` bundle.\\n\\nSaved-flow migration entries that target ``lfx.components.empiriolabs.<Class>``\\nresolve through this package, so the moved Component classes must be importable\\nfrom here by name.\\n\\\"\\\"\\\"\\n\\nfrom .empiriolabs import EmpirioLabsModelComponent\\nfrom .empiriolabs_image_generation import EmpirioLabsImageGenerationComponent\\n\\n__all__ = [\\\"EmpirioLabsImageGenerationComponent\\\", \\\"EmpirioLabsModelComponent\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/empiriolabs/src/lfx_empiriolabs/components/empiriolabs/empiriolabs.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"10b552e66790fb36978cfbb10dcd88624cb48fb527eb34aa8d95336e78427437\",\"content\":\"import requests\\nfrom langchain_openai import ChatOpenAI\\nfrom lfx.base.models.model import LCModelComponent\\nfrom lfx.field_typing import LanguageModel\\nfrom lfx.field_typing.range_spec import RangeSpec\\nfrom lfx.inputs.inputs import (\\n    BoolInput,\\n    DictInput,\\n    DropdownInput,\\n    HandleInput,\\n    IntInput,\\n    SecretStrInput,\\n    SliderInput,\\n)\\nfrom pydantic.v1 import SecretStr\\nfrom typing_extensions import override\\n\\nEMPIRIOLABS_BASE_URL = \\\"https://api.empiriolabs.ai/v1\\\"\\n\\nEMPIRIOLABS_MODELS = [\\n    \\\"qwen3-7-plus\\\",\\n    \\\"qwen3-7-max\\\",\\n    \\\"deepseek-v4-pro\\\",\\n    \\\"deepseek-v4-flash\\\",\\n    \\\"glm-5-1\\\",\\n    \\\"kimi-k2-7-code\\\",\\n    \\\"minimax-m3\\\",\\n]\\nMODEL_NAMES = EMPIRIOLABS_MODELS  # reverse compatibility\\n\\n\\nclass EmpirioLabsModelComponent(LCModelComponent):\\n    display_name = \\\"EmpirioLabs AI\\\"\\n    description = \\\"Generates text using EmpirioLabs AI LLMs (OpenAI compatible).\\\"\\n    icon = \\\"EmpirioLabs\\\"\\n    name = \\\"EmpirioLabsModel\\\"\\n\\n    inputs = [\\n        *LCModelComponent.get_base_inputs(),\\n        IntInput(\\n            name=\\\"max_tokens\\\",\\n            display_name=\\\"Max Tokens\\\",\\n            advanced=True,\\n            info=\\\"The maximum number of tokens to generate. Set to 0 for unlimited tokens.\\\",\\n            range_spec=RangeSpec(min=0, max=128000),\\n        ),\\n        DictInput(\\n            name=\\\"model_kwargs\\\",\\n            display_name=\\\"Model Kwargs\\\",\\n            advanced=True,\\n            info=\\\"Additional keyword arguments to pass to the model.\\\",\\n        ),\\n        BoolInput(\\n            name=\\\"json_mode\\\",\\n            display_name=\\\"JSON Mode\\\",\\n            advanced=True,\\n            info=\\\"If True, it will output JSON regardless of passing a schema.\\\",\\n        ),\\n        DropdownInput(\\n            name=\\\"model_name\\\",\\n            display_name=\\\"Model Name\\\",\\n            advanced=False,\\n            options=MODEL_NAMES,\\n            value=MODEL_NAMES[0],\\n            refresh_button=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"EmpirioLabs API Key\\\",\\n            info=\\\"The EmpirioLabs API Key to use for EmpirioLabs AI models.\\\",\\n            advanced=False,\\n            value=\\\"EMPIRIOLABS_API_KEY\\\",\\n            real_time_refresh=True,\\n        ),\\n        SliderInput(name=\\\"temperature\\\", display_name=\\\"Temperature\\\", value=0.1, range_spec=RangeSpec(min=0, max=1)),\\n        IntInput(\\n            name=\\\"seed\\\",\\n            display_name=\\\"Seed\\\",\\n            info=\\\"The seed controls the reproducibility of the job.\\\",\\n            advanced=True,\\n            value=1,\\n        ),\\n        HandleInput(\\n            name=\\\"output_parser\\\",\\n            display_name=\\\"Output Parser\\\",\\n            info=\\\"The parser to use to parse the output of the model\\\",\\n            advanced=True,\\n            input_types=[\\\"OutputParser\\\"],\\n        ),\\n    ]\\n\\n    def get_models(self) -> list[str]:\\n        url = f\\\"{EMPIRIOLABS_BASE_URL}/models\\\"\\n\\n        headers = {\\\"Content-Type\\\": \\\"application/json\\\"}\\n        api_key = getattr(self, \\\"api_key\\\", None)\\n        if api_key:\\n            token = SecretStr(api_key).get_secret_value() if isinstance(api_key, str) else api_key\\n            headers[\\\"Authorization\\\"] = f\\\"Bearer {token}\\\"\\n\\n        try:\\n            response = requests.get(url, headers=headers, timeout=10)\\n            response.raise_for_status()\\n            model_list = response.json()\\n            return [model[\\\"id\\\"] for model in model_list.get(\\\"data\\\", [])]\\n        except requests.RequestException as e:\\n            self.status = f\\\"Error fetching models: {e}\\\"\\n            return MODEL_NAMES\\n\\n    @override\\n    def update_build_config(self, build_config: dict, field_value: str, field_name: str | None = None):\\n        if field_name in {\\\"api_key\\\", \\\"model_name\\\"}:\\n            models = self.get_models()\\n            build_config[\\\"model_name\\\"][\\\"options\\\"] = models\\n        return build_config\\n\\n    def build_model(self) -> LanguageModel:  # type: ignore[type-var]\\n        api_key = self.api_key\\n        temperature = self.temperature\\n        model_name: str = self.model_name\\n        max_tokens = self.max_tokens\\n        model_kwargs = self.model_kwargs or {}\\n        json_mode = self.json_mode\\n        seed = self.seed\\n\\n        try:\\n            output = ChatOpenAI(\\n                model=model_name,\\n                api_key=(SecretStr(api_key).get_secret_value() if api_key else None),\\n                max_tokens=max_tokens or None,\\n                temperature=temperature,\\n                model_kwargs=model_kwargs,\\n                streaming=self.stream,\\n                seed=seed,\\n                base_url=EMPIRIOLABS_BASE_URL,\\n            )\\n        except Exception as e:\\n            msg = \\\"Could not connect to EmpirioLabs API.\\\"\\n            raise ValueError(msg) from e\\n\\n        if json_mode:\\n            output = output.bind(response_format={\\\"type\\\": \\\"json_object\\\"})\\n\\n        return output\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/empiriolabs/src/lfx_empiriolabs/components/empiriolabs/empiriolabs_image_generation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"266e10fe2c40ed9a1f51c085dcdaa468c40013ea4078e2a397159de51932e6b3\",\"content\":\"import requests\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import DropdownInput, IntInput, MessageTextInput, Output, SecretStrInput\\nfrom lfx.schema.data import Data\\nfrom pydantic.v1 import SecretStr\\n\\nEMPIRIOLABS_BASE_URL = \\\"https://api.empiriolabs.ai/v1\\\"\\n\\n# EmpirioLabs image generation models (category=image). These use the OpenAI\\n# Images request shape at POST /v1/images/generations.\\nEMPIRIOLABS_IMAGE_MODELS = [\\n    \\\"seedream-5-0-lite\\\",\\n    \\\"qwen-image-2-0\\\",\\n    \\\"flux-2-klein-4b\\\",\\n    \\\"amazon-nova-canvas\\\",\\n    \\\"hunyuan-image-3\\\",\\n    \\\"wan2-7-image\\\",\\n    \\\"janus-pro-deepseek\\\",\\n]\\n\\n# Allowed aspect ratios mirror the common set supported across the image models.\\nASPECT_RATIOS = [\\\"1:1\\\", \\\"16:9\\\", \\\"9:16\\\", \\\"4:3\\\", \\\"3:4\\\", \\\"3:2\\\", \\\"2:3\\\", \\\"21:9\\\", \\\"9:21\\\"]\\n\\n\\nclass EmpirioLabsImageGenerationComponent(Component):\\n    display_name = \\\"EmpirioLabs AI Image Generation\\\"\\n    description = \\\"Generate an image from a text prompt using EmpirioLabs AI image models such as Seedream, \\\\\\n        Qwen-Image, FLUX, Nova Canvas, and HunyuanImage.\\\"\\n    documentation = \\\"https://docs.empiriolabs.ai\\\"\\n    icon = \\\"EmpirioLabs\\\"\\n    name = \\\"EmpirioLabsImageGeneration\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"EmpirioLabs API Key\\\",\\n            info=\\\"The EmpirioLabs API Key to use for EmpirioLabs AI image models.\\\",\\n            required=True,\\n            value=\\\"EMPIRIOLABS_API_KEY\\\",\\n            real_time_refresh=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"prompt\\\",\\n            display_name=\\\"Prompt\\\",\\n            info=\\\"The text prompt to generate the image from.\\\",\\n            required=True,\\n            tool_mode=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"model_name\\\",\\n            display_name=\\\"Model\\\",\\n            info=\\\"The EmpirioLabs image model to use for generation.\\\",\\n            options=EMPIRIOLABS_IMAGE_MODELS,\\n            value=EMPIRIOLABS_IMAGE_MODELS[0],\\n            refresh_button=True,\\n            required=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"aspect_ratio\\\",\\n            display_name=\\\"Aspect Ratio\\\",\\n            info=\\\"The aspect ratio of the generated image. Used when the selected model supports it.\\\",\\n            options=ASPECT_RATIOS,\\n            value=\\\"1:1\\\",\\n            required=False,\\n        ),\\n        MessageTextInput(\\n            name=\\\"size\\\",\\n            display_name=\\\"Size\\\",\\n            info=\\\"Optional explicit pixel size such as '1024x1024'. Takes priority over aspect ratio \\\"\\n            \\\"when the selected model supports an explicit size.\\\",\\n            required=False,\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"n\\\",\\n            display_name=\\\"Number of Images\\\",\\n            info=\\\"The number of images to generate.\\\",\\n            value=1,\\n            required=False,\\n        ),\\n        IntInput(\\n            name=\\\"seed\\\",\\n            display_name=\\\"Seed\\\",\\n            info=\\\"Makes generation deterministic. Using the same seed and parameters produces \\\"\\n            \\\"the same image each time. Used when the selected model supports it.\\\",\\n            required=False,\\n            tool_mode=True,\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"negative_prompt\\\",\\n            display_name=\\\"Negative Prompt\\\",\\n            info=\\\"The text prompt describing what to avoid in the generated image. \\\"\\n            \\\"Used when the selected model supports it.\\\",\\n            required=False,\\n            tool_mode=True,\\n            advanced=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Image Generation Results\\\", name=\\\"image_generation_results\\\", method=\\\"generate_image\\\"),\\n    ]\\n\\n    def _get_token(self) -> str:\\n        api_key = getattr(self, \\\"api_key\\\", None)\\n        if not api_key:\\n            return \\\"\\\"\\n        return SecretStr(api_key).get_secret_value() if isinstance(api_key, str) else api_key\\n\\n    def get_models(self) -> list[str]:\\n        \\\"\\\"\\\"Fetch the live list of image models from the EmpirioLabs API, falling back to the static list.\\\"\\\"\\\"\\n        url = f\\\"{EMPIRIOLABS_BASE_URL}/models\\\"\\n        headers = {\\\"Content-Type\\\": \\\"application/json\\\"}\\n        token = self._get_token()\\n        if token:\\n            headers[\\\"Authorization\\\"] = f\\\"Bearer {token}\\\"\\n\\n        try:\\n            response = requests.get(url, headers=headers, timeout=10)\\n            response.raise_for_status()\\n            model_list = response.json()\\n            image_models = [\\n                model[\\\"id\\\"]\\n                for model in model_list.get(\\\"data\\\", [])\\n                if model.get(\\\"category\\\") == \\\"image\\\"\\n                or (isinstance(model.get(\\\"metadata\\\"), dict) and model[\\\"metadata\\\"].get(\\\"category\\\") == \\\"image\\\")\\n            ]\\n        except requests.RequestException as e:\\n            self.status = f\\\"Error fetching models: {e}\\\"\\n            return EMPIRIOLABS_IMAGE_MODELS\\n        return image_models or EMPIRIOLABS_IMAGE_MODELS\\n\\n    def update_build_config(self, build_config: dict, field_value: str, field_name: str | None = None):  # noqa: ARG002\\n        if field_name in {\\\"api_key\\\", \\\"model_name\\\"}:\\n            build_config[\\\"model_name\\\"][\\\"options\\\"] = self.get_models()\\n        return build_config\\n\\n    def generate_image(self) -> Data:\\n        token = self._get_token()\\n        if not token:\\n            missing_key_error = \\\"An EmpirioLabs API key is required to generate images.\\\"\\n            raise ValueError(missing_key_error)\\n\\n        if not self.prompt or not self.prompt.strip():\\n            invalid_prompt_error = \\\"A non-empty prompt is required to generate an image.\\\"\\n            raise ValueError(invalid_prompt_error)\\n\\n        # Build the OpenAI Images request body. sync: true makes the API hold the\\n        # request and return the finished image instead of an async job envelope.\\n        payload: dict = {\\n            \\\"model\\\": self.model_name,\\n            \\\"prompt\\\": self.prompt.strip(),\\n            \\\"sync\\\": True,\\n        }\\n        if self.size and self.size.strip():\\n            payload[\\\"size\\\"] = self.size.strip()\\n        elif self.aspect_ratio:\\n            payload[\\\"aspect_ratio\\\"] = self.aspect_ratio\\n        if self.n:\\n            payload[\\\"n\\\"] = self.n\\n        if self.seed:\\n            payload[\\\"seed\\\"] = self.seed\\n        if self.negative_prompt and self.negative_prompt.strip():\\n            payload[\\\"negative_prompt\\\"] = self.negative_prompt.strip()\\n\\n        headers = {\\n            \\\"Authorization\\\": f\\\"Bearer {token}\\\",\\n            \\\"Content-Type\\\": \\\"application/json\\\",\\n        }\\n\\n        try:\\n            response = requests.post(\\n                f\\\"{EMPIRIOLABS_BASE_URL}/images/generations\\\",\\n                headers=headers,\\n                json=payload,\\n                timeout=300,\\n            )\\n            response.raise_for_status()\\n            result = response.json()\\n        except requests.RequestException as e:\\n            error_data = {\\\"error\\\": str(e), \\\"success\\\": False}\\n            self.status = f\\\"Error: {e!s}\\\"\\n            return Data(data=error_data)\\n\\n        items = result.get(\\\"data\\\") if isinstance(result, dict) else None\\n        if not items:\\n            failed_response_error = \\\"EmpirioLabs API did not return any generated image.\\\"\\n            raise ValueError(failed_response_error)\\n\\n        image_urls = [item.get(\\\"url\\\") for item in items if isinstance(item, dict) and item.get(\\\"url\\\")]\\n        first = items[0] if isinstance(items[0], dict) else {}\\n        image_url = first.get(\\\"url\\\")\\n        image_b64 = first.get(\\\"b64_json\\\")\\n\\n        data_payload: dict = dict(result)\\n        if image_url:\\n            data_payload[\\\"image_url\\\"] = image_url\\n            self.status = image_url\\n        elif image_b64:\\n            data_payload[\\\"b64_json\\\"] = image_b64\\n            self.status = \\\"Generated image returned as base64 content.\\\"\\n        if image_urls:\\n            data_payload[\\\"image_urls\\\"] = image_urls\\n\\n        return Data(data=data_payload)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/empiriolabs/src/lfx_empiriolabs/extension.json\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"32167252e5ad17585d90a7c4d251ec5e3eb0d71866c44f7ee5d926cee0097c27\",\"content\":\"{\\n  \\\"$schema\\\": \\\"https://schemas.langflow.org/extension/v1.json\\\",\\n  \\\"id\\\": \\\"lfx-empiriolabs\\\",\\n  \\\"version\\\": \\\"0.1.3\\\",\\n  \\\"name\\\": \\\"EmpirioLabs\\\",\\n  \\\"description\\\": \\\"EmpirioLabs components (OpenAI-compatible chat models and image generation) as a standalone Langflow Extension Bundle.\\\",\\n  \\\"lfx\\\": {\\n    \\\"compat\\\": [\\\"1\\\"]\\n  },\\n  \\\"bundles\\\": [\\n    {\\n      \\\"name\\\": \\\"empiriolabs\\\",\\n      \\\"path\\\": \\\"components/empiriolabs\\\"\\n    }\\n  ]\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/empiriolabs/tests/test_empiriolabs_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b1fe4e9cc8f8b0057041bdbac77133fefc19195344beffa99d6e602384096a92\",\"content\":\"\\\"\\\"\\\"Unit tests for the EmpirioLabs extension bundle (``lfx-empiriolabs``).\\n\\nThe components previously lived at ``lfx.components.empiriolabs.*`` on the\\ncontributor branch (PR #13645); they now ship as a standalone bundle, so these\\ntests travel with the bundle and import the public bundle entry point. They\\nexercise the server-free surface (component metadata, model building, live\\nmodel fetching with its static fallback, input structure, and image-generation\\nrequest shaping / validation) with ``ChatOpenAI`` and the HTTP calls\\nmonkeypatched -- no network access or EmpirioLabs API key is required.\\n\\nThe in-tree fixture used ``tests.base.ComponentTestBaseWithoutClient``, which is\\nnot importable inside a standalone bundle; these tests reimplement the same\\nassertions as plain pytest functions.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nimport requests\\nfrom lfx_empiriolabs import EmpirioLabsImageGenerationComponent, EmpirioLabsModelComponent\\nfrom lfx_empiriolabs.components.empiriolabs.empiriolabs import EMPIRIOLABS_MODELS, MODEL_NAMES\\n\\nCHATOPENAI_PATH = \\\"lfx_empiriolabs.components.empiriolabs.empiriolabs.ChatOpenAI\\\"\\n\\nDEFAULT_KWARGS = {\\n    \\\"api_key\\\": \\\"test-empiriolabs-key\\\",  # pragma: allowlist secret\\n    \\\"model_name\\\": \\\"qwen3-7-plus\\\",\\n    \\\"temperature\\\": 0.1,\\n    \\\"max_tokens\\\": 1000,\\n    \\\"seed\\\": 1,\\n    \\\"json_mode\\\": False,\\n    \\\"model_kwargs\\\": {},\\n    \\\"stream\\\": False,\\n}\\n\\n\\n# --------------------------------------------------------------------------- #\\n# Bundle entry point\\n# --------------------------------------------------------------------------- #\\ndef test_bundle_entrypoint_exports():\\n    assert EmpirioLabsModelComponent.__name__ == \\\"EmpirioLabsModelComponent\\\"\\n    assert EmpirioLabsModelComponent.name == \\\"EmpirioLabsModel\\\"\\n    assert EmpirioLabsImageGenerationComponent.__name__ == \\\"EmpirioLabsImageGenerationComponent\\\"\\n    assert EmpirioLabsImageGenerationComponent.name == \\\"EmpirioLabsImageGeneration\\\"\\n\\n\\n# --------------------------------------------------------------------------- #\\n# Inlined model constants (previously lfx.base.models.empiriolabs_constants)\\n# --------------------------------------------------------------------------- #\\ndef test_empiriolabs_models_not_empty():\\n    assert isinstance(EMPIRIOLABS_MODELS, list)\\n    assert len(EMPIRIOLABS_MODELS) > 0\\n\\n\\ndef test_model_names_alias():\\n    assert MODEL_NAMES == EMPIRIOLABS_MODELS\\n    assert MODEL_NAMES is EMPIRIOLABS_MODELS\\n\\n\\ndef test_models_are_unique_strings():\\n    for model in EMPIRIOLABS_MODELS:\\n        assert isinstance(model, str)\\n        assert model\\n    assert len(EMPIRIOLABS_MODELS) == len(set(EMPIRIOLABS_MODELS))\\n\\n\\ndef test_specific_models_present():\\n    for expected in [\\\"qwen3-7-plus\\\", \\\"deepseek-v4-pro\\\", \\\"glm-5-1\\\", \\\"minimax-m3\\\"]:\\n        assert expected in EMPIRIOLABS_MODELS\\n\\n\\n# --------------------------------------------------------------------------- #\\n# Chat-model component\\n# --------------------------------------------------------------------------- #\\ndef test_basic_setup():\\n    component = EmpirioLabsModelComponent()\\n    component.set_attributes(dict(DEFAULT_KWARGS))\\n\\n    assert component.display_name == \\\"EmpirioLabs AI\\\"\\n    assert component.description == \\\"Generates text using EmpirioLabs AI LLMs (OpenAI compatible).\\\"\\n    assert component.icon == \\\"EmpirioLabs\\\"\\n    assert component.name == \\\"EmpirioLabsModel\\\"\\n    assert component.api_key == \\\"test-empiriolabs-key\\\"  # pragma: allowlist secret\\n    assert component.model_name == \\\"qwen3-7-plus\\\"\\n    assert component.temperature == 0.1\\n    assert component.max_tokens == 1000\\n    assert component.seed == 1\\n    assert component.json_mode is False\\n\\n\\n@patch(CHATOPENAI_PATH)\\ndef test_build_model_success(mock_chat_openai):\\n    mock_instance = MagicMock()\\n    mock_chat_openai.return_value = mock_instance\\n\\n    component = EmpirioLabsModelComponent()\\n    component.set_attributes(dict(DEFAULT_KWARGS))\\n    model = component.build_model()\\n\\n    mock_chat_openai.assert_called_once_with(\\n        model=\\\"qwen3-7-plus\\\",\\n        api_key=\\\"test-empiriolabs-key\\\",  # pragma: allowlist secret\\n        max_tokens=1000,\\n        temperature=0.1,\\n        model_kwargs={},\\n        streaming=False,\\n        seed=1,\\n        base_url=\\\"https://api.empiriolabs.ai/v1\\\",\\n    )\\n    assert model == mock_instance\\n\\n\\n@patch(CHATOPENAI_PATH)\\ndef test_build_model_with_json_mode(mock_chat_openai):\\n    mock_instance = MagicMock()\\n    mock_bound_instance = MagicMock()\\n    mock_instance.bind.return_value = mock_bound_instance\\n    mock_chat_openai.return_value = mock_instance\\n\\n    kwargs = dict(DEFAULT_KWARGS)\\n    kwargs[\\\"json_mode\\\"] = True\\n    component = EmpirioLabsModelComponent()\\n    component.set_attributes(kwargs)\\n    model = component.build_model()\\n\\n    mock_instance.bind.assert_called_once_with(response_format={\\\"type\\\": \\\"json_object\\\"})\\n    assert model == mock_bound_instance\\n\\n\\n@patch(CHATOPENAI_PATH)\\ndef test_build_model_with_streaming(mock_chat_openai):\\n    mock_chat_openai.return_value = MagicMock()\\n\\n    component = EmpirioLabsModelComponent()\\n    component.set_attributes(dict(DEFAULT_KWARGS))\\n    component.stream = True\\n    component.build_model()\\n\\n    _args, kwargs = mock_chat_openai.call_args\\n    assert kwargs[\\\"streaming\\\"] is True\\n\\n\\n@patch(CHATOPENAI_PATH)\\ndef test_build_model_exception_handling(mock_chat_openai):\\n    mock_chat_openai.side_effect = ValueError(\\\"Invalid API key\\\")\\n\\n    component = EmpirioLabsModelComponent()\\n    component.set_attributes(dict(DEFAULT_KWARGS))\\n\\n    with pytest.raises(ValueError, match=\\\"Could not connect to EmpirioLabs API\\\"):\\n        component.build_model()\\n\\n\\n@patch(\\\"requests.get\\\")\\ndef test_get_models_success(mock_get):\\n    mock_response = MagicMock()\\n    mock_response.json.return_value = {\\\"data\\\": [{\\\"id\\\": \\\"qwen3-7-plus\\\"}, {\\\"id\\\": \\\"deepseek-v4-pro\\\"}, {\\\"id\\\": \\\"glm-5-1\\\"}]}\\n    mock_response.raise_for_status.return_value = None\\n    mock_get.return_value = mock_response\\n\\n    component = EmpirioLabsModelComponent()\\n    component.set_attributes(dict(DEFAULT_KWARGS))\\n    models = component.get_models()\\n\\n    assert models == [\\\"qwen3-7-plus\\\", \\\"deepseek-v4-pro\\\", \\\"glm-5-1\\\"]\\n    mock_get.assert_called_once()\\n\\n\\n@patch(\\\"requests.get\\\")\\ndef test_get_models_fallback(mock_get):\\n    mock_get.side_effect = requests.RequestException(\\\"Network error\\\")\\n\\n    component = EmpirioLabsModelComponent()\\n    component.set_attributes(dict(DEFAULT_KWARGS))\\n    models = component.get_models()\\n\\n    assert models == MODEL_NAMES\\n    assert \\\"Error fetching models\\\" in component.status\\n\\n\\ndef test_component_inputs_structure():\\n    component = EmpirioLabsModelComponent()\\n    input_names = [input_.name for input_ in component.inputs]\\n    for expected in [\\\"api_key\\\", \\\"model_name\\\", \\\"model_kwargs\\\", \\\"temperature\\\", \\\"max_tokens\\\", \\\"seed\\\", \\\"json_mode\\\"]:\\n        assert expected in input_names\\n\\n\\ndef test_component_input_types():\\n    component = EmpirioLabsModelComponent()\\n    api_key_input = next(i for i in component.inputs if i.name == \\\"api_key\\\")\\n    model_name_input = next(i for i in component.inputs if i.name == \\\"model_name\\\")\\n    temperature_input = next(i for i in component.inputs if i.name == \\\"temperature\\\")\\n\\n    assert api_key_input.field_type.value == \\\"str\\\"  # SecretStrInput\\n    assert model_name_input.field_type.value == \\\"str\\\"  # DropdownInput\\n    assert temperature_input.field_type.value == \\\"slider\\\"  # SliderInput\\n\\n\\n# --------------------------------------------------------------------------- #\\n# Image-generation component\\n# --------------------------------------------------------------------------- #\\nIMAGE_KWARGS = {\\n    \\\"api_key\\\": \\\"test-empiriolabs-key\\\",  # pragma: allowlist secret\\n    \\\"prompt\\\": \\\"a serene mountain lake at sunset\\\",\\n    \\\"model_name\\\": \\\"seedream-5-0-lite\\\",\\n    \\\"aspect_ratio\\\": \\\"1:1\\\",\\n    \\\"size\\\": \\\"\\\",\\n    \\\"n\\\": 1,\\n    \\\"seed\\\": 0,\\n    \\\"negative_prompt\\\": \\\"\\\",\\n}\\n\\n\\ndef test_image_generation_requires_api_key():\\n    component = EmpirioLabsImageGenerationComponent()\\n    kwargs = dict(IMAGE_KWARGS)\\n    kwargs[\\\"api_key\\\"] = \\\"\\\"\\n    component.set_attributes(kwargs)\\n    with pytest.raises(ValueError, match=\\\"EmpirioLabs API key is required\\\"):\\n        component.generate_image()\\n\\n\\ndef test_image_generation_requires_prompt():\\n    component = EmpirioLabsImageGenerationComponent()\\n    kwargs = dict(IMAGE_KWARGS)\\n    kwargs[\\\"prompt\\\"] = \\\"   \\\"\\n    component.set_attributes(kwargs)\\n    with pytest.raises(ValueError, match=\\\"non-empty prompt is required\\\"):\\n        component.generate_image()\\n\\n\\n@patch(\\\"requests.post\\\")\\ndef test_image_generation_success(mock_post):\\n    mock_response = MagicMock()\\n    mock_response.json.return_value = {\\\"data\\\": [{\\\"url\\\": \\\"https://cdn.empiriolabs.ai/generated/abc.png\\\"}]}\\n    mock_response.raise_for_status.return_value = None\\n    mock_post.return_value = mock_response\\n\\n    component = EmpirioLabsImageGenerationComponent()\\n    component.set_attributes(dict(IMAGE_KWARGS))\\n    result = component.generate_image()\\n\\n    assert result.data[\\\"image_url\\\"] == \\\"https://cdn.empiriolabs.ai/generated/abc.png\\\"\\n    assert result.data[\\\"image_urls\\\"] == [\\\"https://cdn.empiriolabs.ai/generated/abc.png\\\"]\\n\\n    _args, kwargs = mock_post.call_args\\n    payload = kwargs[\\\"json\\\"]\\n    assert payload[\\\"model\\\"] == \\\"seedream-5-0-lite\\\"\\n    assert payload[\\\"prompt\\\"] == \\\"a serene mountain lake at sunset\\\"\\n    assert payload[\\\"sync\\\"] is True\\n    # No explicit size -> aspect_ratio is used.\\n    assert payload[\\\"aspect_ratio\\\"] == \\\"1:1\\\"\\n    assert \\\"size\\\" not in payload\\n\\n\\n@patch(\\\"requests.post\\\")\\ndef test_image_generation_request_error_returns_data(mock_post):\\n    mock_post.side_effect = requests.RequestException(\\\"boom\\\")\\n\\n    component = EmpirioLabsImageGenerationComponent()\\n    component.set_attributes(dict(IMAGE_KWARGS))\\n    result = component.generate_image()\\n\\n    assert result.data[\\\"success\\\"] is False\\n    assert \\\"boom\\\" in result.data[\\\"error\\\"]\\n\\n\\n@patch(\\\"requests.get\\\")\\ndef test_image_generation_get_models_fallback(mock_get):\\n    mock_get.side_effect = requests.RequestException(\\\"Network error\\\")\\n\\n    component = EmpirioLabsImageGenerationComponent()\\n    component.set_attributes(dict(IMAGE_KWARGS))\\n    models = component.get_models()\\n\\n    from lfx_empiriolabs.components.empiriolabs.empiriolabs_image_generation import EMPIRIOLABS_IMAGE_MODELS\\n\\n    assert models == EMPIRIOLABS_IMAGE_MODELS\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/exa/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c86a74b6d417ed895d542c72ff93f8ca0b6f4aa7eabfb9dfd3e5cb1521251d90\",\"content\":\"# lfx-exa\\n\\n[Exa](https://exa.ai/) web-search and contents tools as a standalone\\nLangflow Extension Bundle.\\n\\n## What it ships\\n\\nOne component, registered under the `exa` bundle group:\\n\\n- **Exa Search** (`ExaSearchToolkit`, canonical ID\\n  `ext:exa:ExaSearchToolkit@official`) \u2014 a toolkit exposing two tools for\\n  a Langflow **Agent** component or MCP client:\\n  - `search` \u2014 search the web with Exa (`auto` / `fast` / `instant` /\\n    `deep` search types, category, domain allow/deny lists, published-date\\n    range), returning token-efficient highlights by default.\\n  - `get_contents` \u2014 fetch highlights and/or full text for result IDs\\n    returned by `search`.\\n\\nThe component is built on the [`exa-py`](https://pypi.org/project/exa-py/)\\nSDK. It previously shipped inside the manifest-less `lfx-bundles`\\nmetapackage on the deprecated `metaphor-python` client; the bundle name and\\nclass name are unchanged, so saved flows load without migration changes.\\nThe legacy `metaphor_api_key` field is still honored (hidden) \u2014 new flows\\nshould use `exa_api_key`.\\n\\n## Install\\n\\n```bash\\npip install lfx-exa\\n```\\n\\n`pip install langflow` already includes it.\\n\\n## Develop\\n\\nThe bundle is a uv workspace member of the Langflow monorepo:\\n\\n```bash\\nuv sync\\nuv run pytest src/bundles/exa/tests -q\\nuv run lfx extension validate src/bundles/exa/src/lfx_exa\\n```\\n\\nTo iterate on the component with a live palette:\\n\\n```bash\\nuv run lfx extension dev src/bundles/exa\\n```\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/exa/pyproject.toml\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5a1a61cfe22a10cf10d39c95dafd9522db5a0e252b04270c334a138ffec60e7c\",\"content\":\"[project]\\nname = \\\"lfx-exa\\\"\\nversion = \\\"0.1.3\\\"\\ndescription = \\\"Exa web-search and contents tools (exa-py SDK) as a standalone Langflow Extension Bundle.\\\"\\nreadme = \\\"README.md\\\"\\nrequires-python = \\\">=3.10,<3.15\\\"\\nlicense = { text = \\\"MIT\\\" }\\nauthors = [\\n    { name = \\\"Langflow\\\", email = \\\"contact@langflow.org\\\" },\\n]\\nkeywords = [\\\"langflow\\\", \\\"lfx\\\", \\\"extension\\\", \\\"bundle\\\", \\\"exa\\\", \\\"search\\\"]\\n\\n# Runtime deps: lfx (the BUNDLE_API surface) plus the third-party imports the\\n# component uses directly.  ``exa-py`` replaces the deprecated\\n# ``metaphor-python`` SDK the pre-1.11 component shipped with; the legacy\\n# ``metaphor_api_key`` input is kept (hidden) so old saved flows keep working.\\n# ``langchain-core`` is already an lfx dep but is listed here as a direct\\n# runtime dep (the component imports ``langchain_core.tools.tool``) so the\\n# bundle keeps building even if lfx drops it later.\\n# lfx is floored at the current major.minor line and capped below the next lfx\\n# major; the floor is read from src/lfx/pyproject.toml at port time and\\n# re-synced on ``make patch`` via scripts/ci/sync_bundle_lfx_pin.py.\\n# Fine-grained BUNDLE_API compatibility is enforced via extension.json's\\n# lfx.compat list against BUNDLE_API_VERSION.\\ndependencies = [\\n    \\\"lfx>=1.12.0.dev0,<2.0.0\\\",\\n    \\\"exa-py>=1.14,<3\\\",\\n    \\\"langchain-core>=1.2.28,<2.0.0\\\",\\n]\\n\\n[project.urls]\\nHomepage = \\\"https://github.com/langflow-ai/langflow\\\"\\nDocumentation = \\\"https://docs.langflow.org/extensions\\\"\\nRepository = \\\"https://github.com/langflow-ai/langflow\\\"\\n\\n# Manifest-shipping distributions are discovered via the\\n# ``langflow.extensions`` entry-point.  Editable installs whose\\n# ``dist.files`` only surfaces dist-info entries fall back to this\\n# entry-point to find the manifest.\\n[project.entry-points.\\\"langflow.extensions\\\"]\\nlfx-exa = \\\"lfx_exa\\\"\\n\\n[build-system]\\nrequires = [\\\"hatchling==1.31.0\\\"]\\nbuild-backend = \\\"hatchling.build\\\"\\n\\n[tool.hatch.build.targets.wheel]\\n# extension.json + components live inside the lfx_exa package so\\n# ``importlib.metadata.files(dist)`` finds them and the loader resolves\\n# bundles[].path relative to the manifest's directory.\\npackages = [\\\"src/lfx_exa\\\"]\\ninclude = [\\\"src/lfx_exa/extension.json\\\", \\\"src/lfx_exa/components/**/*.py\\\"]\\n\\n[tool.hatch.build.targets.sdist]\\ninclude = [\\n    \\\"src/lfx_exa\\\",\\n    \\\"extension.json\\\",\\n    \\\"README.md\\\",\\n    \\\"pyproject.toml\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/exa/src/lfx_exa/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7c227b7bcaa37d1fb435a00220adcbce01171a6cbbd5c1f6c2d2fc77952a48ac\",\"content\":\"\\\"\\\"\\\"lfx-exa: Exa Search bundle.\\n\\nThis package is the distribution unit ``lfx-exa``.  At runtime\\nLangflow's loader discovers ``extension.json`` shipped alongside this\\n``__init__.py`` and registers ``ExaSearchToolkit`` under the namespaced\\nID ``ext:exa:ExaSearchToolkit@official``.\\n\\nGraduated out of the manifest-less ``lfx-bundles`` metapackage when the\\ncomponent was modernized onto the ``exa-py`` SDK (the metapackage copy\\nstill used the deprecated ``metaphor-python`` client).  The bundle name\\n(``exa``) and class name are unchanged, so the canonical component ID --\\nand every migration-table entry pointing at it -- is stable across the\\nmove.\\n\\\"\\\"\\\"\\n\\nfrom lfx_exa.components.exa.exa_search import ExaSearchToolkit\\n\\n__all__ = [\\\"ExaSearchToolkit\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/exa/src/lfx_exa/components/exa/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"11262587a980c97ae90c821f81fef1272d3378c99eb08332ef1579311f857496\",\"content\":\"from .exa_search import ExaSearchToolkit\\n\\n__all__ = [\\\"ExaSearchToolkit\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/exa/src/lfx_exa/components/exa/exa_search.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"550c3dad3f1ecd2a5b88425e9d53461896bc3499a5d977e5d67ef42888208493\",\"content\":\"from exa_py import Exa\\nfrom langchain_core.tools import tool\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.field_typing import Tool\\nfrom lfx.io import (\\n    BoolInput,\\n    DropdownInput,\\n    IntInput,\\n    MessageTextInput,\\n    Output,\\n    SecretStrInput,\\n)\\n\\nEXA_INTEGRATION_NAME = \\\"langflow-integration\\\"\\n\\n\\nclass ExaSearchToolkit(Component):\\n    display_name = \\\"Exa Search\\\"\\n    description = \\\"Exa search and contents tools for agents and MCP clients.\\\"\\n    documentation = \\\"https://docs.exa.ai/reference/getting-started\\\"\\n    beta = True\\n    name = \\\"ExaSearch\\\"\\n    icon = \\\"ExaSearch\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"exa_api_key\\\",\\n            display_name=\\\"Exa API Key\\\",\\n            info=\\\"Get one at https://dashboard.exa.ai/api-keys\\\",\\n            password=True,\\n        ),\\n        # Kept for backward compatibility with flows saved before the field\\n        # was renamed. Hidden from the UI; users should fill in `exa_api_key`.\\n        SecretStrInput(\\n            name=\\\"metaphor_api_key\\\",\\n            display_name=\\\"Metaphor API Key (legacy)\\\",\\n            info=\\\"Deprecated. Use Exa API Key instead.\\\",\\n            password=True,\\n            advanced=True,\\n            show=False,\\n        ),\\n        DropdownInput(\\n            name=\\\"search_type\\\",\\n            display_name=\\\"Search type\\\",\\n            options=[\\\"auto\\\", \\\"fast\\\", \\\"instant\\\", \\\"deep\\\"],\\n            value=\\\"auto\\\",\\n            info=\\\"Latency vs. depth tradeoff. `auto` is recommended for most use cases.\\\",\\n        ),\\n        IntInput(\\n            name=\\\"search_num_results\\\",\\n            display_name=\\\"Number of results\\\",\\n            value=10,\\n        ),\\n        BoolInput(\\n            name=\\\"include_highlights\\\",\\n            display_name=\\\"Include highlights\\\",\\n            value=True,\\n            advanced=True,\\n            info=\\\"Token-efficient extracts of the most relevant text per result. Recommended default.\\\",\\n        ),\\n        IntInput(\\n            name=\\\"highlights_max_characters\\\",\\n            display_name=\\\"Highlights max characters\\\",\\n            value=0,\\n            advanced=True,\\n            info=\\\"Optional cap on the length of each highlight, in characters. 0 leaves it at Exa's default.\\\",\\n        ),\\n        BoolInput(\\n            name=\\\"include_text\\\",\\n            display_name=\\\"Include full text\\\",\\n            value=False,\\n            advanced=True,\\n            info=\\\"Return full page text. Off by default; prefer highlights for token efficiency.\\\",\\n        ),\\n        DropdownInput(\\n            name=\\\"category\\\",\\n            display_name=\\\"Category\\\",\\n            options=[\\n                \\\"\\\",\\n                \\\"company\\\",\\n                \\\"people\\\",\\n                \\\"research paper\\\",\\n                \\\"news\\\",\\n                \\\"personal site\\\",\\n                \\\"financial report\\\",\\n            ],\\n            value=\\\"\\\",\\n            advanced=True,\\n            info=\\\"Restrict to a specific Exa data category. Leave empty for general web search.\\\",\\n        ),\\n        IntInput(\\n            name=\\\"max_age_hours\\\",\\n            display_name=\\\"Max age (hours)\\\",\\n            value=0,\\n            advanced=True,\\n            info=(\\n                \\\"Max age of cached content (in hours) before refetching. \\\"\\n                \\\"0 = always refetch. -1 = never refetch (use cache only).\\\"\\n            ),\\n        ),\\n        MessageTextInput(\\n            name=\\\"include_domains\\\",\\n            display_name=\\\"Include domains\\\",\\n            value=\\\"\\\",\\n            advanced=True,\\n            info=\\\"Comma-separated allowlist of domains.\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"exclude_domains\\\",\\n            display_name=\\\"Exclude domains\\\",\\n            value=\\\"\\\",\\n            advanced=True,\\n            info=\\\"Comma-separated denylist of domains.\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"start_published_date\\\",\\n            display_name=\\\"Start published date\\\",\\n            value=\\\"\\\",\\n            advanced=True,\\n            info=\\\"ISO date (YYYY-MM-DD). Only return results published on or after this date.\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"end_published_date\\\",\\n            display_name=\\\"End published date\\\",\\n            value=\\\"\\\",\\n            advanced=True,\\n            info=\\\"ISO date (YYYY-MM-DD). Only return results published on or before this date.\\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"tools\\\", display_name=\\\"Tools\\\", method=\\\"build_toolkit\\\"),\\n    ]\\n\\n    def _resolved_api_key(self) -> str:\\n        key = self.exa_api_key or self.metaphor_api_key\\n        if not key:\\n            msg = \\\"Exa API key is required. Set the Exa API Key input.\\\"\\n            raise ValueError(msg)\\n        return key\\n\\n    def _build_client(self) -> Exa:\\n        client = Exa(api_key=self._resolved_api_key())\\n        client.headers[\\\"x-exa-integration\\\"] = EXA_INTEGRATION_NAME\\n        return client\\n\\n    def _highlights_value(self) -> bool | dict | None:\\n        if not self.include_highlights:\\n            return None\\n        if self.highlights_max_characters and self.highlights_max_characters > 0:\\n            return {\\\"max_characters\\\": self.highlights_max_characters}\\n        return True\\n\\n    def _contents(self) -> dict | None:\\n        contents: dict = {}\\n        highlights = self._highlights_value()\\n        if highlights is not None:\\n            contents[\\\"highlights\\\"] = highlights\\n        if self.include_text:\\n            contents[\\\"text\\\"] = True\\n        if self.max_age_hours and self.max_age_hours != 0:\\n            contents[\\\"max_age_hours\\\"] = self.max_age_hours\\n        return contents or None\\n\\n    @staticmethod\\n    def _split_csv(raw: str) -> list[str] | None:\\n        items = [s.strip() for s in (raw or \\\"\\\").split(\\\",\\\") if s.strip()]\\n        return items or None\\n\\n    def build_toolkit(self) -> Tool:\\n        client = self._build_client()\\n        contents = self._contents()\\n        category = self.category or None\\n        include_domains = self._split_csv(self.include_domains)\\n        exclude_domains = self._split_csv(self.exclude_domains)\\n        start_published_date = (self.start_published_date or \\\"\\\").strip() or None\\n        end_published_date = (self.end_published_date or \\\"\\\").strip() or None\\n\\n        @tool\\n        def search(query: str):\\n            \\\"\\\"\\\"Search the web with Exa and return results with optional highlights.\\\"\\\"\\\"\\n            kwargs: dict = {\\n                \\\"type\\\": self.search_type,\\n                \\\"num_results\\\": self.search_num_results,\\n            }\\n            if contents is not None:\\n                kwargs[\\\"contents\\\"] = contents\\n            if category:\\n                kwargs[\\\"category\\\"] = category\\n            if include_domains:\\n                kwargs[\\\"include_domains\\\"] = include_domains\\n            if exclude_domains:\\n                kwargs[\\\"exclude_domains\\\"] = exclude_domains\\n            if start_published_date:\\n                kwargs[\\\"start_published_date\\\"] = start_published_date\\n            if end_published_date:\\n                kwargs[\\\"end_published_date\\\"] = end_published_date\\n            return client.search(query, **kwargs)\\n\\n        @tool\\n        def get_contents(ids: list[str]):\\n            \\\"\\\"\\\"Fetch contents (highlights and/or text) for result IDs returned by `search`.\\\"\\\"\\\"\\n            kwargs: dict = {}\\n            highlights = self._highlights_value()\\n            if highlights is not None:\\n                kwargs[\\\"highlights\\\"] = highlights\\n            if self.include_text:\\n                kwargs[\\\"text\\\"] = True\\n            if self.max_age_hours and self.max_age_hours != 0:\\n                kwargs[\\\"max_age_hours\\\"] = self.max_age_hours\\n            return client.get_contents(ids, **kwargs)\\n\\n        return [search, get_contents]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/exa/src/lfx_exa/extension.json\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"dd1ea3e28dc47bcf86a97c73ec28cb28db4f82b4caac7a9aac7ac4d6148f65bf\",\"content\":\"{\\n  \\\"$schema\\\": \\\"https://schemas.langflow.org/extension/v1.json\\\",\\n  \\\"id\\\": \\\"lfx-exa\\\",\\n  \\\"version\\\": \\\"0.1.3\\\",\\n  \\\"name\\\": \\\"Exa\\\",\\n  \\\"description\\\": \\\"Exa web-search and contents tools (exa-py SDK) as a standalone Langflow Extension Bundle.\\\",\\n  \\\"lfx\\\": {\\n    \\\"compat\\\": [\\\"1\\\"]\\n  },\\n  \\\"bundles\\\": [\\n    {\\n      \\\"name\\\": \\\"exa\\\",\\n      \\\"path\\\": \\\"components/exa\\\"\\n    }\\n  ]\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/exa/tests/test_exa_search_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"282ce78541a8f5c7460582b2bf179b7f1552c574e61fb92eb360d52a60f90e68\",\"content\":\"\\\"\\\"\\\"Unit tests for the Exa Search extension bundle (``lfx-exa``).\\n\\nAdapted from the pre-bundle-split suite contributed in\\nlangflow-ai/langflow#13001; the component now ships as a standalone\\nbundle, so these tests travel with the bundle and import the public\\nbundle entry point.  ``exa_py`` is a hard runtime dep of the bundle, so\\nthe client class is patched at the component module rather than mocked\\nat import time.  No network access is required.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom lfx_exa import ExaSearchToolkit\\n\\nCLIENT_PATCH_TARGET = \\\"lfx_exa.components.exa.exa_search.Exa\\\"\\n\\n\\n@pytest.fixture\\ndef component() -> ExaSearchToolkit:\\n    \\\"\\\"\\\"Build an ExaSearchToolkit with sensible defaults set.\\\"\\\"\\\"\\n    c = ExaSearchToolkit()\\n    c.exa_api_key = \\\"test-key\\\"  # pragma: allowlist secret\\n    c.metaphor_api_key = \\\"\\\"\\n    c.search_type = \\\"auto\\\"\\n    c.search_num_results = 10\\n    c.include_highlights = True\\n    c.highlights_max_characters = 0\\n    c.include_text = False\\n    c.category = \\\"\\\"\\n    c.max_age_hours = 0\\n    c.include_domains = \\\"\\\"\\n    c.exclude_domains = \\\"\\\"\\n    c.start_published_date = \\\"\\\"\\n    c.end_published_date = \\\"\\\"\\n    return c\\n\\n\\ndef test_component_metadata():\\n    \\\"\\\"\\\"Class name and component name must stay stable for saved flows.\\\"\\\"\\\"\\n    assert ExaSearchToolkit.__name__ == \\\"ExaSearchToolkit\\\"\\n    assert ExaSearchToolkit.name == \\\"ExaSearch\\\"\\n\\n\\ndef test_resolved_api_key_prefers_exa_key(component):\\n    \\\"\\\"\\\"`exa_api_key` wins when both are set.\\\"\\\"\\\"\\n    component.metaphor_api_key = \\\"legacy\\\"  # pragma: allowlist secret\\n    assert component._resolved_api_key() == \\\"test-key\\\"\\n\\n\\ndef test_resolved_api_key_falls_back_to_metaphor(component):\\n    \\\"\\\"\\\"Old saved flows that only have `metaphor_api_key` keep working.\\\"\\\"\\\"\\n    component.exa_api_key = \\\"\\\"\\n    component.metaphor_api_key = \\\"legacy\\\"  # pragma: allowlist secret\\n    assert component._resolved_api_key() == \\\"legacy\\\"\\n\\n\\ndef test_resolved_api_key_raises_when_both_empty(component):\\n    \\\"\\\"\\\"No key set on either field -> clear ValueError instead of silent empty string.\\\"\\\"\\\"\\n    component.exa_api_key = \\\"\\\"\\n    component.metaphor_api_key = \\\"\\\"\\n    with pytest.raises(ValueError, match=\\\"Exa API key is required\\\"):\\n        component._resolved_api_key()\\n\\n\\ndef test_build_client_sets_integration_header(component):\\n    \\\"\\\"\\\"Client should be built with the API key and the integration header.\\\"\\\"\\\"\\n    with patch(CLIENT_PATCH_TARGET) as mock_exa:\\n        mock_exa.return_value.headers = {}\\n        client = component._build_client()\\n        mock_exa.assert_called_once_with(api_key=\\\"test-key\\\")  # pragma: allowlist secret\\n        assert client.headers[\\\"x-exa-integration\\\"] == \\\"langflow-integration\\\"\\n\\n\\ndef test_highlights_value_default_true(component):\\n    \\\"\\\"\\\"Default highlights config is just `True`.\\\"\\\"\\\"\\n    assert component._highlights_value() is True\\n\\n\\ndef test_highlights_value_with_max_characters(component):\\n    \\\"\\\"\\\"Setting max characters returns the dict shape Exa expects.\\\"\\\"\\\"\\n    component.highlights_max_characters = 200\\n    assert component._highlights_value() == {\\\"max_characters\\\": 200}\\n\\n\\ndef test_highlights_value_disabled(component):\\n    \\\"\\\"\\\"Turning highlights off returns None so it's omitted from the payload.\\\"\\\"\\\"\\n    component.include_highlights = False\\n    assert component._highlights_value() is None\\n\\n\\ndef test_contents_default_payload(component):\\n    \\\"\\\"\\\"Default contents payload only includes highlights.\\\"\\\"\\\"\\n    assert component._contents() == {\\\"highlights\\\": True}\\n\\n\\ndef test_contents_with_text_and_max_age(component):\\n    \\\"\\\"\\\"Text and max_age_hours are included alongside highlights when set.\\\"\\\"\\\"\\n    component.include_text = True\\n    component.max_age_hours = 24\\n    assert component._contents() == {\\n        \\\"highlights\\\": True,\\n        \\\"text\\\": True,\\n        \\\"max_age_hours\\\": 24,\\n    }\\n\\n\\ndef test_contents_returns_none_when_everything_off(component):\\n    \\\"\\\"\\\"No highlights, no text, no max_age -> no contents dict at all.\\\"\\\"\\\"\\n    component.include_highlights = False\\n    component.include_text = False\\n    component.max_age_hours = 0\\n    assert component._contents() is None\\n\\n\\ndef test_split_csv_handles_spaces_and_empty():\\n    \\\"\\\"\\\"Domain lists are split, trimmed, and `None` when empty.\\\"\\\"\\\"\\n    assert ExaSearchToolkit._split_csv(\\\"a.com, b.com ,c.com\\\") == [\\n        \\\"a.com\\\",\\n        \\\"b.com\\\",\\n        \\\"c.com\\\",\\n    ]\\n    assert ExaSearchToolkit._split_csv(\\\"\\\") is None\\n    assert ExaSearchToolkit._split_csv(\\\"   \\\") is None\\n\\n\\ndef test_build_toolkit_exposes_two_tools(component):\\n    \\\"\\\"\\\"Toolkit must expose exactly `search` and `get_contents` (no find_similar).\\\"\\\"\\\"\\n    with patch(CLIENT_PATCH_TARGET) as mock_exa:\\n        mock_exa.return_value.headers = {}\\n        tools = component.build_toolkit()\\n        assert [t.name for t in tools] == [\\\"search\\\", \\\"get_contents\\\"]\\n\\n\\ndef test_search_tool_default_kwargs(component):\\n    \\\"\\\"\\\"Default search call uses type=auto, num_results=10, contents={highlights: True}.\\\"\\\"\\\"\\n    mock_client = MagicMock()\\n    mock_client.headers = {}\\n    with patch(CLIENT_PATCH_TARGET, return_value=mock_client):\\n        tools = component.build_toolkit()\\n        search_tool = next(t for t in tools if t.name == \\\"search\\\")\\n        search_tool.invoke({\\\"query\\\": \\\"hello\\\"})\\n        mock_client.search.assert_called_once_with(\\n            \\\"hello\\\",\\n            type=\\\"auto\\\",\\n            num_results=10,\\n            contents={\\\"highlights\\\": True},\\n        )\\n\\n\\ndef test_search_tool_passes_filters(component):\\n    \\\"\\\"\\\"Category, domain lists, and date filters should reach client.search().\\\"\\\"\\\"\\n    component.category = \\\"company\\\"\\n    component.include_domains = \\\"a.com, b.com\\\"\\n    component.exclude_domains = \\\"spam.com\\\"\\n    component.start_published_date = \\\"2024-01-01\\\"\\n    component.end_published_date = \\\"2024-12-31\\\"\\n\\n    mock_client = MagicMock()\\n    mock_client.headers = {}\\n    with patch(CLIENT_PATCH_TARGET, return_value=mock_client):\\n        tools = component.build_toolkit()\\n        search_tool = next(t for t in tools if t.name == \\\"search\\\")\\n        search_tool.invoke({\\\"query\\\": \\\"q\\\"})\\n\\n        call = mock_client.search.call_args\\n        assert call.kwargs[\\\"category\\\"] == \\\"company\\\"\\n        assert call.kwargs[\\\"include_domains\\\"] == [\\\"a.com\\\", \\\"b.com\\\"]\\n        assert call.kwargs[\\\"exclude_domains\\\"] == [\\\"spam.com\\\"]\\n        assert call.kwargs[\\\"start_published_date\\\"] == \\\"2024-01-01\\\"\\n        assert call.kwargs[\\\"end_published_date\\\"] == \\\"2024-12-31\\\"\\n\\n\\ndef test_get_contents_tool_kwargs(component):\\n    \\\"\\\"\\\"get_contents passes highlights/text/max_age_hours as flat kwargs.\\\"\\\"\\\"\\n    component.highlights_max_characters = 300\\n    component.include_text = True\\n    component.max_age_hours = 12\\n\\n    mock_client = MagicMock()\\n    mock_client.headers = {}\\n    with patch(CLIENT_PATCH_TARGET, return_value=mock_client):\\n        tools = component.build_toolkit()\\n        get_contents_tool = next(t for t in tools if t.name == \\\"get_contents\\\")\\n        get_contents_tool.invoke({\\\"ids\\\": [\\\"abc\\\"]})\\n\\n        mock_client.get_contents.assert_called_once_with(\\n            [\\\"abc\\\"],\\n            highlights={\\\"max_characters\\\": 300},\\n            text=True,\\n            max_age_hours=12,\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/firecrawl/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"72228a5e399d5d7672000957c2caaa75a06d01f5c06253d6a3cdeb1c62fa67b3\",\"content\":\"# lfx-firecrawl\\n\\nFirecrawl components (Scrape, Crawl, Map, and Search APIs) as a standalone\\nLangflow Extension Bundle, built against the firecrawl-py v2 SDK.\\n\\n## Install\\n\\n```bash\\npip install lfx-firecrawl\\n```\\n\\nThe bundle is registered automatically via the `langflow.extensions`\\nentry-point.  After install, restart your Langflow server; the bundle's\\ncomponents will appear in the palette under the `firecrawl` group.\\n\\n## Develop\\n\\n```bash\\ncd src/bundles/firecrawl\\npip install -e .\\nlfx extension validate src/lfx_firecrawl\\n```\\n\\n## Migration\\n\\nSaved flows referencing the legacy class name(s) or the old import paths\\nunder `lfx.components.firecrawl.*` are rewritten to the new namespaced\\nIDs by the migration table in\\n`src/lfx/src/lfx/extension/migration/migration_table.json`.\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/firecrawl/pyproject.toml\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"69379fa55ed333e28f967ad1314cf1404f6313ea7738aea6007e48bbb82d820e\",\"content\":\"[project]\\nname = \\\"lfx-firecrawl\\\"\\nversion = \\\"0.1.3\\\"\\ndescription = \\\"Firecrawl components (Scrape, Crawl, Map, and Search APIs) as a standalone Langflow Extension Bundle.\\\"\\nreadme = \\\"README.md\\\"\\nrequires-python = \\\">=3.10,<3.15\\\"\\nlicense = { text = \\\"MIT\\\" }\\nauthors = [\\n    { name = \\\"Langflow\\\", email = \\\"contact@langflow.org\\\" },\\n]\\nkeywords = [\\\"langflow\\\", \\\"lfx\\\", \\\"extension\\\", \\\"bundle\\\", \\\"firecrawl\\\"]\\n\\n# Runtime deps: lfx (the BUNDLE_API surface) plus any third-party imports\\n# the bundle's components rely on.  REVIEW THIS LIST -- the script ports\\n# only ``lfx``; add any other deps the moved component(s) import.\\n# lfx is floored at the current major.minor line and capped below the next\\n# lfx major (e.g. \\\"lfx>=1.10.0,<2.0.0\\\"); the floor is read from\\n# src/lfx/pyproject.toml at port time and re-synced on ``make patch`` via\\n# scripts/ci/sync_bundle_lfx_pin.py.  Fine-grained BUNDLE_API compatibility\\n# is enforced via extension.json's lfx.compat list against BUNDLE_API_VERSION.\\ndependencies = [\\n    \\\"lfx>=1.12.0.dev0,<2.0.0\\\",\\n    \\\"firecrawl-py>=4.0.0,<5.0.0\\\",\\n]\\n\\n[project.urls]\\nHomepage = \\\"https://github.com/langflow-ai/langflow\\\"\\nDocumentation = \\\"https://docs.langflow.org/extensions\\\"\\nRepository = \\\"https://github.com/langflow-ai/langflow\\\"\\n\\n# Manifest-shipping distributions are discovered via the\\n# ``langflow.extensions`` entry-point.  Editable installs whose\\n# ``dist.files`` only surfaces dist-info entries fall back to this\\n# entry-point to find the manifest.\\n[project.entry-points.\\\"langflow.extensions\\\"]\\nlfx-firecrawl = \\\"lfx_firecrawl\\\"\\n\\n[build-system]\\nrequires = [\\\"hatchling==1.31.0\\\"]\\nbuild-backend = \\\"hatchling.build\\\"\\n\\n[tool.hatch.build.targets.wheel]\\n# extension.json + components live inside the lfx_firecrawl package so\\n# ``importlib.metadata.files(dist)`` finds them and the loader resolves\\n# bundles[].path relative to the manifest's directory.\\npackages = [\\\"src/lfx_firecrawl\\\"]\\ninclude = [\\\"src/lfx_firecrawl/extension.json\\\", \\\"src/lfx_firecrawl/components/**/*.py\\\"]\\n\\n[tool.hatch.build.targets.sdist]\\ninclude = [\\n    \\\"src/lfx_firecrawl\\\",\\n    \\\"extension.json\\\",\\n    \\\"README.md\\\",\\n    \\\"pyproject.toml\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/firecrawl/src/lfx_firecrawl/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2d28117a0b87d72d3558235b43e9a8a889270839d3d5284da15d9642b00764d3\",\"content\":\"\\\"\\\"\\\"lfx-firecrawl: Firecrawl bundle.\\n\\nDistribution unit ``lfx-firecrawl``.  At runtime Langflow's loader\\ndiscovers ``extension.json`` shipped alongside this ``__init__.py`` and\\nregisters the bundle's components under the namespaced IDs\\n``ext:firecrawl:<Class>@official``.\\n\\\"\\\"\\\"\\n\\nfrom lfx_firecrawl.components.firecrawl.firecrawl_crawl_api import FirecrawlCrawlApi\\nfrom lfx_firecrawl.components.firecrawl.firecrawl_map_api import FirecrawlMapApi\\nfrom lfx_firecrawl.components.firecrawl.firecrawl_scrape_api import FirecrawlScrapeApi\\nfrom lfx_firecrawl.components.firecrawl.firecrawl_search_api import FirecrawlSearchApi\\n\\n__all__ = [\\\"FirecrawlCrawlApi\\\", \\\"FirecrawlMapApi\\\", \\\"FirecrawlScrapeApi\\\", \\\"FirecrawlSearchApi\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/firecrawl/src/lfx_firecrawl/components/firecrawl/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"af6d86140aefba7bba7e2d4477e014c6621318430bcbd514ece5d4e8bf80180a\",\"content\":\"\\\"\\\"\\\"Component re-exports for the ``firecrawl`` bundle.\\n\\nSaved-flow migration entries that target ``lfx.components.firecrawl.<Class>``\\nresolve through this package, so the moved Component class(es) must be\\nimportable from here by name.\\n\\\"\\\"\\\"\\n\\nfrom .firecrawl_crawl_api import FirecrawlCrawlApi\\nfrom .firecrawl_map_api import FirecrawlMapApi\\nfrom .firecrawl_scrape_api import FirecrawlScrapeApi\\nfrom .firecrawl_search_api import FirecrawlSearchApi\\n\\n__all__ = [\\\"FirecrawlCrawlApi\\\", \\\"FirecrawlMapApi\\\", \\\"FirecrawlScrapeApi\\\", \\\"FirecrawlSearchApi\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/firecrawl/src/lfx_firecrawl/components/firecrawl/firecrawl_crawl_api.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1301838baf0f53b78fb89840817857649438c409f67b9a61f79fb6b930c70c0d\",\"content\":\"import re\\n\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import DataInput, IntInput, MultilineInput, Output, SecretStrInput, StrInput\\nfrom lfx.schema.data import Data\\n\\n_CAMEL_TO_SNAKE_RE = re.compile(r\\\"(?<!^)(?=[A-Z])\\\")\\n\\n\\ndef _to_snake_case_kwargs(params: dict) -> dict:\\n    \\\"\\\"\\\"Convert camelCase option keys to snake_case keyword arguments.\\n\\n    The firecrawl-py v1 convention uses camelCase, while the v2 SDK expects\\n    snake_case keyword arguments. Keys that are already snake_case are passed\\n    through unchanged.\\n    \\\"\\\"\\\"\\n    return {_CAMEL_TO_SNAKE_RE.sub(\\\"_\\\", key).lower(): value for key, value in params.items()}\\n\\n\\nclass FirecrawlCrawlApi(Component):\\n    display_name: str = \\\"Firecrawl Crawl API\\\"\\n    description: str = \\\"Crawls a URL and returns the results.\\\"\\n    name = \\\"FirecrawlCrawlApi\\\"\\n\\n    documentation: str = \\\"https://docs.firecrawl.dev/v1/api-reference/endpoint/crawl-post\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"Firecrawl API Key\\\",\\n            required=True,\\n            password=True,\\n            info=\\\"The API key to use Firecrawl API.\\\",\\n        ),\\n        MultilineInput(\\n            name=\\\"url\\\",\\n            display_name=\\\"URL\\\",\\n            required=True,\\n            info=\\\"The URL to scrape.\\\",\\n            tool_mode=True,\\n        ),\\n        IntInput(\\n            name=\\\"timeout\\\",\\n            display_name=\\\"Timeout\\\",\\n            info=\\\"Timeout in milliseconds for the request.\\\",\\n        ),\\n        StrInput(\\n            name=\\\"idempotency_key\\\",\\n            display_name=\\\"Idempotency Key\\\",\\n            info=\\\"Optional idempotency key to ensure unique requests.\\\",\\n        ),\\n        DataInput(\\n            name=\\\"crawlerOptions\\\",\\n            display_name=\\\"Crawler Options\\\",\\n            info=\\\"The crawler options to send with the request.\\\",\\n        ),\\n        DataInput(\\n            name=\\\"scrapeOptions\\\",\\n            display_name=\\\"Scrape Options\\\",\\n            info=\\\"The page options to send with the request.\\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"JSON\\\", name=\\\"data\\\", method=\\\"crawl\\\"),\\n    ]\\n    idempotency_key: str | None = None\\n\\n    def crawl(self) -> Data:\\n        try:\\n            from firecrawl import Firecrawl\\n            from firecrawl.v2.types import ScrapeOptions\\n        except ImportError as e:\\n            msg = \\\"Could not import firecrawl integration package. Please install it with `pip install firecrawl-py`.\\\"\\n            raise ImportError(msg) from e\\n\\n        params = dict(self.crawlerOptions.__dict__.get(\\\"data\\\", {})) if self.crawlerOptions else {}\\n        scrape_options_dict = dict(self.scrapeOptions.__dict__.get(\\\"data\\\", {})) if self.scrapeOptions else {}\\n\\n        # Set default values for crawl parameters.\\n        # Note: firecrawl-py v2 renamed several options. \\\"maxDepth\\\" -> \\\"max_discovery_depth\\\"\\n        # and \\\"allowBackwardLinks\\\" -> \\\"crawl_entire_domain\\\".\\n        params.setdefault(\\\"maxDepth\\\", 2)\\n        params.setdefault(\\\"limit\\\", 10000)\\n        params.setdefault(\\\"allowExternalLinks\\\", False)\\n        params.setdefault(\\\"allowBackwardLinks\\\", False)\\n        params.setdefault(\\\"ignoreQueryParameters\\\", False)\\n\\n        # Ensure onlyMainContent is explicitly set if not provided.\\n        scrape_options_dict.setdefault(\\\"onlyMainContent\\\", True)\\n\\n        # Translate legacy v1 camelCase option names to the firecrawl-py v2 keyword args.\\n        kwargs = _to_snake_case_kwargs(params)\\n        if \\\"max_depth\\\" in kwargs:\\n            kwargs[\\\"max_discovery_depth\\\"] = kwargs.pop(\\\"max_depth\\\")\\n        if \\\"allow_backward_links\\\" in kwargs:\\n            kwargs[\\\"crawl_entire_domain\\\"] = kwargs.pop(\\\"allow_backward_links\\\")\\n        # v2 removed \\\"ignore_sitemap\\\"; it is now the \\\"sitemap\\\" mode enum.\\n        if kwargs.pop(\\\"ignore_sitemap\\\", False):\\n            kwargs[\\\"sitemap\\\"] = \\\"skip\\\"\\n\\n        # Build the typed ScrapeOptions object expected by v2 from the (snake_cased) dict.\\n        scrape_kwargs = _to_snake_case_kwargs(scrape_options_dict)\\n        kwargs[\\\"scrape_options\\\"] = ScrapeOptions(**scrape_kwargs)\\n\\n        app = Firecrawl(api_key=self.api_key)\\n        # v2 polls to completion and returns a typed CrawlJob object.\\n        crawl_job = app.crawl(self.url, **kwargs)\\n        return Data(data={\\\"results\\\": crawl_job.model_dump()})\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/firecrawl/src/lfx_firecrawl/components/firecrawl/firecrawl_map_api.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"56a23f3135492db61a4bfb76992f042ce29f701a717d85d83735ea98cee2a901\",\"content\":\"from lfx.custom.custom_component.component import Component\\nfrom lfx.io import (\\n    BoolInput,\\n    MultilineInput,\\n    Output,\\n    SecretStrInput,\\n)\\nfrom lfx.schema.data import Data\\n\\n\\nclass FirecrawlMapApi(Component):\\n    display_name: str = \\\"Firecrawl Map API\\\"\\n    description: str = \\\"Maps a URL and returns the results.\\\"\\n    name = \\\"FirecrawlMapApi\\\"\\n\\n    documentation: str = \\\"https://docs.firecrawl.dev/api-reference/endpoint/map\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"Firecrawl API Key\\\",\\n            required=True,\\n            password=True,\\n            info=\\\"The API key to use Firecrawl API.\\\",\\n        ),\\n        MultilineInput(\\n            name=\\\"urls\\\",\\n            display_name=\\\"URLs\\\",\\n            required=True,\\n            info=\\\"List of URLs to create maps from (separated by commas or new lines).\\\",\\n            tool_mode=True,\\n        ),\\n        BoolInput(\\n            name=\\\"ignore_sitemap\\\",\\n            display_name=\\\"Ignore Sitemap\\\",\\n            info=\\\"When true, the sitemap.xml file will be ignored during crawling.\\\",\\n        ),\\n        BoolInput(\\n            name=\\\"sitemap_only\\\",\\n            display_name=\\\"Sitemap Only\\\",\\n            info=\\\"When true, only links found in the sitemap will be returned.\\\",\\n        ),\\n        BoolInput(\\n            name=\\\"include_subdomains\\\",\\n            display_name=\\\"Include Subdomains\\\",\\n            info=\\\"When true, subdomains of the provided URL will also be scanned.\\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"JSON\\\", name=\\\"data\\\", method=\\\"map\\\"),\\n    ]\\n\\n    def map(self) -> Data:\\n        try:\\n            from firecrawl import Firecrawl\\n        except ImportError as e:\\n            msg = \\\"Could not import firecrawl integration package. Please install it with `pip install firecrawl-py`.\\\"\\n            raise ImportError(msg) from e\\n\\n        # Validate URLs\\n        if not self.urls:\\n            msg = \\\"URLs are required\\\"\\n            raise ValueError(msg)\\n\\n        # Split and validate URLs (handle both commas and newlines)\\n        urls = [url.strip() for url in self.urls.replace(\\\"\\\\n\\\", \\\",\\\").split(\\\",\\\") if url.strip()]\\n        if not urls:\\n            msg = \\\"No valid URLs provided\\\"\\n            raise ValueError(msg)\\n\\n        # firecrawl-py v2 replaced the separate \\\"ignoreSitemap\\\"/\\\"sitemapOnly\\\" flags with a\\n        # single \\\"sitemap\\\" mode: \\\"only\\\" (sitemap only), \\\"skip\\\" (ignore sitemap), or the\\n        # default mixed behavior.\\n        kwargs: dict = {\\\"include_subdomains\\\": self.include_subdomains}\\n        if self.sitemap_only:\\n            kwargs[\\\"sitemap\\\"] = \\\"only\\\"\\n        elif self.ignore_sitemap:\\n            kwargs[\\\"sitemap\\\"] = \\\"skip\\\"\\n\\n        app = Firecrawl(api_key=self.api_key)\\n\\n        # Map all provided URLs and combine results.\\n        combined_links = []\\n        for url in urls:\\n            result = app.map(url, **kwargs)\\n            # v2 returns a typed MapData object whose .links is a list of typed\\n            # SearchResult objects; serialize each to a dict for downstream consumers.\\n            links = getattr(result, \\\"links\\\", None) or []\\n            combined_links.extend(link.model_dump() if hasattr(link, \\\"model_dump\\\") else link for link in links)\\n\\n        map_result = {\\\"success\\\": True, \\\"links\\\": combined_links}\\n\\n        return Data(data=map_result)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/firecrawl/src/lfx_firecrawl/components/firecrawl/firecrawl_scrape_api.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"20248f97c2485ece2f2a968b13600c955be7a6388bb9db3d72208f265401d3d3\",\"content\":\"import re\\n\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import (\\n    DataInput,\\n    IntInput,\\n    MultilineInput,\\n    Output,\\n    SecretStrInput,\\n)\\nfrom lfx.schema.data import Data\\n\\n_CAMEL_TO_SNAKE_RE = re.compile(r\\\"(?<!^)(?=[A-Z])\\\")\\n\\n\\ndef _to_snake_case_kwargs(params: dict) -> dict:\\n    \\\"\\\"\\\"Convert camelCase option keys to snake_case keyword arguments.\\n\\n    The firecrawl-py v1 convention uses camelCase, while the v2 SDK expects\\n    snake_case keyword arguments. Keys that are already snake_case are passed\\n    through unchanged.\\n    \\\"\\\"\\\"\\n    return {_CAMEL_TO_SNAKE_RE.sub(\\\"_\\\", key).lower(): value for key, value in params.items()}\\n\\n\\nclass FirecrawlScrapeApi(Component):\\n    display_name: str = \\\"Firecrawl Scrape API\\\"\\n    description: str = \\\"Scrapes a URL and returns the results.\\\"\\n    name = \\\"FirecrawlScrapeApi\\\"\\n\\n    documentation: str = \\\"https://docs.firecrawl.dev/api-reference/endpoint/scrape\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"Firecrawl API Key\\\",\\n            required=True,\\n            password=True,\\n            info=\\\"The API key to use Firecrawl API.\\\",\\n        ),\\n        MultilineInput(\\n            name=\\\"url\\\",\\n            display_name=\\\"URL\\\",\\n            required=True,\\n            info=\\\"The URL to scrape.\\\",\\n            tool_mode=True,\\n        ),\\n        IntInput(\\n            name=\\\"timeout\\\",\\n            display_name=\\\"Timeout\\\",\\n            info=\\\"Timeout in milliseconds for the request.\\\",\\n        ),\\n        DataInput(\\n            name=\\\"scrapeOptions\\\",\\n            display_name=\\\"Scrape Options\\\",\\n            info=\\\"The page options to send with the request.\\\",\\n        ),\\n        DataInput(\\n            name=\\\"extractorOptions\\\",\\n            display_name=\\\"Extractor Options\\\",\\n            info=\\\"The extractor options to send with the request.\\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"JSON\\\", name=\\\"data\\\", method=\\\"scrape\\\"),\\n    ]\\n\\n    def scrape(self) -> Data:\\n        try:\\n            from firecrawl import Firecrawl\\n        except ImportError as e:\\n            msg = \\\"Could not import firecrawl integration package. Please install it with `pip install firecrawl-py`.\\\"\\n            raise ImportError(msg) from e\\n\\n        params = dict(self.scrapeOptions.__dict__.get(\\\"data\\\", {})) if self.scrapeOptions else {}\\n\\n        # Set default values for parameters\\n        params.setdefault(\\\"formats\\\", [\\\"markdown\\\"])  # Default output format\\n        params.setdefault(\\\"onlyMainContent\\\", True)  # Default to only main content\\n        if self.timeout:\\n            params.setdefault(\\\"timeout\\\", self.timeout)\\n\\n        kwargs = _to_snake_case_kwargs(params)\\n\\n        # In firecrawl-py v2, structured extraction is requested via a \\\"json\\\" format entry\\n        # on the scrape call rather than a separate extractor option.\\n        extractor_options_dict = self.extractorOptions.__dict__.get(\\\"data\\\", {}) if self.extractorOptions else {}\\n        if extractor_options_dict:\\n            formats = list(kwargs.get(\\\"formats\\\", []))\\n            formats.append({\\\"type\\\": \\\"json\\\", **_to_snake_case_kwargs(extractor_options_dict)})\\n            kwargs[\\\"formats\\\"] = formats\\n\\n        app = Firecrawl(api_key=self.api_key)\\n        document = app.scrape(self.url, **kwargs)\\n        # v2 returns a typed Document object; serialize to a dict for downstream consumers.\\n        return Data(data=document.model_dump())\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/firecrawl/src/lfx_firecrawl/components/firecrawl/firecrawl_search_api.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f6cc801c7267022db5804f35ce0c317b01dce3d224da6ba2e064e9119d90c249\",\"content\":\"from lfx.custom.custom_component.component import Component\\nfrom lfx.io import (\\n    IntInput,\\n    MultilineInput,\\n    Output,\\n    SecretStrInput,\\n    StrInput,\\n)\\nfrom lfx.schema.data import Data\\n\\n\\nclass FirecrawlSearchApi(Component):\\n    display_name: str = \\\"Firecrawl Search API\\\"\\n    description: str = \\\"Searches the web and returns the results.\\\"\\n    name = \\\"FirecrawlSearchApi\\\"\\n\\n    documentation: str = \\\"https://docs.firecrawl.dev/api-reference/endpoint/search\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"Firecrawl API Key\\\",\\n            required=True,\\n            password=True,\\n            info=\\\"The API key to use Firecrawl API.\\\",\\n        ),\\n        MultilineInput(\\n            name=\\\"query\\\",\\n            display_name=\\\"Query\\\",\\n            required=True,\\n            info=\\\"The search query to run.\\\",\\n            tool_mode=True,\\n        ),\\n        IntInput(\\n            name=\\\"limit\\\",\\n            display_name=\\\"Limit\\\",\\n            info=\\\"Maximum number of results to return.\\\",\\n            value=5,\\n        ),\\n        StrInput(\\n            name=\\\"location\\\",\\n            display_name=\\\"Location\\\",\\n            info=\\\"Location to bias the search results (e.g. a country or region).\\\",\\n            advanced=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"JSON\\\", name=\\\"data\\\", method=\\\"search\\\"),\\n    ]\\n\\n    def search(self) -> Data:\\n        try:\\n            from firecrawl import Firecrawl\\n        except ImportError as e:\\n            msg = \\\"Could not import firecrawl integration package. Please install it with `pip install firecrawl-py`.\\\"\\n            raise ImportError(msg) from e\\n\\n        if not self.query:\\n            msg = \\\"Query is required\\\"\\n            raise ValueError(msg)\\n\\n        kwargs: dict = {}\\n        if self.limit:\\n            kwargs[\\\"limit\\\"] = self.limit\\n        if self.location:\\n            kwargs[\\\"location\\\"] = self.location\\n\\n        app = Firecrawl(api_key=self.api_key)\\n        result = app.search(self.query, **kwargs)\\n\\n        # v2 returns a typed SearchData object (results grouped by source);\\n        # serialize to a dict for downstream consumers.\\n        search_result = result.model_dump() if hasattr(result, \\\"model_dump\\\") else result\\n\\n        return Data(data=search_result)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/firecrawl/src/lfx_firecrawl/extension.json\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8205402bd8c386c834a365f926134f970499cb4820adcb4979e8fb28caf8b475\",\"content\":\"{\\n  \\\"$schema\\\": \\\"https://schemas.langflow.org/extension/v1.json\\\",\\n  \\\"id\\\": \\\"lfx-firecrawl\\\",\\n  \\\"version\\\": \\\"0.1.3\\\",\\n  \\\"name\\\": \\\"Firecrawl\\\",\\n  \\\"description\\\": \\\"Firecrawl components (Scrape, Crawl, Map, and Search APIs) as a standalone Langflow Extension Bundle.\\\",\\n  \\\"lfx\\\": {\\n    \\\"compat\\\": [\\\"1\\\"]\\n  },\\n  \\\"bundles\\\": [\\n    {\\n      \\\"name\\\": \\\"firecrawl\\\",\\n      \\\"path\\\": \\\"components/firecrawl\\\"\\n    }\\n  ]\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/firecrawl/tests/test_firecrawl_components.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a933494f0ffac48ee9befb97c6f42fefeacc48634d55fc206f16e5d7e438283c\",\"content\":\"\\\"\\\"\\\"Unit tests for the Firecrawl extension bundle (``lfx-firecrawl``).\\n\\nThe components used to live at ``lfx.components.firecrawl``; they have since\\nbeen extracted into a standalone bundle, so these tests travel with the\\nbundle and import the public bundle entry point.\\n\\nThey verify v2 SDK usage, the v1->v2 parameter mapping, response\\nserialization, and error handling using a mocked Firecrawl SDK. No network\\naccess or real ``firecrawl-py`` install is required: the SDK is injected via\\n``sys.modules`` so the components' in-method ``from firecrawl import ...``\\nstatements resolve to the mocks.\\n\\\"\\\"\\\"\\n\\nimport sys\\nimport types\\nfrom unittest.mock import MagicMock\\n\\nimport pytest\\nfrom lfx_firecrawl import FirecrawlCrawlApi, FirecrawlMapApi, FirecrawlScrapeApi, FirecrawlSearchApi\\n\\n\\n@pytest.fixture\\ndef mock_firecrawl(monkeypatch):\\n    \\\"\\\"\\\"Inject a fake ``firecrawl`` SDK and return the mocked ``Firecrawl`` class.\\n\\n    ``mock_firecrawl.return_value`` is the client instance whose\\n    ``.scrape``/``.crawl``/``.map``/``.extract``/``.search`` methods can be\\n    stubbed per test.\\n    \\\"\\\"\\\"\\n    client_cls = MagicMock(name=\\\"Firecrawl\\\")\\n\\n    firecrawl_mod = types.ModuleType(\\\"firecrawl\\\")\\n    firecrawl_mod.Firecrawl = client_cls\\n\\n    v2_mod = types.ModuleType(\\\"firecrawl.v2\\\")\\n    types_mod = types.ModuleType(\\\"firecrawl.v2.types\\\")\\n    types_mod.ScrapeOptions = MagicMock(name=\\\"ScrapeOptions\\\")\\n    v2_mod.types = types_mod\\n\\n    monkeypatch.setitem(sys.modules, \\\"firecrawl\\\", firecrawl_mod)\\n    monkeypatch.setitem(sys.modules, \\\"firecrawl.v2\\\", v2_mod)\\n    monkeypatch.setitem(sys.modules, \\\"firecrawl.v2.types\\\", types_mod)\\n    return client_cls\\n\\n\\ndef _typed(dump):\\n    \\\"\\\"\\\"Return a fake v2 typed response whose ``model_dump()`` yields ``dump``.\\\"\\\"\\\"\\n    obj = MagicMock()\\n    obj.model_dump.return_value = dump\\n    return obj\\n\\n\\nclass TestFirecrawlScrapeApi:\\n    def test_scrape_calls_v2_and_serializes(self, mock_firecrawl):\\n        client = mock_firecrawl.return_value\\n        client.scrape.return_value = _typed({\\\"markdown\\\": \\\"# Hi\\\", \\\"metadata\\\": {}})\\n\\n        component = FirecrawlScrapeApi()\\n        component._attributes = {\\n            \\\"api_key\\\": \\\"test-key\\\",  # pragma: allowlist secret\\n            \\\"url\\\": \\\"https://example.com\\\",\\n            \\\"timeout\\\": 0,\\n            \\\"scrapeOptions\\\": None,\\n            \\\"extractorOptions\\\": None,\\n        }\\n\\n        result = component.scrape()\\n\\n        mock_firecrawl.assert_called_once_with(api_key=\\\"test-key\\\")  # pragma: allowlist secret\\n        client.scrape.assert_called_once()\\n        assert client.scrape.call_args.args[0] == \\\"https://example.com\\\"\\n        assert result.data == {\\\"markdown\\\": \\\"# Hi\\\", \\\"metadata\\\": {}}\\n\\n    def test_scrape_propagates_sdk_error(self, mock_firecrawl):\\n        client = mock_firecrawl.return_value\\n        client.scrape.side_effect = RuntimeError(\\\"boom\\\")\\n\\n        component = FirecrawlScrapeApi()\\n        component._attributes = {\\n            \\\"api_key\\\": \\\"k\\\",  # pragma: allowlist secret\\n            \\\"url\\\": \\\"https://example.com\\\",\\n            \\\"timeout\\\": 0,\\n            \\\"scrapeOptions\\\": None,\\n            \\\"extractorOptions\\\": None,\\n        }\\n\\n        with pytest.raises(RuntimeError):\\n            component.scrape()\\n\\n\\nclass TestFirecrawlCrawlApi:\\n    def test_crawl_maps_legacy_params_and_serializes(self, mock_firecrawl):\\n        client = mock_firecrawl.return_value\\n        client.crawl.return_value = _typed({\\\"status\\\": \\\"completed\\\", \\\"data\\\": []})\\n\\n        component = FirecrawlCrawlApi()\\n        component._attributes = {\\n            \\\"api_key\\\": \\\"test-key\\\",  # pragma: allowlist secret\\n            \\\"url\\\": \\\"https://example.com\\\",\\n            \\\"timeout\\\": 0,\\n            \\\"idempotency_key\\\": \\\"\\\",\\n            \\\"crawlerOptions\\\": None,\\n            \\\"scrapeOptions\\\": None,\\n        }\\n\\n        result = component.crawl()\\n\\n        mock_firecrawl.assert_called_once_with(api_key=\\\"test-key\\\")  # pragma: allowlist secret\\n        client.crawl.assert_called_once()\\n        assert client.crawl.call_args.args[0] == \\\"https://example.com\\\"\\n        kwargs = client.crawl.call_args.kwargs\\n        # v1 \\\"maxDepth\\\" was renamed to v2 \\\"max_discovery_depth\\\".\\n        assert \\\"max_discovery_depth\\\" in kwargs\\n        assert \\\"max_depth\\\" not in kwargs\\n        # v1 \\\"allowBackwardLinks\\\" was renamed to v2 \\\"crawl_entire_domain\\\".\\n        assert \\\"crawl_entire_domain\\\" in kwargs\\n        assert result.data[\\\"results\\\"] == {\\\"status\\\": \\\"completed\\\", \\\"data\\\": []}\\n\\n\\nclass TestFirecrawlMapApi:\\n    def test_map_sitemap_only_maps_to_enum(self, mock_firecrawl):\\n        client = mock_firecrawl.return_value\\n        result_obj = MagicMock()\\n        result_obj.links = [_typed({\\\"url\\\": \\\"https://example.com/a\\\"})]\\n        client.map.return_value = result_obj\\n\\n        component = FirecrawlMapApi()\\n        component._attributes = {\\n            \\\"api_key\\\": \\\"test-key\\\",  # pragma: allowlist secret\\n            \\\"urls\\\": \\\"https://example.com\\\",\\n            \\\"ignore_sitemap\\\": False,\\n            \\\"sitemap_only\\\": True,\\n            \\\"include_subdomains\\\": False,\\n        }\\n\\n        result = component.map()\\n\\n        client.map.assert_called_once()\\n        assert client.map.call_args.kwargs.get(\\\"sitemap\\\") == \\\"only\\\"\\n        assert result.data[\\\"links\\\"] == [{\\\"url\\\": \\\"https://example.com/a\\\"}]\\n\\n    def test_map_ignore_sitemap_maps_to_skip(self, mock_firecrawl):\\n        client = mock_firecrawl.return_value\\n        result_obj = MagicMock()\\n        result_obj.links = []\\n        client.map.return_value = result_obj\\n\\n        component = FirecrawlMapApi()\\n        component._attributes = {\\n            \\\"api_key\\\": \\\"k\\\",  # pragma: allowlist secret\\n            \\\"urls\\\": \\\"https://example.com\\\",\\n            \\\"ignore_sitemap\\\": True,\\n            \\\"sitemap_only\\\": False,\\n            \\\"include_subdomains\\\": False,\\n        }\\n\\n        component.map()\\n\\n        assert client.map.call_args.kwargs.get(\\\"sitemap\\\") == \\\"skip\\\"\\n\\n\\nclass TestFirecrawlSearchApi:\\n    def test_search_calls_v2_with_query_limit_location(self, mock_firecrawl):\\n        client = mock_firecrawl.return_value\\n        client.search.return_value = _typed({\\\"web\\\": [{\\\"url\\\": \\\"https://example.com\\\"}]})\\n\\n        component = FirecrawlSearchApi()\\n        component._attributes = {\\n            \\\"api_key\\\": \\\"test-key\\\",  # pragma: allowlist secret\\n            \\\"query\\\": \\\"firecrawl\\\",\\n            \\\"limit\\\": 5,\\n            \\\"location\\\": \\\"US\\\",\\n        }\\n\\n        result = component.search()\\n\\n        mock_firecrawl.assert_called_once_with(api_key=\\\"test-key\\\")  # pragma: allowlist secret\\n        client.search.assert_called_once()\\n        assert client.search.call_args.args[0] == \\\"firecrawl\\\"\\n        assert client.search.call_args.kwargs.get(\\\"limit\\\") == 5\\n        assert client.search.call_args.kwargs.get(\\\"location\\\") == \\\"US\\\"\\n        assert result.data == {\\\"web\\\": [{\\\"url\\\": \\\"https://example.com\\\"}]}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/google/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cae25a83cd9ce76d4148421e03866316d3d2015cf84c6c07521a6d5f7ab5e392\",\"content\":\"# lfx-google\\n\\nGoogle and Gemini components as a standalone Langflow Extension Bundle.\\n\\n## Install\\n\\n```bash\\npip install lfx-google\\n```\\n\\n`pip install langflow` includes this bundle because Google Generative AI is a\\nsupported model provider. The bundle is registered automatically through the\\n`langflow.extensions` entry point and appears under the `google` group with\\ncanonical component IDs such as\\n`ext:google:GoogleGenerativeAIComponent@official`.\\n\\n## Develop\\n\\n```bash\\nuv sync\\nuv run pytest src/bundles/google/tests -q\\nuv run lfx extension validate src/bundles/google/src/lfx_google\\n```\\n\\nThe bundle graduated from the manifest-less `lfx-bundles[google]` provider in\\nLangflow 1.12. Its bundle and class names are unchanged, so existing saved\\nflows retain their canonical IDs.\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/google/pyproject.toml\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3a807747b4d62276c98f4e908b47abee3055d419817924f30dc2f395f3dc2bb2\",\"content\":\"[project]\\nname = \\\"lfx-google\\\"\\nversion = \\\"0.1.2\\\"\\ndescription = \\\"Google and Gemini components as a standalone Langflow Extension Bundle.\\\"\\nreadme = \\\"README.md\\\"\\nrequires-python = \\\">=3.10,<3.15\\\"\\nlicense = { text = \\\"MIT\\\" }\\nauthors = [\\n    { name = \\\"Langflow\\\", email = \\\"contact@langflow.org\\\" },\\n]\\nkeywords = [\\\"langflow\\\", \\\"lfx\\\", \\\"extension\\\", \\\"bundle\\\", \\\"google\\\", \\\"gemini\\\"]\\n\\n# Runtime deps: lfx (the BUNDLE_API surface) plus every third-party package\\n# imported by the Google components. Keep these dependencies with the bundle\\n# so a default Langflow install can discover and build Gemini models without\\n# relying on the opt-in lfx-bundles metapackage.\\ndependencies = [\\n    \\\"lfx>=1.12.0.dev0,<2.0.0\\\",\\n    \\\"google-api-python-client~=2.161\\\",\\n    \\\"google-auth>=2.38.0,<3.0.0\\\",\\n    \\\"google-auth-oauthlib>=1.2.0,<2.0.0\\\",\\n    \\\"google-cloud-bigquery>=3.35,<4.0.0\\\",\\n    \\\"google-genai>=1.75.0,<2.0.0\\\",\\n    \\\"langchain-community>=0.4.1,<1.0.0\\\",\\n    \\\"langchain-core>=1.2.28,<2.0.0\\\",\\n    \\\"langchain-google-community~=5.0.0\\\",\\n    \\\"langchain-google-genai~=4.1.2\\\",\\n    \\\"requests>=2.32.0\\\",\\n]\\n\\n[project.urls]\\nHomepage = \\\"https://github.com/langflow-ai/langflow\\\"\\nDocumentation = \\\"https://docs.langflow.org/extensions\\\"\\nRepository = \\\"https://github.com/langflow-ai/langflow\\\"\\n\\n[project.entry-points.\\\"langflow.extensions\\\"]\\nlfx-google = \\\"lfx_google\\\"\\n\\n[build-system]\\nrequires = [\\\"hatchling==1.31.0\\\"]\\nbuild-backend = \\\"hatchling.build\\\"\\n\\n[tool.hatch.build.targets.wheel]\\npackages = [\\\"src/lfx_google\\\"]\\ninclude = [\\n    \\\"src/lfx_google/extension.json\\\",\\n    \\\"src/lfx_google/components/**/*.py\\\",\\n]\\n\\n[tool.hatch.build.targets.sdist]\\ninclude = [\\n    \\\"src/lfx_google\\\",\\n    \\\"extension.json\\\",\\n    \\\"README.md\\\",\\n    \\\"pyproject.toml\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/google/src/lfx_google/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a2d49e84c1acbb819854b2ae7f8f772b1672812dd2e7402444bf4c85bc425e5d\",\"content\":\"\\\"\\\"\\\"Google and Gemini components for Langflow.\\\"\\\"\\\"\\n\\nfrom lfx_google.components.google import (\\n    BigQueryExecutorComponent,\\n    GmailLoaderComponent,\\n    GoogleDriveComponent,\\n    GoogleDriveSearchComponent,\\n    GoogleGenerativeAIComponent,\\n    GoogleGenerativeAIEmbeddingsComponent,\\n    GoogleOAuthToken,\\n    GoogleSearchAPICore,\\n    GoogleSerperAPICore,\\n)\\n\\n__all__ = [\\n    \\\"BigQueryExecutorComponent\\\",\\n    \\\"GmailLoaderComponent\\\",\\n    \\\"GoogleDriveComponent\\\",\\n    \\\"GoogleDriveSearchComponent\\\",\\n    \\\"GoogleGenerativeAIComponent\\\",\\n    \\\"GoogleGenerativeAIEmbeddingsComponent\\\",\\n    \\\"GoogleOAuthToken\\\",\\n    \\\"GoogleSearchAPICore\\\",\\n    \\\"GoogleSerperAPICore\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/google/src/lfx_google/components/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8c63f802bf95b5d721bbc41ac61c0a093384a7d27f8d691f0b120169ab3654d3\",\"content\":\"\\\"\\\"\\\"Component packages shipped by lfx-google.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/google/src/lfx_google/components/google/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5b7efffd0e248c811e435d7fa516881446970400712fa13825c11436e11ea28e\",\"content\":\"from .gmail import GmailLoaderComponent\\nfrom .google_bq_sql_executor import BigQueryExecutorComponent\\nfrom .google_drive import GoogleDriveComponent\\nfrom .google_drive_search import GoogleDriveSearchComponent\\nfrom .google_generative_ai import GoogleGenerativeAIComponent\\nfrom .google_generative_ai_embeddings import GoogleGenerativeAIEmbeddingsComponent\\nfrom .google_oauth_token import GoogleOAuthToken\\nfrom .google_search_api_core import GoogleSearchAPICore\\nfrom .google_serper_api_core import GoogleSerperAPICore\\n\\n__all__ = [\\n    \\\"BigQueryExecutorComponent\\\",\\n    \\\"GmailLoaderComponent\\\",\\n    \\\"GoogleDriveComponent\\\",\\n    \\\"GoogleDriveSearchComponent\\\",\\n    \\\"GoogleGenerativeAIComponent\\\",\\n    \\\"GoogleGenerativeAIEmbeddingsComponent\\\",\\n    \\\"GoogleOAuthToken\\\",\\n    \\\"GoogleSearchAPICore\\\",\\n    \\\"GoogleSerperAPICore\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/google/src/lfx_google/components/google/gmail.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fa6a94489cea80f127aaf378e00a478714c45470fc682af6f88647feabc07e88\",\"content\":\"import base64\\nimport json\\nimport re\\nfrom collections.abc import Iterator\\nfrom json.decoder import JSONDecodeError\\nfrom typing import Any\\n\\nfrom google.auth.exceptions import RefreshError\\nfrom google.oauth2.credentials import Credentials\\nfrom googleapiclient.discovery import build\\nfrom langchain_core.chat_sessions import ChatSession\\nfrom langchain_core.messages import HumanMessage\\nfrom langchain_google_community.gmail.loader import GMailLoader\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.inputs.inputs import MessageTextInput\\nfrom lfx.io import SecretStrInput\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.data import Data\\nfrom lfx.template.field.base import Output\\n\\n\\nclass GmailLoaderComponent(Component):\\n    display_name = \\\"Gmail Loader\\\"\\n    description = \\\"Loads emails from Gmail using provided credentials.\\\"\\n    icon = \\\"Google\\\"\\n    legacy: bool = True\\n    replacement = [\\\"composio.ComposioGmailAPIComponent\\\"]\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"json_string\\\",\\n            display_name=\\\"JSON String of the Service Account Token\\\",\\n            info=\\\"JSON string containing OAuth 2.0 access token information for service account access\\\",\\n            required=True,\\n            value=\\\"\\\"\\\"{\\n                \\\"account\\\": \\\"\\\",\\n                \\\"client_id\\\": \\\"\\\",\\n                \\\"client_secret\\\": \\\"\\\",\\n                \\\"expiry\\\": \\\"\\\",\\n                \\\"refresh_token\\\": \\\"\\\",\\n                \\\"scopes\\\": [\\n                    \\\"https://www.googleapis.com/auth/gmail.readonly\\\",\\n                ],\\n                \\\"token\\\": \\\"\\\",\\n                \\\"token_uri\\\": \\\"https://oauth2.googleapis.com/token\\\",\\n                \\\"universe_domain\\\": \\\"googleapis.com\\\"\\n            }\\\"\\\"\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"label_ids\\\",\\n            display_name=\\\"Label IDs\\\",\\n            info=\\\"Comma-separated list of label IDs to filter emails.\\\",\\n            required=True,\\n            value=\\\"INBOX,SENT,UNREAD,IMPORTANT\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"max_results\\\",\\n            display_name=\\\"Max Results\\\",\\n            info=\\\"Maximum number of emails to load.\\\",\\n            required=True,\\n            value=\\\"10\\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"JSON\\\", name=\\\"data\\\", method=\\\"load_emails\\\"),\\n    ]\\n\\n    def load_emails(self) -> Data:\\n        class CustomGMailLoader(GMailLoader):\\n            def __init__(\\n                self, creds: Any, *, n: int = 100, label_ids: list[str] | None = None, raise_error: bool = False\\n            ) -> None:\\n                super().__init__(creds, n, raise_error)\\n                self.label_ids = label_ids if label_ids is not None else [\\\"SENT\\\"]\\n\\n            def clean_message_content(self, message):\\n                # Remove URLs\\n                message = re.sub(r\\\"http\\\\S+|www\\\\S+|https\\\\S+\\\", \\\"\\\", message, flags=re.MULTILINE)\\n\\n                # Remove email addresses\\n                message = re.sub(r\\\"\\\\S+@\\\\S+\\\", \\\"\\\", message)\\n\\n                # Remove special characters and excessive whitespace\\n                message = re.sub(r\\\"[^A-Za-z0-9\\\\s]+\\\", \\\" \\\", message)\\n                message = re.sub(r\\\"\\\\s{2,}\\\", \\\" \\\", message)\\n\\n                # Trim leading and trailing whitespace\\n                return message.strip()\\n\\n            def _extract_email_content(self, msg: Any) -> HumanMessage:\\n                from_email = None\\n                for values in msg[\\\"payload\\\"][\\\"headers\\\"]:\\n                    name = values[\\\"name\\\"]\\n                    if name == \\\"From\\\":\\n                        from_email = values[\\\"value\\\"]\\n                if from_email is None:\\n                    msg = \\\"From email not found.\\\"\\n                    raise ValueError(msg)\\n\\n                parts = msg[\\\"payload\\\"][\\\"parts\\\"] if \\\"parts\\\" in msg[\\\"payload\\\"] else [msg[\\\"payload\\\"]]\\n\\n                for part in parts:\\n                    if part[\\\"mimeType\\\"] == \\\"text/plain\\\":\\n                        data = part[\\\"body\\\"][\\\"data\\\"]\\n                        data = base64.urlsafe_b64decode(data).decode(\\\"utf-8\\\")\\n                        pattern = re.compile(r\\\"\\\\r\\\\nOn .+(\\\\r\\\\n)*wrote:\\\\r\\\\n\\\")\\n                        newest_response = re.split(pattern, data)[0]\\n                        return HumanMessage(\\n                            content=self.clean_message_content(newest_response),\\n                            additional_kwargs={\\\"sender\\\": from_email},\\n                        )\\n                msg = \\\"No plain text part found in the email.\\\"\\n                raise ValueError(msg)\\n\\n            def _get_message_data(self, service: Any, message: Any) -> ChatSession:\\n                msg = service.users().messages().get(userId=\\\"me\\\", id=message[\\\"id\\\"]).execute()\\n                message_content = self._extract_email_content(msg)\\n\\n                in_reply_to = None\\n                email_data = msg[\\\"payload\\\"][\\\"headers\\\"]\\n                for values in email_data:\\n                    name = values[\\\"name\\\"]\\n                    if name == \\\"In-Reply-To\\\":\\n                        in_reply_to = values[\\\"value\\\"]\\n\\n                thread_id = msg[\\\"threadId\\\"]\\n\\n                if in_reply_to:\\n                    thread = service.users().threads().get(userId=\\\"me\\\", id=thread_id).execute()\\n                    messages = thread[\\\"messages\\\"]\\n\\n                    response_email = None\\n                    for _message in messages:\\n                        email_data = _message[\\\"payload\\\"][\\\"headers\\\"]\\n                        for values in email_data:\\n                            if values[\\\"name\\\"] == \\\"Message-ID\\\":\\n                                message_id = values[\\\"value\\\"]\\n                                if message_id == in_reply_to:\\n                                    response_email = _message\\n                    if response_email is None:\\n                        msg = \\\"Response email not found in the thread.\\\"\\n                        raise ValueError(msg)\\n                    starter_content = self._extract_email_content(response_email)\\n                    return ChatSession(messages=[starter_content, message_content])\\n                return ChatSession(messages=[message_content])\\n\\n            def lazy_load(self) -> Iterator[ChatSession]:\\n                service = build(\\\"gmail\\\", \\\"v1\\\", credentials=self.creds)\\n                results = (\\n                    service.users().messages().list(userId=\\\"me\\\", labelIds=self.label_ids, maxResults=self.n).execute()\\n                )\\n                messages = results.get(\\\"messages\\\", [])\\n                if not messages:\\n                    logger.warning(\\\"No messages found with the specified labels.\\\")\\n                for message in messages:\\n                    try:\\n                        yield self._get_message_data(service, message)\\n                    except Exception:\\n                        if self.raise_error:\\n                            raise\\n                        else:\\n                            logger.exception(f\\\"Error processing message {message['id']}\\\")\\n\\n        json_string = self.json_string\\n        label_ids = self.label_ids.split(\\\",\\\") if self.label_ids else [\\\"INBOX\\\"]\\n        try:\\n            max_results = int(self.max_results) if self.max_results else 100\\n        except (TypeError, ValueError) as e:\\n            msg = f\\\"Invalid max_results value: {self.max_results}\\\"\\n            raise ValueError(msg) from e\\n\\n        # Load the token information from the JSON string\\n        try:\\n            token_info = json.loads(json_string)\\n        except JSONDecodeError as e:\\n            msg = \\\"Invalid JSON string\\\"\\n            raise ValueError(msg) from e\\n\\n        creds = Credentials.from_authorized_user_info(token_info)\\n\\n        # Initialize the custom loader with the provided credentials\\n        loader = CustomGMailLoader(creds=creds, n=max_results, label_ids=label_ids)\\n\\n        try:\\n            docs = loader.load()\\n        except RefreshError as e:\\n            msg = \\\"Authentication error: Unable to refresh authentication token. Please try to reauthenticate.\\\"\\n            raise ValueError(msg) from e\\n        except Exception as e:\\n            msg = f\\\"Error loading documents: {e}\\\"\\n            raise ValueError(msg) from e\\n\\n        # Return the loaded documents\\n        self.status = docs\\n        return Data(data={\\\"text\\\": docs})\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/google/src/lfx_google/components/google/google_bq_sql_executor.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0c7d1aaa430f01bf5115b14f7d047ed713a0e025af3437d6b35d1fb61fb988ea\",\"content\":\"import json\\nimport re\\nfrom pathlib import Path\\n\\nfrom google.auth.exceptions import RefreshError\\nfrom google.cloud import bigquery\\nfrom google.oauth2.service_account import Credentials\\nfrom lfx.custom import Component\\nfrom lfx.io import BoolInput, FileInput, MessageTextInput, Output\\nfrom lfx.schema.dataframe import DataFrame\\n\\n\\nclass BigQueryExecutorComponent(Component):\\n    display_name = \\\"BigQuery\\\"\\n    description = \\\"Execute SQL queries on Google BigQuery.\\\"\\n    name = \\\"BigQueryExecutor\\\"\\n    icon = \\\"Google\\\"\\n    beta: bool = True\\n\\n    inputs = [\\n        FileInput(\\n            name=\\\"service_account_json_file\\\",\\n            display_name=\\\"Upload Service Account JSON\\\",\\n            info=\\\"Upload the JSON file containing Google Cloud service account credentials.\\\",\\n            file_types=[\\\"json\\\"],\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"query\\\",\\n            display_name=\\\"SQL Query\\\",\\n            info=\\\"The SQL query to execute on BigQuery.\\\",\\n            required=True,\\n            tool_mode=True,\\n        ),\\n        BoolInput(\\n            name=\\\"clean_query\\\",\\n            display_name=\\\"Clean Query\\\",\\n            info=\\\"When enabled, this will automatically clean up your SQL query.\\\",\\n            value=False,\\n            advanced=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Query Results\\\", name=\\\"query_results\\\", method=\\\"execute_sql\\\"),\\n    ]\\n\\n    def _clean_sql_query(self, query: str) -> str:\\n        \\\"\\\"\\\"Clean SQL query by removing surrounding quotes and whitespace.\\n\\n        Also extracts SQL statements from text that might contain other content.\\n\\n        Args:\\n            query: The SQL query to clean\\n\\n        Returns:\\n            The cleaned SQL query\\n        \\\"\\\"\\\"\\n        # First, try to extract SQL from code blocks\\n        sql_pattern = r\\\"```(?:sql)?\\\\s*([\\\\s\\\\S]*?)\\\\s*```\\\"\\n        sql_matches = re.findall(sql_pattern, query, re.IGNORECASE)\\n\\n        if sql_matches:\\n            # If we found SQL in code blocks, use the first match\\n            query = sql_matches[0]\\n        else:\\n            # If no code block, try to find SQL statements\\n            # Look for common SQL keywords at the start of lines\\n            sql_keywords = r\\\"(?i)(SELECT|INSERT|UPDATE|DELETE|CREATE|ALTER|DROP|WITH|MERGE)\\\"\\n            lines = query.split(\\\"\\\\n\\\")\\n            sql_lines = []\\n            in_sql = False\\n\\n            for _line in lines:\\n                line = _line.strip()\\n                if re.match(sql_keywords, line):\\n                    in_sql = True\\n                if in_sql:\\n                    sql_lines.append(line)\\n                if line.endswith(\\\";\\\"):\\n                    in_sql = False\\n\\n            if sql_lines:\\n                query = \\\"\\\\n\\\".join(sql_lines)\\n\\n        # Remove any backticks that might be at the start or end\\n        query = query.strip(\\\"`\\\")\\n\\n        # Then remove surrounding quotes (single or double) if they exist\\n        query = query.strip()\\n        if (query.startswith('\\\"') and query.endswith('\\\"')) or (query.startswith(\\\"'\\\") and query.endswith(\\\"'\\\")):\\n            query = query[1:-1]\\n\\n        # Finally, clean up any remaining whitespace and ensure no backticks remain\\n        query = query.strip()\\n        # Remove any remaining backticks, but preserve them if they're part of a table/column name\\n        # This regex will remove backticks that are not part of a valid identifier\\n        return re.sub(r\\\"`(?![a-zA-Z0-9_])|(?<![a-zA-Z0-9_])`\\\", \\\"\\\", query)\\n\\n    def execute_sql(self) -> DataFrame:\\n        try:\\n            # First try to read the file\\n            try:\\n                service_account_path = Path(self.service_account_json_file)\\n                with service_account_path.open() as f:\\n                    credentials_json = json.load(f)\\n                    project_id = credentials_json.get(\\\"project_id\\\")\\n                    if not project_id:\\n                        msg = \\\"No project_id found in service account credentials file.\\\"\\n                        raise ValueError(msg)\\n            except FileNotFoundError as e:\\n                msg = f\\\"Service account file not found: {e}\\\"\\n                raise ValueError(msg) from e\\n            except json.JSONDecodeError as e:\\n                msg = \\\"Invalid JSON string for service account credentials\\\"\\n                raise ValueError(msg) from e\\n\\n            # Then try to load credentials\\n            try:\\n                credentials = Credentials.from_service_account_file(self.service_account_json_file)\\n            except Exception as e:\\n                msg = f\\\"Error loading service account credentials: {e}\\\"\\n                raise ValueError(msg) from e\\n\\n        except ValueError:\\n            raise\\n        except Exception as e:\\n            msg = f\\\"Error executing BigQuery SQL query: {e}\\\"\\n            raise ValueError(msg) from e\\n\\n        try:\\n            client = bigquery.Client(credentials=credentials, project=project_id)\\n\\n            # Check for empty or whitespace-only query before cleaning\\n            if not str(self.query).strip():\\n                msg = \\\"No valid SQL query found in input text.\\\"\\n                raise ValueError(msg)\\n\\n            # Always clean the query if it contains code block markers, quotes, or if clean_query is enabled\\n            if \\\"```\\\" in str(self.query) or '\\\"' in str(self.query) or \\\"'\\\" in str(self.query) or self.clean_query:\\n                sql_query = self._clean_sql_query(str(self.query))\\n            else:\\n                sql_query = str(self.query).strip()  # At minimum, strip whitespace\\n\\n            query_job = client.query(sql_query)\\n            results = query_job.result()\\n            output_dict = [dict(row) for row in results]\\n\\n        except RefreshError as e:\\n            msg = \\\"Authentication error: Unable to refresh authentication token. Please try to reauthenticate.\\\"\\n            raise ValueError(msg) from e\\n        except Exception as e:\\n            msg = f\\\"Error executing BigQuery SQL query: {e}\\\"\\n            raise ValueError(msg) from e\\n\\n        return DataFrame(output_dict)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/google/src/lfx_google/components/google/google_drive.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"06907c85740e2bce7c4b1f3053e1a4a08ce420afb9fad3fccabba0d2509590e1\",\"content\":\"import json\\nfrom json.decoder import JSONDecodeError\\n\\nfrom google.auth.exceptions import RefreshError\\nfrom google.oauth2.credentials import Credentials\\nfrom langchain_google_community import GoogleDriveLoader\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.helpers.data import docs_to_data\\nfrom lfx.inputs.inputs import MessageTextInput\\nfrom lfx.io import SecretStrInput\\nfrom lfx.schema.data import Data\\nfrom lfx.template.field.base import Output\\n\\n\\nclass GoogleDriveComponent(Component):\\n    display_name = \\\"Google Drive Loader\\\"\\n    description = \\\"Loads documents from Google Drive using provided credentials.\\\"\\n    icon = \\\"Google\\\"\\n    legacy: bool = True\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"json_string\\\",\\n            display_name=\\\"JSON String of the Service Account Token\\\",\\n            info=\\\"JSON string containing OAuth 2.0 access token information for service account access\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"document_id\\\", display_name=\\\"Document ID\\\", info=\\\"Single Google Drive document ID\\\", required=True\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Loaded Documents\\\", name=\\\"docs\\\", method=\\\"load_documents\\\"),\\n    ]\\n\\n    def load_documents(self) -> Data:\\n        class CustomGoogleDriveLoader(GoogleDriveLoader):\\n            creds: Credentials | None = None\\n            \\\"\\\"\\\"Credentials object to be passed directly.\\\"\\\"\\\"\\n\\n            def _load_credentials(self):\\n                \\\"\\\"\\\"Load credentials from the provided creds attribute or fallback to the original method.\\\"\\\"\\\"\\n                if self.creds:\\n                    return self.creds\\n                msg = \\\"No credentials provided.\\\"\\n                raise ValueError(msg)\\n\\n            def _load_documents_from_ids(self):\\n                # This component loads one Google Doc. Preserve that path instead of\\n                # the 5.x loader's MIME discovery via an unsupported files.list id query.\\n                return [self._load_document_from_id(document_id) for document_id in self.document_ids]\\n\\n            class Config:\\n                arbitrary_types_allowed = True\\n\\n        json_string = self.json_string\\n\\n        document_ids = [self.document_id]\\n        if len(document_ids) != 1:\\n            msg = \\\"Expected a single document ID\\\"\\n            raise ValueError(msg)\\n\\n        # TODO: Add validation to check if the document ID is valid\\n\\n        # Load the token information from the JSON string\\n        try:\\n            token_info = json.loads(json_string)\\n        except JSONDecodeError as e:\\n            msg = \\\"Invalid JSON string\\\"\\n            raise ValueError(msg) from e\\n\\n        # Initialize the custom loader with the provided credentials and document IDs\\n        loader = CustomGoogleDriveLoader(\\n            creds=Credentials.from_authorized_user_info(token_info), document_ids=document_ids\\n        )\\n\\n        # Load the documents\\n        try:\\n            docs = loader.load()\\n        # catch google.auth.exceptions.RefreshError\\n        except RefreshError as e:\\n            msg = \\\"Authentication error: Unable to refresh authentication token. Please try to reauthenticate.\\\"\\n            raise ValueError(msg) from e\\n        except Exception as e:\\n            msg = f\\\"Error loading documents: {e}\\\"\\n            raise ValueError(msg) from e\\n\\n        if len(docs) != 1:\\n            msg = \\\"Expected a single document to be loaded.\\\"\\n            raise ValueError(msg)\\n\\n        data = docs_to_data(docs)\\n        # Return the loaded documents\\n        self.status = data\\n        return Data(data={\\\"text\\\": data})\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/google/src/lfx_google/components/google/google_drive_search.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3e15b823152c2928559106961ba5bf4b23002654b799ff60f937fa4bb64b666\",\"content\":\"import json\\nfrom json.decoder import JSONDecodeError\\n\\nfrom google.auth.exceptions import RefreshError\\nfrom google.oauth2.credentials import Credentials\\nfrom googleapiclient.discovery import build\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.inputs.inputs import DropdownInput, MessageTextInput\\nfrom lfx.io import SecretStrInput\\nfrom lfx.schema.data import Data\\nfrom lfx.template.field.base import Output\\n\\n\\nclass GoogleDriveSearchComponent(Component):\\n    display_name = \\\"Google Drive Search\\\"\\n    description = \\\"Searches Google Drive files using provided credentials and query parameters.\\\"\\n    icon = \\\"Google\\\"\\n    legacy: bool = True\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"token_string\\\",\\n            display_name=\\\"Token String\\\",\\n            info=\\\"JSON string containing OAuth 2.0 access token information for service account access\\\",\\n            required=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"query_item\\\",\\n            display_name=\\\"Query Item\\\",\\n            options=[\\n                \\\"name\\\",\\n                \\\"fullText\\\",\\n                \\\"mimeType\\\",\\n                \\\"modifiedTime\\\",\\n                \\\"viewedByMeTime\\\",\\n                \\\"trashed\\\",\\n                \\\"starred\\\",\\n                \\\"parents\\\",\\n                \\\"owners\\\",\\n                \\\"writers\\\",\\n                \\\"readers\\\",\\n                \\\"sharedWithMe\\\",\\n                \\\"createdTime\\\",\\n                \\\"properties\\\",\\n                \\\"appProperties\\\",\\n                \\\"visibility\\\",\\n                \\\"shortcutDetails.targetId\\\",\\n            ],\\n            info=\\\"The field to query.\\\",\\n            required=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"valid_operator\\\",\\n            display_name=\\\"Valid Operator\\\",\\n            options=[\\\"contains\\\", \\\"=\\\", \\\"!=\\\", \\\"<=\\\", \\\"<\\\", \\\">\\\", \\\">=\\\", \\\"in\\\", \\\"has\\\"],\\n            info=\\\"Operator to use in the query.\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"search_term\\\",\\n            display_name=\\\"Search Term\\\",\\n            info=\\\"The value to search for in the specified query item.\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"query_string\\\",\\n            display_name=\\\"Query String\\\",\\n            info=\\\"The query string used for searching. You can edit this manually.\\\",\\n            value=\\\"\\\",  # This will be updated with the generated query string\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Document URLs\\\", name=\\\"doc_urls\\\", method=\\\"search_doc_urls\\\"),\\n        Output(display_name=\\\"Document IDs\\\", name=\\\"doc_ids\\\", method=\\\"search_doc_ids\\\"),\\n        Output(display_name=\\\"Document Titles\\\", name=\\\"doc_titles\\\", method=\\\"search_doc_titles\\\"),\\n        Output(display_name=\\\"JSON\\\", name=\\\"Data\\\", method=\\\"search_data\\\"),\\n    ]\\n\\n    def generate_query_string(self) -> str:\\n        query_item = self.query_item\\n        valid_operator = self.valid_operator\\n        search_term = self.search_term\\n\\n        # Construct the query string\\n        query = f\\\"{query_item} {valid_operator} '{search_term}'\\\"\\n\\n        # Update the editable query string input with the generated query\\n        self.query_string = query\\n\\n        return query\\n\\n    def on_inputs_changed(self) -> None:\\n        # Automatically regenerate the query string when inputs change\\n        self.generate_query_string()\\n\\n    def generate_file_url(self, file_id: str, mime_type: str) -> str:\\n        \\\"\\\"\\\"Generates the appropriate Google Drive URL for a file based on its MIME type.\\\"\\\"\\\"\\n        return {\\n            \\\"application/vnd.google-apps.document\\\": f\\\"https://docs.google.com/document/d/{file_id}/edit\\\",\\n            \\\"application/vnd.google-apps.spreadsheet\\\": f\\\"https://docs.google.com/spreadsheets/d/{file_id}/edit\\\",\\n            \\\"application/vnd.google-apps.presentation\\\": f\\\"https://docs.google.com/presentation/d/{file_id}/edit\\\",\\n            \\\"application/vnd.google-apps.drawing\\\": f\\\"https://docs.google.com/drawings/d/{file_id}/edit\\\",\\n            \\\"application/pdf\\\": f\\\"https://drive.google.com/file/d/{file_id}/view?usp=drivesdk\\\",\\n        }.get(mime_type, f\\\"https://drive.google.com/file/d/{file_id}/view?usp=drivesdk\\\")\\n\\n    def search_files(self) -> dict:\\n        # Load the token information from the JSON string\\n        try:\\n            token_info = json.loads(self.token_string)\\n        except JSONDecodeError as e:\\n            msg = \\\"Invalid JSON string\\\"\\n            raise ValueError(msg) from e\\n\\n        # Use the query string from the input (which might have been edited by the user)\\n        query = self.query_string or self.generate_query_string()\\n\\n        try:\\n            creds = Credentials.from_authorized_user_info(token_info)\\n            service = build(\\\"drive\\\", \\\"v3\\\", credentials=creds)\\n            results = (\\n                service.files().list(q=query, pageSize=5, fields=\\\"nextPageToken, files(id, name, mimeType)\\\").execute()\\n            )\\n        except RefreshError as e:\\n            msg = \\\"Authentication error: Unable to refresh authentication token. Please try to reauthenticate.\\\"\\n            raise ValueError(msg) from e\\n        except Exception as e:\\n            msg = f\\\"Error searching Google Drive: {e}\\\"\\n            raise ValueError(msg) from e\\n\\n        items = results.get(\\\"files\\\", [])\\n\\n        doc_urls = []\\n        doc_ids = []\\n        doc_titles_urls = []\\n        doc_titles = []\\n\\n        if items:\\n            for item in items:\\n                # Directly use the file ID, title, and MIME type to generate the URL\\n                file_id = item[\\\"id\\\"]\\n                file_title = item[\\\"name\\\"]\\n                mime_type = item[\\\"mimeType\\\"]\\n                file_url = self.generate_file_url(file_id, mime_type)\\n\\n                # Store the URL, ID, and title+URL in their respective lists\\n                doc_urls.append(file_url)\\n                doc_ids.append(file_id)\\n                doc_titles.append(file_title)\\n                doc_titles_urls.append({\\\"title\\\": file_title, \\\"url\\\": file_url})\\n\\n        return {\\\"doc_urls\\\": doc_urls, \\\"doc_ids\\\": doc_ids, \\\"doc_titles_urls\\\": doc_titles_urls, \\\"doc_titles\\\": doc_titles}\\n\\n    def search_doc_ids(self) -> list[str]:\\n        return self.search_files()[\\\"doc_ids\\\"]\\n\\n    def search_doc_urls(self) -> list[str]:\\n        return self.search_files()[\\\"doc_urls\\\"]\\n\\n    def search_doc_titles(self) -> list[str]:\\n        return self.search_files()[\\\"doc_titles\\\"]\\n\\n    def search_data(self) -> Data:\\n        return Data(data={\\\"text\\\": self.search_files()[\\\"doc_titles_urls\\\"]})\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/google/src/lfx_google/components/google/google_generative_ai.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f28309bed516299fadb606a00f5ad91103b0b3d7191d432a0caf7deab4ced32a\",\"content\":\"from typing import Any\\n\\nimport requests\\nfrom google import genai\\nfrom lfx.base.models.google_generative_ai_constants import GOOGLE_GENERATIVE_AI_MODELS\\nfrom lfx.base.models.google_generative_ai_model import ChatGoogleGenerativeAIFixed\\nfrom lfx.base.models.model import LCModelComponent\\nfrom lfx.field_typing import LanguageModel\\nfrom lfx.field_typing.range_spec import RangeSpec\\nfrom lfx.inputs.inputs import BoolInput, DropdownInput, FloatInput, IntInput, SecretStrInput, SliderInput\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.dotdict import dotdict\\nfrom pydantic.v1 import SecretStr\\n\\n\\nclass GoogleGenerativeAIComponent(LCModelComponent):\\n    display_name = \\\"Google Generative AI\\\"\\n    description = \\\"Generate text using Google Generative AI.\\\"\\n    icon = \\\"GoogleGenerativeAI\\\"\\n    name = \\\"GoogleGenerativeAIModel\\\"\\n\\n    inputs = [\\n        *LCModelComponent.get_base_inputs(),\\n        IntInput(\\n            name=\\\"max_output_tokens\\\", display_name=\\\"Max Output Tokens\\\", info=\\\"The maximum number of tokens to generate.\\\"\\n        ),\\n        DropdownInput(\\n            name=\\\"model_name\\\",\\n            display_name=\\\"Model\\\",\\n            info=\\\"The name of the model to use.\\\",\\n            options=GOOGLE_GENERATIVE_AI_MODELS,\\n            value=\\\"gemini-2.5-flash\\\",\\n            refresh_button=True,\\n            combobox=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"Google API Key\\\",\\n            info=\\\"The Google API Key to use for the Google Generative AI.\\\",\\n            required=True,\\n            real_time_refresh=True,\\n        ),\\n        FloatInput(\\n            name=\\\"top_p\\\",\\n            display_name=\\\"Top P\\\",\\n            info=\\\"The maximum cumulative probability of tokens to consider when sampling.\\\",\\n            advanced=True,\\n        ),\\n        SliderInput(\\n            name=\\\"temperature\\\",\\n            display_name=\\\"Temperature\\\",\\n            value=0.1,\\n            range_spec=RangeSpec(min=0, max=1, step=0.01),\\n            info=\\\"Controls randomness. Lower values are more deterministic, higher values are more creative.\\\",\\n        ),\\n        IntInput(\\n            name=\\\"n\\\",\\n            display_name=\\\"N\\\",\\n            info=\\\"Number of chat completions to generate for each prompt. \\\"\\n            \\\"Note that the API may not return the full n completions if duplicates are generated.\\\",\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"top_k\\\",\\n            display_name=\\\"Top K\\\",\\n            info=\\\"Decode using top-k sampling: consider the set of top_k most probable tokens. Must be positive.\\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\\"tool_model_enabled\\\",\\n            display_name=\\\"Tool Model Enabled\\\",\\n            info=\\\"Whether to use the tool model.\\\",\\n            value=False,\\n        ),\\n    ]\\n\\n    def build_model(self) -> LanguageModel:  # type: ignore[type-var]\\n        google_api_key = self.api_key\\n        model = self.model_name\\n        max_output_tokens = self.max_output_tokens\\n        temperature = self.temperature\\n        top_k = self.top_k\\n        top_p = self.top_p\\n        n = self.n\\n\\n        # Use modified ChatGoogleGenerativeAIFixed class for multiple function support\\n        # TODO: Potentially remove when fixed upstream\\n        return ChatGoogleGenerativeAIFixed(\\n            model=model,\\n            max_output_tokens=max_output_tokens or None,\\n            temperature=temperature,\\n            top_k=top_k or None,\\n            top_p=top_p or None,\\n            n=n or 1,\\n            google_api_key=SecretStr(google_api_key).get_secret_value(),\\n        )\\n\\n    def get_models(self, *, tool_model_enabled: bool | None = None) -> list[str]:\\n        try:\\n            with genai.Client(api_key=self.api_key) as client:\\n                model_ids = [\\n                    model.name.removeprefix(\\\"models/\\\")\\n                    for model in client.models.list()\\n                    if model.name and \\\"generateContent\\\" in (model.supported_actions or [])\\n                ]\\n            model_ids.sort(reverse=True)\\n        except (genai.errors.APIError, ValueError) as e:\\n            logger.exception(f\\\"Error getting model names: {e}\\\")\\n            model_ids = GOOGLE_GENERATIVE_AI_MODELS\\n        if tool_model_enabled:\\n            try:\\n                from langchain_google_genai.chat_models import ChatGoogleGenerativeAI\\n            except ImportError as e:\\n                msg = \\\"langchain_google_genai is not installed.\\\"\\n                raise ImportError(msg) from e\\n            model_ids = [\\n                model\\n                for model in model_ids\\n                if self.supports_tool_calling(ChatGoogleGenerativeAI(model=model, google_api_key=self.api_key))\\n            ]\\n        return model_ids\\n\\n    def update_build_config(self, build_config: dotdict, field_value: Any, field_name: str | None = None):\\n        if field_name in {\\\"base_url\\\", \\\"model_name\\\", \\\"tool_model_enabled\\\", \\\"api_key\\\"} and field_value:\\n            try:\\n                if len(self.api_key) == 0:\\n                    ids = GOOGLE_GENERATIVE_AI_MODELS\\n                else:\\n                    try:\\n                        ids = self.get_models(tool_model_enabled=self.tool_model_enabled)\\n                    except (ImportError, ValueError, requests.exceptions.RequestException) as e:\\n                        logger.exception(f\\\"Error getting model names: {e}\\\")\\n                        ids = GOOGLE_GENERATIVE_AI_MODELS\\n                build_config.setdefault(\\\"model_name\\\", {})\\n                build_config[\\\"model_name\\\"][\\\"options\\\"] = ids\\n                if ids:\\n                    build_config[\\\"model_name\\\"].setdefault(\\\"value\\\", ids[0])\\n                else:\\n                    build_config[\\\"model_name\\\"].pop(\\\"value\\\", None)\\n            except Exception as e:\\n                msg = f\\\"Error getting model names: {e}\\\"\\n                raise ValueError(msg) from e\\n        return build_config\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/google/src/lfx_google/components/google/google_generative_ai_embeddings.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"622b6a1e00135fe6c3a9a59b93cdb9b28a33d9f8e1ad3dd4fb4d0c5e8a156b88\",\"content\":\"from langchain_core.embeddings import Embeddings\\nfrom langchain_google_genai import GoogleGenerativeAIEmbeddings\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import MessageTextInput, Output, SecretStrInput\\n\\n\\nclass GoogleGenerativeAIEmbeddingsComponent(Component):\\n    model_provider_id = \\\"google-generative-ai\\\"\\n    display_name = \\\"Google Generative AI Embeddings\\\"\\n    description = (\\n        \\\"Connect to Google's generative AI embeddings service using the GoogleGenerativeAIEmbeddings class, \\\"\\n        \\\"found in the langchain-google-genai package.\\\"\\n    )\\n    documentation: str = \\\"https://python.langchain.com/v0.2/docs/integrations/text_embedding/google_generative_ai/\\\"\\n    icon = \\\"GoogleGenerativeAI\\\"\\n    name = \\\"Google Generative AI Embeddings\\\"\\n\\n    inputs = [\\n        SecretStrInput(name=\\\"api_key\\\", display_name=\\\"Google Generative AI API Key\\\", required=True),\\n        MessageTextInput(name=\\\"model_name\\\", display_name=\\\"Model Name\\\", value=\\\"models/text-embedding-004\\\"),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Embeddings\\\", name=\\\"embeddings\\\", method=\\\"build_embeddings\\\"),\\n    ]\\n\\n    async def _additional_model_provider_policy_ids(self, purpose, parameters=None) -> tuple[str, ...]:\\n        \\\"\\\"\\\"Authorize this legacy embedding component as Google before credentials load.\\\"\\\"\\\"\\n        _ = purpose, parameters\\n        return (self.model_provider_id,)\\n\\n    def build_embeddings(self) -> Embeddings:\\n        if not self.api_key:\\n            msg = \\\"API Key is required\\\"\\n            raise ValueError(msg)\\n\\n        return GoogleGenerativeAIEmbeddings(\\n            model=self.model_name,\\n            google_api_key=self.api_key,\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/google/src/lfx_google/components/google/google_oauth_token.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"88d4323e6aa01df7713ed5f777c1e0578b8fbc052ca583a1768201e1620dc4e4\",\"content\":\"import json\\nimport re\\n\\nfrom google_auth_oauthlib.flow import InstalledAppFlow\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import FileInput, MultilineInput, Output\\nfrom lfx.schema.data import Data\\n\\n_SCOPE = (\\n    r\\\"(?:https://www\\\\.googleapis\\\\.com/auth/[\\\\w.\\\\-]+\\\"\\n    r\\\"|mail\\\\.google\\\\.com/\\\"\\n    r\\\"|www\\\\.google\\\\.com/calendar/feeds\\\"\\n    r\\\"|www\\\\.google\\\\.com/m8/feeds)\\\"\\n)\\n_SCOPE_LIST_PATTERN = re.compile(rf\\\"{_SCOPE}(?:,\\\\s*{_SCOPE})*\\\")\\n_OAUTH_CALLBACK_TIMEOUT_SECONDS = 300\\n\\n\\nclass GoogleOAuthToken(Component):\\n    display_name = \\\"Google OAuth Token\\\"\\n    description = \\\"Generates a JSON string with your Google OAuth token.\\\"\\n    documentation: str = \\\"https://developers.google.com/identity/protocols/oauth2/web-server?hl=pt-br#python_1\\\"\\n    icon = \\\"Google\\\"\\n    name = \\\"GoogleOAuthToken\\\"\\n    legacy: bool = True\\n    inputs = [\\n        MultilineInput(\\n            name=\\\"scopes\\\",\\n            display_name=\\\"Scopes\\\",\\n            info=\\\"Input scopes for your application.\\\",\\n            required=True,\\n        ),\\n        FileInput(\\n            name=\\\"oauth_credentials\\\",\\n            display_name=\\\"Credentials File\\\",\\n            info=\\\"Input OAuth Credentials file (e.g. credentials.json).\\\",\\n            file_types=[\\\"json\\\"],\\n            required=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Output\\\", name=\\\"output\\\", method=\\\"build_output\\\"),\\n    ]\\n\\n    def validate_scopes(self, scopes: str) -> None:\\n        if _SCOPE_LIST_PATTERN.fullmatch(scopes) is None:\\n            error_message = \\\"Invalid scope format.\\\"\\n            raise ValueError(error_message)\\n\\n    def build_output(self) -> Data:\\n        self.validate_scopes(self.scopes)\\n\\n        user_scopes = [scope.strip() for scope in self.scopes.split(\\\",\\\")]\\n        if self.scopes:\\n            scopes = user_scopes\\n        else:\\n            error_message = \\\"Incorrect scope, check the scopes field.\\\"\\n            raise ValueError(error_message)\\n\\n        if not self.oauth_credentials:\\n            error_message = \\\"OAuth 2.0 Credentials file not provided.\\\"\\n            raise ValueError(error_message)\\n\\n        try:\\n            flow = InstalledAppFlow.from_client_secrets_file(self.oauth_credentials, scopes)\\n            creds = flow.run_local_server(port=0, timeout_seconds=_OAUTH_CALLBACK_TIMEOUT_SECONDS)\\n            creds_json = json.loads(creds.to_json())\\n        except Exception as e:\\n            msg = f\\\"OAuth authorization failed: {e}\\\"\\n            raise ValueError(msg) from e\\n\\n        return Data(data=creds_json)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/google/src/lfx_google/components/google/google_search_api_core.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0e21e12bdf1fc124e0e808bf5b5853c41b9158ff04df88a858aeda7c27f56d98\",\"content\":\"from langchain_google_community import GoogleSearchAPIWrapper\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import IntInput, MultilineInput, Output, SecretStrInput\\nfrom lfx.schema.dataframe import DataFrame\\n\\n\\nclass GoogleSearchAPICore(Component):\\n    display_name = \\\"Google Search API\\\"\\n    description = \\\"Call Google Search API and return results as a DataFrame.\\\"\\n    icon = \\\"Google\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"google_api_key\\\",\\n            display_name=\\\"Google API Key\\\",\\n            required=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"google_cse_id\\\",\\n            display_name=\\\"Google CSE ID\\\",\\n            required=True,\\n        ),\\n        MultilineInput(\\n            name=\\\"input_value\\\",\\n            display_name=\\\"Input\\\",\\n            tool_mode=True,\\n        ),\\n        IntInput(\\n            name=\\\"k\\\",\\n            display_name=\\\"Number of results\\\",\\n            value=4,\\n            required=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(\\n            display_name=\\\"Results\\\",\\n            name=\\\"results\\\",\\n            type_=DataFrame,\\n            method=\\\"search_google\\\",\\n        ),\\n    ]\\n\\n    def search_google(self) -> DataFrame:\\n        \\\"\\\"\\\"Search Google using the provided query.\\\"\\\"\\\"\\n        if not self.google_api_key:\\n            return DataFrame([{\\\"error\\\": \\\"Invalid Google API Key\\\"}])\\n\\n        if not self.google_cse_id:\\n            return DataFrame([{\\\"error\\\": \\\"Invalid Google CSE ID\\\"}])\\n\\n        try:\\n            wrapper = GoogleSearchAPIWrapper(\\n                google_api_key=self.google_api_key, google_cse_id=self.google_cse_id, k=self.k\\n            )\\n            results = wrapper.results(query=self.input_value, num_results=self.k)\\n            return DataFrame(results)\\n        except (ValueError, KeyError) as e:\\n            return DataFrame([{\\\"error\\\": f\\\"Invalid configuration: {e!s}\\\"}])\\n        except ConnectionError as e:\\n            return DataFrame([{\\\"error\\\": f\\\"Connection error: {e!s}\\\"}])\\n        except RuntimeError as e:\\n            return DataFrame([{\\\"error\\\": f\\\"Error occurred while searching: {e!s}\\\"}])\\n\\n    def build(self):\\n        return self.search_google\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/google/src/lfx_google/components/google/google_serper_api_core.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6abab69ee4c266dfca2579f22e6cc22e327c23c68e76d9b8b142c7a1adce0e87\",\"content\":\"from langchain_community.utilities.google_serper import GoogleSerperAPIWrapper\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import IntInput, MultilineInput, Output, SecretStrInput\\nfrom lfx.schema.dataframe import DataFrame\\nfrom lfx.schema.message import Message\\n\\n\\nclass GoogleSerperAPICore(Component):\\n    display_name = \\\"Google Serper API\\\"\\n    description = \\\"Call the Serper.dev Google Search API.\\\"\\n    icon = \\\"Serper\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"serper_api_key\\\",\\n            display_name=\\\"Serper API Key\\\",\\n            required=True,\\n        ),\\n        MultilineInput(\\n            name=\\\"input_value\\\",\\n            display_name=\\\"Input\\\",\\n            tool_mode=True,\\n        ),\\n        IntInput(\\n            name=\\\"k\\\",\\n            display_name=\\\"Number of results\\\",\\n            value=4,\\n            required=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(\\n            display_name=\\\"Results\\\",\\n            name=\\\"results\\\",\\n            type_=DataFrame,\\n            method=\\\"search_serper\\\",\\n        ),\\n    ]\\n\\n    def search_serper(self) -> DataFrame:\\n        try:\\n            wrapper = self._build_wrapper()\\n            results = wrapper.results(query=self.input_value)\\n            list_results = results.get(\\\"organic\\\", [])\\n\\n            # Convert results to DataFrame using list comprehension\\n            df_data = [\\n                {\\n                    \\\"title\\\": result.get(\\\"title\\\", \\\"\\\"),\\n                    \\\"link\\\": result.get(\\\"link\\\", \\\"\\\"),\\n                    \\\"snippet\\\": result.get(\\\"snippet\\\", \\\"\\\"),\\n                }\\n                for result in list_results\\n            ]\\n\\n            return DataFrame(df_data)\\n        except (ValueError, KeyError, ConnectionError) as e:\\n            error_message = f\\\"Error occurred while searching: {e!s}\\\"\\n            self.status = error_message\\n            # Return DataFrame with error as a list of dictionaries\\n            return DataFrame([{\\\"error\\\": error_message}])\\n\\n    def text_search_serper(self) -> Message:\\n        search_results = self.search_serper()\\n        text_result = search_results.to_string(index=False) if not search_results.empty else \\\"No results found.\\\"\\n        return Message(text=text_result)\\n\\n    def _build_wrapper(self):\\n        return GoogleSerperAPIWrapper(serper_api_key=self.serper_api_key, k=self.k)\\n\\n    def build(self):\\n        return self.search_serper\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/google/src/lfx_google/extension.json\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4cc47d100d0c03a44e0ef80f139764ed7d68d5b19859b7113252ea7defe4e5c1\",\"content\":\"{\\n  \\\"$schema\\\": \\\"https://schemas.langflow.org/extension/v1.json\\\",\\n  \\\"id\\\": \\\"lfx-google\\\",\\n  \\\"version\\\": \\\"0.1.2\\\",\\n  \\\"name\\\": \\\"Google\\\",\\n  \\\"description\\\": \\\"Google and Gemini components as a standalone Langflow Extension Bundle.\\\",\\n  \\\"lfx\\\": {\\n    \\\"compat\\\": [\\\"1\\\"]\\n  },\\n  \\\"bundles\\\": [\\n    {\\n      \\\"name\\\": \\\"google\\\",\\n      \\\"path\\\": \\\"components/google\\\"\\n    }\\n  ]\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/google/tests/test_drive_community_migration.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"343d4af1ec64eb3ec18f988611013f3eed8ef8d02a094bc1f29ae237ddfe4cf8\",\"content\":\"\\\"\\\"\\\"Keep the single Google Doc and credential contracts across the provider upgrade.\\\"\\\"\\\"\\n\\nimport json\\nfrom unittest.mock import patch\\n\\nimport pytest\\nfrom google.auth.exceptions import RefreshError\\nfrom langchain_core.documents import Document\\nfrom langchain_google_community import GoogleDriveLoader\\nfrom lfx_google.components.google.google_drive import GoogleDriveComponent\\n\\n\\ndef component():\\n    return GoogleDriveComponent().set(\\n        json_string=json.dumps({\\\"refresh_token\\\": \\\"test\\\", \\\"client_id\\\": \\\"test\\\", \\\"client_secret\\\": \\\"test\\\"}),\\n        document_id=\\\"existing-doc\\\",\\n    )\\n\\n\\ndef test_drive_loads_known_document_without_mime_discovery():\\n    observed = []\\n\\n    def load_document(loader, document_id):\\n        credentials = loader._load_credentials()\\n        observed.append((document_id, credentials.refresh_token))\\n        return Document(page_content=\\\"Saved document\\\", metadata={\\\"source\\\": \\\"existing-doc\\\"})\\n\\n    with (\\n        patch.object(GoogleDriveLoader, \\\"_load_document_from_id\\\", load_document),\\n        patch(\\\"googleapiclient.discovery.build\\\", side_effect=AssertionError(\\\"Unexpected MIME discovery request\\\")),\\n    ):\\n        data = component().load_documents()\\n    assert observed == [(\\\"existing-doc\\\", \\\"test\\\")]\\n    assert data.data[\\\"text\\\"][0].text == \\\"Saved document\\\"\\n    assert data.data[\\\"text\\\"][0].data[\\\"source\\\"] == \\\"existing-doc\\\"\\n\\n\\ndef test_drive_retains_refresh_error_message():\\n    with (\\n        patch.object(GoogleDriveLoader, \\\"_load_document_from_id\\\", side_effect=RefreshError(\\\"expired\\\")),\\n        pytest.raises(ValueError, match=\\\"Authentication error: Unable to refresh authentication token\\\"),\\n    ):\\n        component().load_documents()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/google/tests/test_google_component_regressions.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bb28937cfdead07633e90d235130db16147a3cd2f38d4067e44cc3142d9d19ab\",\"content\":\"import json\\nfrom types import SimpleNamespace\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom google import genai\\nfrom google.auth.exceptions import RefreshError\\nfrom lfx.schema.dotdict import dotdict\\nfrom lfx_google.components.google import (\\n    GmailLoaderComponent,\\n    GoogleDriveSearchComponent,\\n    GoogleGenerativeAIComponent,\\n    GoogleOAuthToken,\\n)\\n\\nTEST_API_KEY = \\\"google-key\\\"  # pragma: allowlist secret\\n\\n\\ndef test_gmail_loader_rejects_non_numeric_max_results() -> None:\\n    component = GmailLoaderComponent()\\n    component.json_string = \\\"{}\\\"\\n    component.label_ids = \\\"INBOX\\\"\\n    component.max_results = \\\"not-a-number\\\"\\n\\n    with pytest.raises(ValueError, match=\\\"Invalid max_results value: not-a-number\\\"):\\n        component.load_emails()\\n\\n\\ndef test_drive_search_rejects_invalid_token_json() -> None:\\n    component = GoogleDriveSearchComponent()\\n    component.token_string = \\\"{invalid\\\"  # noqa: S105\\n\\n    with pytest.raises(ValueError, match=\\\"Invalid JSON string\\\"):\\n        component.search_files()\\n\\n\\ndef test_drive_search_reports_refresh_errors() -> None:\\n    component = GoogleDriveSearchComponent()\\n    component.token_string = \\\"{}\\\"  # noqa: S105\\n    component.query_string = \\\"name contains 'report'\\\"\\n    service = MagicMock()\\n    service.files.return_value.list.return_value.execute.side_effect = RefreshError(\\\"expired\\\")\\n\\n    with (\\n        patch(\\n            \\\"lfx_google.components.google.google_drive_search.Credentials.from_authorized_user_info\\\",\\n            return_value=MagicMock(),\\n        ),\\n        patch(\\\"lfx_google.components.google.google_drive_search.build\\\", return_value=service),\\n        pytest.raises(ValueError, match=\\\"Authentication error: Unable to refresh authentication token\\\"),\\n    ):\\n        component.search_files()\\n\\n\\ndef test_google_model_discovery_uses_api_key_scoped_client() -> None:\\n    component = GoogleGenerativeAIComponent()\\n    component.api_key = TEST_API_KEY\\n    observed_api_keys: list[str] = []\\n\\n    class FakeClient:\\n        def __init__(self, *, api_key: str) -> None:\\n            observed_api_keys.append(api_key)\\n            self.models = SimpleNamespace(\\n                list=lambda: [\\n                    SimpleNamespace(name=\\\"models/gemini-a\\\", supported_actions=[\\\"generateContent\\\"]),\\n                    SimpleNamespace(name=\\\"models/embedding-a\\\", supported_actions=[\\\"embedContent\\\"]),\\n                ]\\n            )\\n\\n        def __enter__(self):\\n            return self\\n\\n        def __exit__(self, exc_type, exc_value, traceback) -> None:\\n            return None\\n\\n    with patch.object(genai, \\\"Client\\\", FakeClient):\\n        model_ids = component.get_models()\\n\\n    assert observed_api_keys == [\\\"google-key\\\"]\\n    assert model_ids == [\\\"gemini-a\\\"]\\n\\n\\ndef test_google_tool_filter_checks_each_candidate_without_skipping() -> None:\\n    component = GoogleGenerativeAIComponent()\\n    component.api_key = TEST_API_KEY\\n\\n    class FakeClient:\\n        def __init__(self, *, api_key: str) -> None:\\n            assert api_key == TEST_API_KEY\\n            self.models = SimpleNamespace(\\n                list=lambda: [\\n                    SimpleNamespace(name=f\\\"models/gemini-{suffix}\\\", supported_actions=[\\\"generateContent\\\"])\\n                    for suffix in (\\\"a\\\", \\\"b\\\", \\\"c\\\")\\n                ]\\n            )\\n\\n        def __enter__(self):\\n            return self\\n\\n        def __exit__(self, exc_type, exc_value, traceback) -> None:\\n            return None\\n\\n    with (\\n        patch.object(genai, \\\"Client\\\", FakeClient),\\n        patch(\\n            \\\"langchain_google_genai.chat_models.ChatGoogleGenerativeAI\\\",\\n            side_effect=lambda **kwargs: SimpleNamespace(model=kwargs[\\\"model\\\"]),\\n        ),\\n        patch.object(\\n            component,\\n            \\\"supports_tool_calling\\\",\\n            side_effect=lambda model: model.model in {\\\"gemini-a\\\", \\\"gemini-c\\\"},\\n        ),\\n    ):\\n        model_ids = component.get_models(tool_model_enabled=True)\\n\\n    assert model_ids == [\\\"gemini-c\\\", \\\"gemini-a\\\"]\\n\\n\\ndef test_google_model_config_handles_no_tool_capable_models() -> None:\\n    component = GoogleGenerativeAIComponent()\\n    component.api_key = TEST_API_KEY\\n    component.tool_model_enabled = True\\n    build_config = dotdict({\\\"model_name\\\": {\\\"value\\\": \\\"gemini-old\\\"}})\\n\\n    with patch.object(component, \\\"get_models\\\", return_value=[]):\\n        updated = component.update_build_config(build_config, field_value=True, field_name=\\\"tool_model_enabled\\\")\\n\\n    assert updated[\\\"model_name\\\"][\\\"options\\\"] == []\\n    assert \\\"value\\\" not in updated[\\\"model_name\\\"]\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"scopes\\\",\\n    [\\n        \\\"https://www.googleapis.com/auth/drive.readonly\\\",\\n        \\\"mail.google.com/\\\",\\n        \\\"mail.google.com/, https://www.googleapis.com/auth/drive.readonly\\\",\\n    ],\\n)\\ndef test_oauth_scope_validation_accepts_separated_scopes(scopes: str) -> None:\\n    GoogleOAuthToken().validate_scopes(scopes)\\n\\n\\ndef test_oauth_scope_validation_rejects_concatenated_scopes() -> None:\\n    scopes = \\\"https://www.googleapis.com/auth/drive.readonlymail.google.com/\\\"\\n\\n    with pytest.raises(ValueError, match=\\\"Invalid scope format\\\"):\\n        GoogleOAuthToken().validate_scopes(scopes)\\n\\n\\ndef test_oauth_returns_credentials_without_shared_token_file() -> None:\\n    component = GoogleOAuthToken()\\n    component.scopes = \\\"https://www.googleapis.com/auth/drive.readonly\\\"\\n    component.oauth_credentials = \\\"/tmp/google-client.json\\\"\\n    credentials = MagicMock()\\n    credentials.to_json.return_value = json.dumps({\\\"token\\\": \\\"test-token\\\"})  # pragma: allowlist secret\\n    flow = MagicMock()\\n    flow.run_local_server.return_value = credentials\\n\\n    with patch(\\n        \\\"lfx_google.components.google.google_oauth_token.InstalledAppFlow.from_client_secrets_file\\\",\\n        return_value=flow,\\n    ) as from_client_secrets_file:\\n        result = component.build_output()\\n\\n    from_client_secrets_file.assert_called_once_with(\\n        \\\"/tmp/google-client.json\\\", [\\\"https://www.googleapis.com/auth/drive.readonly\\\"]\\n    )\\n    flow.run_local_server.assert_called_once_with(port=0, timeout_seconds=300)\\n    assert result.data == {\\\"token\\\": \\\"test-token\\\"}\\n\\n\\ndef test_oauth_reports_callback_failure() -> None:\\n    component = GoogleOAuthToken()\\n    component.scopes = \\\"https://www.googleapis.com/auth/drive.readonly\\\"\\n    component.oauth_credentials = \\\"/tmp/google-client.json\\\"\\n    flow = MagicMock()\\n    flow.run_local_server.side_effect = TimeoutError(\\\"authorization timed out\\\")\\n\\n    with (\\n        patch(\\n            \\\"lfx_google.components.google.google_oauth_token.InstalledAppFlow.from_client_secrets_file\\\",\\n            return_value=flow,\\n        ),\\n        pytest.raises(ValueError, match=\\\"OAuth authorization failed: authorization timed out\\\"),\\n    ):\\n        component.build_output()\\n\\n\\ndef test_oauth_reports_invalid_client_credentials() -> None:\\n    component = GoogleOAuthToken()\\n    component.scopes = \\\"https://www.googleapis.com/auth/drive.readonly\\\"\\n    component.oauth_credentials = \\\"/tmp/google-client.json\\\"\\n\\n    with (\\n        patch(\\n            \\\"lfx_google.components.google.google_oauth_token.InstalledAppFlow.from_client_secrets_file\\\",\\n            side_effect=ValueError(\\\"invalid client credentials\\\"),\\n        ),\\n        pytest.raises(ValueError, match=\\\"OAuth authorization failed: invalid client credentials\\\"),\\n    ):\\n        component.build_output()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/google/tests/test_google_embeddings_provider_policy.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d3fc411285b13f54cdae6808000ca0e29f1bb381a8b542e7578313262b91b37c\",\"content\":\"from types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, Mock\\n\\nimport pytest\\nfrom lfx.services.model_provider_policy import ModelProviderPolicyError, ModelProviderPolicyPurpose\\nfrom lfx_google.components.google.google_generative_ai_embeddings import GoogleGenerativeAIEmbeddingsComponent\\n\\n\\nclass _UnhydratedSecret:\\n    def __bool__(self) -> bool:\\n        raise AssertionError\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"purpose\\\",\\n    [ModelProviderPolicyPurpose.CONFIGURE, ModelProviderPolicyPurpose.USE],\\n)\\nasync def test_google_embeddings_are_gated_as_google_before_secret_hydration(monkeypatch, purpose) -> None:\\n    component = GoogleGenerativeAIEmbeddingsComponent(_user_id=\\\"resource-owner\\\")\\n    denial = ModelProviderPolicyError(\\\"google-generative-ai\\\", purpose)\\n    snapshot = SimpleNamespace(require=Mock(side_effect=denial))\\n    resolve_policy = AsyncMock(return_value=snapshot)\\n    monkeypatch.setattr(\\\"lfx.services.model_provider_policy.aresolve_model_provider_policy\\\", resolve_policy)\\n\\n    with pytest.raises(ModelProviderPolicyError):\\n        await component.arequire_model_provider_policy(\\n            purpose,\\n            user_id=\\\"policy-actor\\\",\\n            parameters={\\\"api_key\\\": _UnhydratedSecret()},\\n        )\\n\\n    assert component.model_provider_id == \\\"google-generative-ai\\\"\\n    resolve_policy.assert_awaited_once_with(\\n        user_id=\\\"policy-actor\\\",\\n        providers=[\\\"google-generative-ai\\\"],\\n        purpose=purpose,\\n    )\\n    snapshot.require.assert_called_once_with(\\\"google-generative-ai\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/google/tests/test_google_generative_ai_model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"723607ab786463c5ca087361a7f82bbdf42c7928b1a306c65726a6a455586432\",\"content\":\"\\\"\\\"\\\"Regression tests for Gemini function-response compatibility in LFX.\\\"\\\"\\\"\\n\\nfrom langchain_core.messages import AIMessage, FunctionMessage, HumanMessage, ToolMessage\\nfrom langchain_google_genai import ChatGoogleGenerativeAI\\nfrom lfx.base.models.google_generative_ai_model import (\\n    ChatGoogleGenerativeAIFixed,\\n    _ensure_function_response_names,\\n    _install_function_response_name_compat,\\n)\\nfrom lfx.base.models.unified_models.class_registry import get_model_class\\nfrom lfx.base.models.unified_models.instantiation import get_llm\\n\\n\\ndef test_request_uses_fallback_name_for_unnamed_tool_response():\\n    model = ChatGoogleGenerativeAIFixed(model=\\\"gemini-2.5-flash\\\", google_api_key=\\\"test-key\\\")\\n    messages = [\\n        HumanMessage(content=\\\"Use the echo tool\\\"),\\n        AIMessage(\\n            content=\\\"\\\",\\n            tool_calls=[{\\\"name\\\": \\\"echo\\\", \\\"args\\\": {\\\"text\\\": \\\"hello\\\"}, \\\"id\\\": \\\"call-1\\\", \\\"type\\\": \\\"tool_call\\\"}],\\n        ),\\n        ToolMessage(content=\\\"hello\\\", tool_call_id=\\\"call-1\\\"),\\n    ]\\n\\n    request = model._prepare_request(messages)\\n\\n    function_response = request[\\\"contents\\\"][-1].parts[0].function_response\\n    assert function_response.name == \\\"tool_response\\\"\\n\\n\\ndef test_ensure_function_response_names_handles_tool_and_function_messages():\\n    tool_message = ToolMessage(content=\\\"tool output\\\", tool_call_id=\\\"call-1\\\")\\n    function_message = FunctionMessage(content=\\\"function output\\\", name=\\\"\\\")\\n    human_message = HumanMessage(content=\\\"hello\\\")\\n\\n    fixed_messages = _ensure_function_response_names([tool_message, function_message, human_message])\\n\\n    assert fixed_messages[0].name == \\\"tool_response\\\"\\n    assert fixed_messages[1].name == \\\"function_response\\\"\\n    assert fixed_messages[2] is human_message\\n    assert tool_message.name is None\\n    assert function_message.name == \\\"\\\"\\n\\n\\ndef test_agent_registry_resolves_compat_class():\\n    assert get_model_class(\\\"ChatGoogleGenerativeAIFixed\\\") is ChatGoogleGenerativeAIFixed\\n\\n\\ndef test_unified_language_model_builds_google_compat_class():\\n    model = get_llm(\\n        [\\n            {\\n                \\\"name\\\": \\\"gemini-2.5-flash\\\",\\n                \\\"provider\\\": \\\"Google Generative AI\\\",\\n                \\\"metadata\\\": {\\n                    \\\"model_class\\\": \\\"ChatGoogleGenerativeAIFixed\\\",\\n                    \\\"model_name_param\\\": \\\"model\\\",\\n                    \\\"api_key_param\\\": \\\"google_api_key\\\",  # pragma: allowlist secret\\n                },\\n            }\\n        ],\\n        user_id=None,\\n        api_key=\\\"test-key\\\",  # pragma: allowlist secret\\n    )\\n\\n    assert type(model) is ChatGoogleGenerativeAIFixed\\n\\n\\ndef test_compat_reuses_parent_pydantic_model_and_defaults():\\n    assert ChatGoogleGenerativeAIFixed is ChatGoogleGenerativeAI\\n    required_fields = {name for name, field in ChatGoogleGenerativeAIFixed.model_fields.items() if field.is_required()}\\n    assert required_fields == {\\\"model\\\"}\\n    assert ChatGoogleGenerativeAIFixed.model_fields[\\\"temperature\\\"].default == 0.7\\n\\n\\ndef test_compat_install_is_idempotent():\\n    request_hook = getattr(ChatGoogleGenerativeAI, \\\"_prepare_request\\\")  # noqa: B009\\n    assert _install_function_response_name_compat() is ChatGoogleGenerativeAI\\n    assert getattr(ChatGoogleGenerativeAI, \\\"_prepare_request\\\") is request_hook  # noqa: B009\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/ibm/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"84d0a956f9badd8cf2a88203e5aabf28c76d31acaa54a6f87dd7a0c25121a8aa\",\"content\":\"# lfx-ibm\\n\\nIBM components \u2014 Db2 Vector Store, watsonx.ai LLM and embeddings, and\\nwatsonx.data Presto and MCP \u2014 as a standalone Langflow Extension Bundle.\\n\\nThis bundle ships five components:\\n\\n* **`DB2VectorStoreComponent`** \u2014 wraps the `DB2VS` LangChain-compatible\\n  vector store and exposes Db2's native vector search through Langflow's\\n  standard vector-store palette entry.\\n* **`WatsonxAIComponent`** \u2014 chat/text-generation against IBM watsonx.ai\\n  foundation models via `langchain-ibm`'s `ChatWatsonx`.\\n* **`WatsonxEmbeddingsComponent`** \u2014 embeddings via watsonx.ai's\\n  `WatsonxEmbeddings` model.\\n* **`WatsonxDataPrestoComponent`** \u2014 run SQL on a watsonx.data Presto engine\\n  (Iceberg lakehouse, federated sources, Confluent Tableflow tables) and get\\n  a DataFrame back; `presto-python-client` DBAPI with `ibmlhapikey` /\\n  IAM-API-key or basic auth and an optional CA bundle.\\n* **`WatsonxDataMCPComponent`** \u2014 a preset MCP toolset for the watsonx.data\\n  remote MCP server (`/api/v2/mcp/`): `LIST_/QUERY_DOCUMENT_LIBRARY`,\\n  `LIST_/QUERY_DOCUMENT_SET`, `LIST_/QUERY_DATA_ASSETS` for an Agent, with\\n  bearer-token or IBM Cloud API-key (IAM exchange) authentication.\\n\\nIt follows the documented porting recipe in\\n[`src/bundles/PORTING.md`](../PORTING.md).\\n\\n## Install\\n\\n```bash\\npip install lfx-ibm\\n```\\n\\nThe bundle is registered automatically via the `langflow.extensions`\\nentry-point. After install, restart your Langflow server; the\\ncomponents appear in the palette under the `ibm` bundle group.\\n\\n> **Platform notes:**\\n> * The `ibm-db` driver does not ship a prebuilt wheel for\\n>   `linux/aarch64`; the dep is gated with a marker so `pip install`\\n>   succeeds on that architecture, but `DB2VectorStoreComponent` will\\n>   fail to build the vector store at runtime there. Use an x86_64 image\\n>   or install `ibm-db` from source if you need Db2 on aarch64.\\n> * `ibm-watsonx-ai` (>=1.5.13) and `langchain-ibm` (>=1.1.0) added Python 3.14\\n>   support upstream, so the watsonx components are importable on every\\n>   supported Python version (3.10-3.14). Earlier releases capped at `<3.14`;\\n>   the bundle pins were bumped to pick up the 3.14-capable builds.\\n\\n## Develop\\n\\n```bash\\ncd src/bundles/ibm\\npip install -e .\\nlfx extension validate src/lfx_ibm\\n```\\n\\n## Manifest\\n\\nThe extension manifest is shipped at `src/lfx_ibm/extension.json` and\\npoints at the bundle at `components/ibm`. Components register under the\\ncanonical namespaced IDs:\\n\\n* `ext:ibm:DB2VectorStoreComponent@official`\\n* `ext:ibm:WatsonxAIComponent@official`\\n* `ext:ibm:WatsonxEmbeddingsComponent@official`\\n* `ext:ibm:WatsonxDataPrestoComponent@official`\\n* `ext:ibm:WatsonxDataMCPComponent@official`\\n\\n## Migration\\n\\nSaved flows referencing the legacy bare class names\\n(`DB2VectorStoreComponent`, `WatsonxAIComponent`,\\n`WatsonxEmbeddingsComponent`) or the old import paths\\n(`lfx.components.ibm.<module>.<Class>` and the package-level\\n`lfx.components.ibm.<Class>` forms) are rewritten to the new namespaced\\nIDs by the migration table in\\n`src/lfx/src/lfx/extension/migration/migration_table.json`.\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/ibm/pyproject.toml\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"232300afc20c727eb4470188f34e0fc6b8a8d641596706caa846bdb6858ac4d4\",\"content\":\"[project]\\nname = \\\"lfx-ibm\\\"\\nversion = \\\"0.2.4\\\"\\ndescription = \\\"IBM components (Db2 Vector Store, watsonx.ai LLM and embeddings, watsonx.data Presto and MCP) as a standalone Langflow Extension Bundle.\\\"\\nreadme = \\\"README.md\\\"\\nrequires-python = \\\">=3.10,<3.15\\\"\\nlicense = { text = \\\"MIT\\\" }\\nauthors = [\\n    { name = \\\"Langflow\\\", email = \\\"contact@langflow.org\\\" },\\n]\\nkeywords = [\\\"langflow\\\", \\\"lfx\\\", \\\"extension\\\", \\\"bundle\\\", \\\"ibm\\\", \\\"db2\\\", \\\"watsonx\\\", \\\"watsonx.data\\\", \\\"presto\\\", \\\"mcp\\\", \\\"vector-store\\\"]\\n\\n# Runtime deps: lfx (the BUNDLE_API surface) plus IBM SDK packages used by\\n# the bundled components.\\n#\\n# * ``ibm-db`` powers the Db2 Vector Store.  Gated with the same platform\\n#   marker we previously used in ``src/lfx/pyproject.toml`` -- the upstream\\n#   wheel does not ship for linux/aarch64, so the dep would otherwise\\n#   break ``pip install`` on that arch.\\n# * ``ibm-watsonx-ai`` and ``langchain-ibm`` power ``WatsonxAIComponent``\\n#   and ``WatsonxEmbeddingsComponent``.  Both upstreams added Python 3.14\\n#   support (``ibm-watsonx-ai`` 1.5.13, ``langchain-ibm`` 1.1.0), so the\\n#   former ``python_version < '3.14'`` markers are lifted.  ``ibm-watsonx-ai``\\n#   raised its floor to ``>=3.11`` on the 3.14-capable build, so the universal\\n#   resolver forks: a 3.14 build on the 3.14 Docker image, an older\\n#   3.10-compatible build elsewhere.  Kept in lockstep with langflow-base.\\n# * ``langchain-core`` provides the document, embedding and vector store interfaces.\\n# * ``presto-python-client`` (``prestodb``) powers ``WatsonxDataPrestoComponent``\\n#   -- the DBAPI client for the Presto engines watsonx.data ships. Pure\\n#   Python (requests-based); the ``trino`` client is header-incompatible with\\n#   watsonx.data Presto, and the SQLAlchemy ``presto://`` dialect needs the\\n#   unmaintained ``pyhive``. ``ibm-cloud-sdk-core`` (already a dep) does the\\n#   IAM API-key -> bearer-token exchange for ``WatsonxDataMCPComponent``.\\ndependencies = [\\n    \\\"lfx>=1.12.0.dev0,<2.0.0\\\",\\n    \\\"langchain-core>=1.2.28,<2.0.0\\\",\\n    \\\"numpy>=1.26.4,<3.0.0\\\",\\n    \\\"ibm-db>=3.2.9,<4.0.0; sys_platform != 'linux' or platform_machine != 'aarch64'\\\",\\n    \\\"ibm-watsonx-ai>=1.3.1,<2.0.0\\\",\\n    \\\"langchain-ibm~=1.1.0\\\",\\n    \\\"ibm-cloud-sdk-core~=3.24.4\\\",\\n    \\\"presto-python-client>=0.8,<1\\\",\\n    \\\"ibm-watsonx-orchestrate-core~=2.12.0; python_version >= '3.11'\\\",\\n    \\\"ibm-watsonx-orchestrate-clients~=2.12.0; python_version >= '3.11'\\\",\\n]\\n\\n[project.urls]\\nHomepage = \\\"https://github.com/langflow-ai/langflow\\\"\\nDocumentation = \\\"https://docs.langflow.org/extensions\\\"\\nRepository = \\\"https://github.com/langflow-ai/langflow\\\"\\n\\n# Manifest-shipping distributions are discovered via the\\n# ``langflow.extensions`` entry-point.  The value is the dotted path to\\n# the package containing ``extension.json`` -- the loader walks\\n# ``importlib.metadata.files()`` from there to find the manifest, and\\n# falls back to this entry-point for editable installs whose dist.files\\n# only surfaces dist-info entries.\\n[project.entry-points.\\\"langflow.extensions\\\"]\\nlfx-ibm = \\\"lfx_ibm\\\"\\n\\n[build-system]\\nrequires = [\\\"hatchling==1.31.0\\\"]\\nbuild-backend = \\\"hatchling.build\\\"\\n\\n[tool.hatch.build.targets.wheel]\\n# extension.json + components live inside the lfx_ibm package so\\n# ``importlib.metadata.files(dist)`` finds them and the loader resolves\\n# bundles[].path relative to the manifest's directory.\\npackages = [\\\"src/lfx_ibm\\\"]\\ninclude = [\\\"src/lfx_ibm/extension.json\\\", \\\"src/lfx_ibm/components/**/*.py\\\"]\\n\\n[tool.hatch.build.targets.sdist]\\ninclude = [\\n    \\\"src/lfx_ibm\\\",\\n    \\\"extension.json\\\",\\n    \\\"README.md\\\",\\n    \\\"pyproject.toml\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/ibm/src/lfx_ibm/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ec70912d82cfac0a567986062a64b3593d1a4965b8413b15e827389bbfda4382\",\"content\":\"\\\"\\\"\\\"lfx-ibm: IBM bundle (Db2 Vector Store, watsonx.ai LLM and embeddings, watsonx.data Presto and MCP).\\n\\nThis package is the distribution unit ``lfx-ibm``.  At runtime\\nLangflow's loader discovers ``extension.json`` shipped alongside this\\n``__init__.py`` and registers the IBM components under the\\nnamespaced IDs:\\n\\n* ``ext:ibm:DB2VectorStoreComponent@official``\\n* ``ext:ibm:WatsonxAIComponent@official``\\n* ``ext:ibm:WatsonxDataMCPComponent@official``\\n* ``ext:ibm:WatsonxDataPrestoComponent@official``\\n* ``ext:ibm:WatsonxEmbeddingsComponent@official``\\n\\nThird pilot port (after lfx-duckduckgo and lfx-arxiv) -- exercises the\\nsame extraction recipe documented in ``src/bundles/PORTING.md`` against\\na multi-component bundle that ships a langchain-community-backed vector\\nstore, the IBM Db2 vendor SDK, and the langchain-ibm watsonx.ai client.\\n\\\"\\\"\\\"\\n\\nfrom lfx_ibm.components.ibm.db2_vector import DB2VectorStoreComponent\\nfrom lfx_ibm.components.ibm.watsonx import WatsonxAIComponent\\nfrom lfx_ibm.components.ibm.watsonx_data_mcp import WatsonxDataMCPComponent\\nfrom lfx_ibm.components.ibm.watsonx_data_presto import WatsonxDataPrestoComponent\\nfrom lfx_ibm.components.ibm.watsonx_embeddings import WatsonxEmbeddingsComponent\\n\\n__all__ = [\\n    \\\"DB2VectorStoreComponent\\\",\\n    \\\"WatsonxAIComponent\\\",\\n    \\\"WatsonxDataMCPComponent\\\",\\n    \\\"WatsonxDataPrestoComponent\\\",\\n    \\\"WatsonxEmbeddingsComponent\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/ibm/src/lfx_ibm/components/ibm/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a962cbfabc273d1c7444dcbbd62b952b0104dce11030c92e98d096d8cd57011b\",\"content\":\"from .db2_vector import DB2VectorStoreComponent\\nfrom .watsonx import WatsonxAIComponent\\nfrom .watsonx_data_mcp import WatsonxDataMCPComponent\\nfrom .watsonx_data_presto import WatsonxDataPrestoComponent\\nfrom .watsonx_embeddings import WatsonxEmbeddingsComponent\\n\\n__all__ = [\\n    \\\"DB2VectorStoreComponent\\\",\\n    \\\"WatsonxAIComponent\\\",\\n    \\\"WatsonxDataMCPComponent\\\",\\n    \\\"WatsonxDataPrestoComponent\\\",\\n    \\\"WatsonxEmbeddingsComponent\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/ibm/src/lfx_ibm/components/ibm/db2_security.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1b7db9ec45d2e4aa504f2234f2f1f7955d8b23b3f32a81c6c2085311a9a2a82b\",\"content\":\"\\\"\\\"\\\"Lightweight validation and safe error helpers for IBM Db2 components.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport contextlib\\nimport os\\nimport re\\nimport tempfile\\nfrom pathlib import Path\\nfrom typing import TYPE_CHECKING\\nfrom urllib.parse import urlparse\\n\\nimport httpx\\nfrom lfx.utils.file_path_security import LocalFileAccessError, enforce_local_file_access\\nfrom lfx.utils.ssrf_httpx import ssrf_safe_httpx_get_bounded\\nfrom lfx.utils.ssrf_protection import SSRFProtectionError\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Iterable\\n\\n_IDENTIFIER_PATTERN = re.compile(r\\\"^[A-Za-z][A-Za-z0-9_]{0,127}$\\\")\\n_HOSTNAME_PATTERN = re.compile(r\\\"^[A-Za-z0-9.-]{1,253}$\\\")\\n\\n# Only these schemes are treated as a downloadable certificate URL. Everything else\\n# with a scheme is rejected outright rather than being reinterpreted as a local path.\\n_DOWNLOADABLE_CERT_SCHEMES = frozenset({\\\"http\\\", \\\"https\\\"})\\n\\n_CERT_DOWNLOAD_TIMEOUT_SECONDS = 30\\n\\n# A PEM/DER certificate chain is a few KB; cap the buffered response so a hostile or\\n# broken endpoint cannot make the server hold an arbitrarily large body in memory.\\n_MAX_CERT_BYTES = 1024 * 1024\\n\\n\\ndef _require_string(value: object, field_name: str) -> str:\\n    \\\"\\\"\\\"Return a stripped string or raise TypeError.\\\"\\\"\\\"\\n    if not isinstance(value, str):\\n        msg = f\\\"Invalid {field_name}: must be a string\\\"\\n        raise TypeError(msg)\\n\\n    cleaned = value.strip()\\n    if not cleaned:\\n        msg = f\\\"Invalid {field_name}: cannot be empty\\\"\\n        raise ValueError(msg)\\n    return cleaned\\n\\n\\n# Maximum length for Db2 database names\\n_MAX_DB_NAME_LENGTH = 128\\n\\n\\ndef validate_database_name(value: object) -> str:\\n    \\\"\\\"\\\"Validate a Db2 database name.\\\"\\\"\\\"\\n    database_name = _require_string(value, \\\"database name\\\")\\n    if len(database_name) > _MAX_DB_NAME_LENGTH:\\n        msg = \\\"Invalid database name: exceeds maximum length\\\"\\n        raise ValueError(msg)\\n    if any(char in database_name for char in ('\\\"', \\\"'\\\", \\\";\\\", \\\"\\\\\\\\\\\", \\\"\\\\n\\\", \\\"\\\\r\\\", \\\"\\\\t\\\")):\\n        msg = \\\"Invalid database name: contains unsafe characters\\\"\\n        raise ValueError(msg)\\n    return database_name\\n\\n\\ndef validate_hostname(value: object) -> str:\\n    \\\"\\\"\\\"Validate a hostname or IP-like address.\\\"\\\"\\\"\\n    hostname = _require_string(value, \\\"hostname\\\")\\n    if any(char in hostname for char in ('\\\"', \\\"'\\\", \\\";\\\", \\\"\\\\\\\\\\\", \\\"/\\\", \\\"?\\\", \\\"#\\\", \\\"\\\\n\\\", \\\"\\\\r\\\", \\\"\\\\t\\\", \\\" \\\")):\\n        msg = \\\"Invalid hostname: contains unsafe characters\\\"\\n        raise ValueError(msg)\\n    if not _HOSTNAME_PATTERN.fullmatch(hostname):\\n        msg = \\\"Invalid hostname: contains unsupported characters\\\"\\n        raise ValueError(msg)\\n    if \\\"..\\\" in hostname or hostname.startswith((\\\".\\\", \\\"-\\\")) or hostname.endswith(\\\".\\\"):\\n        msg = \\\"Invalid hostname: malformed hostname\\\"\\n        raise ValueError(msg)\\n    return hostname\\n\\n\\n# Valid TCP port range\\n_MIN_PORT = 1\\n_MAX_PORT = 65535\\n\\n\\ndef validate_port(value: object) -> int:\\n    \\\"\\\"\\\"Validate a TCP port number.\\\"\\\"\\\"\\n    if isinstance(value, bool) or not isinstance(value, int):\\n        msg = \\\"Invalid port: must be an integer\\\"\\n        raise TypeError(msg)\\n    if value < _MIN_PORT or value > _MAX_PORT:\\n        msg = f\\\"Invalid port: must be between {_MIN_PORT} and {_MAX_PORT}\\\"\\n        raise ValueError(msg)\\n    return value\\n\\n\\ndef validate_identifier(value: object, field_name: str = \\\"identifier\\\") -> str:\\n    \\\"\\\"\\\"Validate a SQL identifier used for table names.\\\"\\\"\\\"\\n    identifier = _require_string(value, field_name)\\n    if not _IDENTIFIER_PATTERN.fullmatch(identifier):\\n        msg = f\\\"Invalid {field_name}: use letters, numbers, and underscores only, starting with a letter\\\"\\n        raise ValueError(msg)\\n    return identifier\\n\\n\\ndef get_quoted_identifier(identifier: str) -> str:\\n    \\\"\\\"\\\"Return a properly quoted SQL identifier for Db2.\\n\\n    Args:\\n        identifier: The identifier to quote (already validated)\\n\\n    Returns:\\n        The quoted identifier safe for SQL queries\\n    \\\"\\\"\\\"\\n    # Db2 uses double quotes for identifiers\\n    # Escape any existing double quotes by doubling them\\n    escaped = identifier.replace('\\\"', '\\\"\\\"')\\n    return f'\\\"{escaped}\\\"'\\n\\n\\ndef sanitize_sql_string(value: str) -> str:\\n    \\\"\\\"\\\"Sanitize a string value for use in SQL queries.\\n\\n    Args:\\n        value: The string value to sanitize\\n\\n    Returns:\\n        The sanitized string with dangerous characters escaped\\n    \\\"\\\"\\\"\\n    # Escape single quotes by doubling them (SQL standard)\\n    return value.replace(\\\"'\\\", \\\"''\\\")\\n\\n\\ndef create_safe_error_message(error: Exception, context: str | None = None) -> str:\\n    \\\"\\\"\\\"Create a sanitized error message without exposing connection details.\\\"\\\"\\\"\\n    error_text = str(error).strip() or \\\"Unknown error\\\"\\n    redacted_text = error_text\\n\\n    sensitive_patterns = [\\n        r\\\"PWD=[^; ]+\\\",\\n        r\\\"PASSWORD=[^; ]+\\\",\\n        r\\\"UID=[^; ]+\\\",\\n        r\\\"USER(ID)?=[^; ]+\\\",\\n        r\\\"HOSTNAME=[^; ]+\\\",\\n        r\\\"DATABASE=[^; ]+\\\",\\n        r\\\"PORT=[^; ]+\\\",\\n    ]\\n    for pattern in sensitive_patterns:\\n        redacted_text = re.sub(pattern, \\\"[REDACTED]\\\", redacted_text, flags=re.IGNORECASE)\\n\\n    prefix = \\\"DB2 operation failed\\\"\\n    if context:\\n        prefix = f\\\"{prefix} {context}\\\"\\n\\n    return f\\\"{prefix}: {redacted_text}\\\"\\n\\n\\ndef validate_ssl_certificate_path(\\n    cert_path: str | None,\\n    *,\\n    scope_ids: Iterable[object] | None = None,\\n) -> tuple[str | None, str | None]:\\n    \\\"\\\"\\\"Validate and resolve SSL certificate path.\\n\\n    ``cert_path`` comes from a tenant-controlled component field, so both branches are\\n    constrained: only ``http``/``https`` URLs are treated as downloadable (any other\\n    scheme is rejected rather than silently falling through to the local-path branch),\\n    and a local path is held inside the caller's storage scope when\\n    ``LANGFLOW_RESTRICT_LOCAL_FILE_ACCESS`` is on.\\n\\n    Args:\\n        cert_path: Path to certificate file (local path or URL), or None\\n        scope_ids: Authenticated user / executing flow ids used for local-path containment.\\n            Only consulted when local-file restriction is enabled (off by default in OSS).\\n\\n    Returns:\\n        Tuple of (resolved_path, error_message)\\n        - If valid: (resolved_path, None)\\n        - If invalid: (None, error_message)\\n        - If None/empty: (None, None) - indicates use system defaults\\n    \\\"\\\"\\\"\\n    if not cert_path or not cert_path.strip():\\n        # Empty path means use system defaults\\n        return None, None\\n\\n    cert_path = cert_path.strip()\\n\\n    # Check if it's a URL\\n    parsed = urlparse(cert_path)\\n    if parsed.scheme in _DOWNLOADABLE_CERT_SCHEMES:\\n        # URL-based certificate - downloaded (and SSRF-validated) later\\n        return cert_path, None\\n\\n    # A multi-character scheme means this is a URL of some other protocol (file://,\\n    # ftp://, gopher://, data:, ...). Those must not fall through to the local-path\\n    # branch. A single-character scheme is a Windows drive letter (``C:\\\\certs\\\\ca.pem``)\\n    # and is a genuine local path.\\n    if len(parsed.scheme) > 1:\\n        return (\\n            None,\\n            f\\\"Unsupported certificate URL scheme: '{parsed.scheme}'. \\\"\\n            f\\\"Expected a local file path or one of: {', '.join(sorted(_DOWNLOADABLE_CERT_SCHEMES))}\\\",\\n        )\\n\\n    # Local file path - validate it exists and is readable\\n    try:\\n        # Resolve path (handles relative paths, ~, etc.)\\n        resolved_path = Path(cert_path).expanduser().resolve()\\n\\n        # Hold the resolved path inside the caller's storage scope before touching the\\n        # filesystem, so a restricted deployment does not leak a file-existence oracle\\n        # for paths it would refuse to read anyway. No-op when restriction is disabled.\\n        resolved_path = enforce_local_file_access(resolved_path, scope_ids=scope_ids)\\n\\n        # Check if file exists\\n        if not resolved_path.exists():\\n            return None, f\\\"Certificate file not found: {cert_path}\\\"\\n\\n        # Check if it's a file (not a directory)\\n        if not resolved_path.is_file():\\n            return None, f\\\"Certificate path is not a file: {cert_path}\\\"\\n\\n        # Check if file is readable\\n        if not os.access(resolved_path, os.R_OK):\\n            return None, f\\\"Certificate file is not readable: {cert_path}\\\"\\n\\n        # Validate file extension\\n        valid_extensions = {\\\".crt\\\", \\\".pem\\\", \\\".cer\\\", \\\".cert\\\"}\\n        if resolved_path.suffix.lower() not in valid_extensions:\\n            return (\\n                None,\\n                f\\\"Invalid certificate file extension: {resolved_path.suffix}. \\\"\\n                f\\\"Expected one of: {', '.join(valid_extensions)}\\\",\\n            )\\n\\n        return str(resolved_path), None\\n\\n    except LocalFileAccessError as e:\\n        return None, str(e)\\n    except (OSError, ValueError) as e:\\n        return None, f\\\"Error validating certificate path: {e}\\\"\\n\\n\\ndef download_certificate(url: str) -> tuple[str | None, str | None]:\\n    \\\"\\\"\\\"Download SSL certificate from URL to temporary file.\\n\\n    The URL is tenant-controlled and a published flow makes this reachable without\\n    authentication, so the fetch is routed through the shared connector SSRF guard\\n    (:func:`lfx.utils.ssrf_httpx.ssrf_safe_httpx_get_bounded`) rather than a raw HTTP client.\\n    That guard validates the host against the internal-network policy and pins the\\n    connection to the validated IPs. Redirects are followed by the guard itself so\\n    that *every* hop is re-validated -- a first-hop-only check is defeated by an\\n    attacker-controlled redirector that bounces to an internal address.\\n\\n    Args:\\n        url: URL to download certificate from\\n\\n    Returns:\\n        Tuple of (temp_file_path, error_message)\\n        - If successful: (temp_file_path, None)\\n        - If failed: (None, error_message)\\n    \\\"\\\"\\\"\\n    try:\\n        # Bounded stream rather than a buffered read: a hostile endpoint that passes SSRF\\n        # validation could still answer with an unbounded body, and measuring it after the\\n        # fact has already paid the memory cost. The transfer is abandoned past the cap.\\n        cert_data = ssrf_safe_httpx_get_bounded(\\n            url,\\n            max_bytes=_MAX_CERT_BYTES,\\n            follow_redirects=True,\\n            timeout=_CERT_DOWNLOAD_TIMEOUT_SECONDS,\\n        )\\n    except SSRFProtectionError as e:\\n        return None, f\\\"SSRF Protection: refusing to download certificate from {url}: {e}\\\"\\n    except httpx.HTTPError as e:\\n        return None, f\\\"Failed to download certificate from {url}: {e}\\\"\\n    except (OSError, ValueError) as e:\\n        # validate_and_resolve_connector_url raises ValueError on a malformed URL, and the\\n        # bounded reader raises it when the body passes _MAX_CERT_BYTES.\\n        return None, f\\\"Failed to download certificate from {url}: {e}\\\"\\n\\n    # Create temporary file with appropriate extension\\n    try:\\n        temp_fd, temp_path = tempfile.mkstemp(suffix=\\\".crt\\\", prefix=\\\"db2_ssl_\\\")\\n    except OSError as e:\\n        return None, f\\\"Error setting up certificate download: {e}\\\"\\n\\n    try:\\n        with os.fdopen(temp_fd, \\\"wb\\\") as f:\\n            f.write(cert_data)\\n    except OSError as write_error:\\n        # ``os.fdopen`` owns the descriptor once it returns, and the ``with`` block closes\\n        # it on the way out -- so only the file itself needs cleaning up here. (Explicitly\\n        # closing the fd again could close an unrelated descriptor that reused the number.)\\n        with contextlib.suppress(OSError):\\n            Path(temp_path).unlink(missing_ok=True)\\n        return None, f\\\"Failed to download certificate from {url}: {write_error}\\\"\\n\\n    return temp_path, None\\n\\n\\ndef validate_and_prepare_ssl_certificate(\\n    cert_path: str | None,\\n    *,\\n    scope_ids: Iterable[object] | None = None,\\n) -> tuple[str | None, bool, str | None]:\\n    \\\"\\\"\\\"Validate and prepare SSL certificate for use.\\n\\n    Args:\\n        cert_path: Path to certificate file (local path or URL), or None\\n        scope_ids: Authenticated user / executing flow ids used for local-path containment.\\n            Callers should pass ``component_file_access_scopes(self)``.\\n\\n    Returns:\\n        Tuple of (resolved_path, is_temp_file, error_message)\\n        - resolved_path: Path to use for SSL connection (None means use system defaults)\\n        - is_temp_file: True if the file is temporary and should be cleaned up\\n        - error_message: Error message if validation failed, None otherwise\\n    \\\"\\\"\\\"\\n    if not cert_path or not cert_path.strip():\\n        # No certificate provided - use system defaults\\n        return None, False, None\\n\\n    # First validate the path/URL\\n    validated_path, error = validate_ssl_certificate_path(cert_path, scope_ids=scope_ids)\\n    if error";
